class AIBehaviorTree:
    def __init__(self, robot: Robot, game_state: GameState):
        self.robot = robot
        self.game_state = game_state
        self.blackboard = {}
        self.reset_blackboard()

    def reset_blackboard(self):
        self.blackboard = {
            "enemy_targets": [],
            "ally_targets": [],
            "current_objective": None,
            "last_known_enemy": None,
            "path_to_objective": [],
            "is_in_danger": False,
            "is_low_health": False,
            "is_low_energy": False,
            "need_support": False,
            "role_specific_task": None
        }

    def update_blackboard(self):
        """Update the AI's perception of the world"""
        self.blackboard["enemy_targets"] = [
            r for r in self.game_state.robots 
            if r.is_alive and r.team != self.robot.team and 
            self.robot.position.distance_to(r.position) <= self.robot.vision_range
        ]

        self.blackboard["ally_targets"] = [
            r for r in self.game_state.robots 
            if r.is_alive and r.team == self.robot.team and r.id != self.robot.id
        ]

        # Check status
        self.blackboard["is_low_health"] = self.robot.health < Config.ROBOT_HEALTH * 0.3
        self.blackboard["is_low_energy"] = self.robot.energy < Config.ROBOT_MAX_ENERGY * 0.2
        self.blackboard["need_support"] = len(self.blackboard["enemy_targets"]) > 2 and self.robot.role != RobotRole.DEFENDER

        # Find active objectives
        active_objectives = [
            obj for obj in self.game_state.objectives 
            if obj.is_active and obj.team != self.robot.team
        ]

        if active_objectives:
            # Prioritize objectives by distance and importance
            closest_obj = min(active_objectives, key=lambda obj: self.robot.position.distance_to(obj.position))
            self.blackboard["current_objective"] = closest_obj

            # If escort objective, find payload target
            if closest_obj.type == ObjectiveType.ESCAPE_PAYLOAD and closest_obj.target:
                self.blackboard["path_to_objective"] = [closest_obj.target]
            else:
                self.blackboard["path_to_objective"] = [closest_obj.position]

        # Check for nearby enemies
        if self.blackboard["enemy_targets"]:
            self.blackboard["last_known_enemy"] = min(
                self.blackboard["enemy_targets"], 
                key=lambda r: self.robot.position.distance_to(r.position)
            )

        # Determine danger
        self.blackboard["is_in_danger"] = len(self.blackboard["enemy_targets"]) >= 2

    def select_action(self) -> str:
        """Select the best action based on the AI's role and current state"""
        self.update_blackboard()

        # Role-based behavior priorities
        if self.robot.role == RobotRole.ATTACKER:
            return self._attacker_behavior()
        elif self.robot.role == RobotRole.DEFENDER:
            return self._defender_behavior()
        elif self.robot.role == RobotRole.SUPPORT:
            return self._support_behavior()
        elif self.robot.role == RobotRole.Scout:
            return self._scout_behavior()
        else:  # CONTROLLER
            return self._controller_behavior()

    def _attacker_behavior(self) -> str:
        if self.blackboard["is_low_health"]:
            return "retreat"

        if self.blackboard["enemy_targets"]:
            # Attack the closest enemy
            target = self.blackboard["last_known_enemy"]
            if target and self.robot.can_attack(time.time()):
                return f"attack_{target.id}"
            else:
                return "move_to_enemy"

        # If no enemies, go for objective
        if self.blackboard["current_objective"]:
            return "move_to_objective"

        # Patrol or roam
        return "patrol"

    def _defender_behavior(self) -> str:
        # Defenders prioritize protecting objectives
        if self.blackboard["current_objective"] and self.blackboard["current_objective"].team == self.robot.team:
            # Defend our own objective
            return "defend_objective"

        # If an enemy is near our objective, engage
        for obj in self.game_state.objectives:
            if obj.team == self.robot.team and obj.is_active:
                nearby_enemies = [r for r in self.blackboard["enemy_targets"] 
                                if r.position.distance_to(obj.position) < obj.radius + 100]
                if nearby_enemies:
                    return f"attack_{nearby_enemies[0].id}"

        # Otherwise, move toward the nearest objective
        if self.blackboard["current_objective"]:
            return "move_to_objective"

        return "patrol"

