class CyberArena:
    def __init__(self):
        self.game_state = GameState()
        self.initialize_game()
        self.last_time = time.time()
        self.running = True
        self.ai_systems = {}

        # Initialize pygame for visualization
        pygame.init()
        self.screen = pygame.display.set_mode((Config.WORLD_WIDTH, Config.WORLD_HEIGHT))
        pygame.display.set_caption("CyberArena - AI Robot Battle Arena")
        self.clock = pygame.time.Clock()

        # Initialize fonts
        self.font = pygame.font.SysFont('Arial', 16)

        # Audio setup
        pygame.mixer.init()
        self.sounds = {
            'shoot': self._load_sound('shoot.wav'),
            'explosion': self._load_sound('explosion.wav'),
            'pickup': self._load_sound('pickup.wav'),
            'objective_complete': self._load_sound('objective_complete.wav'),
            'team_win': self._load_sound('team_win.wav'),
        }

    def _load_sound(self, filename: str) -> Optional[pygame.mixer.Sound]:
        """Placeholder for sound loading - in real implementation, load actual audio files"""
        return None

    def initialize_game(self):
        """Initialize the game world with robots, objectives, power-ups, and hazards"""
        # Spawn robots
        team_count = 4  # 2 per team
        for i in range(team_count):
            # Red team
            robot = Robot(
                id=i,
                team=Team.RED,
                position=Vector2D(
                    random.randint(100, Config.WORLD_WIDTH // 2 - 100),
                    random.randint(100, Config.WORLD_HEIGHT - 100)
                ),
                role=random.choice(list(RobotRole))
            )
            self.game_state.robots.append(robot)

        for i in range(team_count, team_count * 2):
            # Blue team
            robot = Robot(
                id=i,
                team=Team.BLUE,
                position=Vector2D(
                    random.randint(Config.WORLD_WIDTH // 2 + 100, Config.WORLD_WIDTH - 100),
                    random.randint(100, Config.WORLD_HEIGHT - 100)
                ),
                role=random.choice(list(RobotRole))
            )
            self.game_state.robots.append(robot)

        # Spawn objectives
        # Capture flag
        flag = Objective(
            type=ObjectiveType.CAPTURE_FLAG,
            position=Vector2D(Config.WORLD_WIDTH // 4, Config.WORLD_HEIGHT // 2),
            team=Team.RED
        )
        self.game_state.objectives.append(flag)

        flag2 = Objective(
            type=ObjectiveType.CAPTURE_FLAG,
            position=Vector2D(Config.WORLD_WIDTH * 3 // 4, Config.WORLD_HEIGHT // 2),
            team=Team.BLUE
        )
        self.game_state.objectives.append(flag2)

        # Escort payload
        payload = Objective(
            type=ObjectiveType.ESCAPE_PAYLOAD,
            position=Vector2D(Config.WORLD_WIDTH // 2, 100),
            team=Team.RED,
            target=Vector2D(Config.WORLD_WIDTH // 2, Config.WORLD_HEIGHT - 100)
        )
        self.game_state.objectives.append(payload)

        # Spawn power-ups
        for _ in range(5):
            powerup_type = random.choice(list(PowerUpType))
            powerup = PowerUp(
                type=powerup_type,
                position=Vector2D(
                    random.randint(50, Config.WORLD_WIDTH - 50),
                    random.randint(50, Config.WORLD_HEIGHT - 50)
                ),
                spawn_time=time.time()
            )
            self.game_state.powerups.append(powerup)

        # Spawn hazards
        for _ in range(3):
            hazard_type = random.choice(list(HazardType))
            hazard = Hazard(
                type=hazard_type,
                position=Vector2D(
                    random.randint(100, Config.WORLD_WIDTH - 100),
                    random.randint(100, Config.WORLD_HEIGHT - 100)
                ),
                radius=60,
                damage_per_second=20,
                color=self._hazard_color(hazard_type)
            )
            self.game_state.hazards.append(hazard)

        # Initialize AI systems for each robot
        for robot in self.game_state.robots:
            self.ai_systems[robot.id] = AIBehaviorTree(robot, self.game_state)

        self.game_state.round_start_time = time.time()

    def _hazard_color(self, hazard_type: HazardType) -> Tuple[int, int, int]:
        colors = {
            HazardType.LAVA: (255, 69, 0),
            HazardType.ELECTRIC_FIELD: (135, 206, 250),
            HazardType.MINEFIELD: (139, 69, 19),
            HazardType.BLACK_HOLE: (10, 10, 10)
        }
        return colors.get(hazard_type, (255, 100, 100))

    def update(self, dt: float):
        """Update game state"""
        current_time = time.time()
        self.game_state.game_time += dt

        # Update AI for each robot
        for robot in self.game_state.robots:
            if robot.is_alive:
                # Get AI decision
                ai_system = self.ai_systems[robot.id]
                action = ai_system.select_action()
                _, target = ai_system.execute_action(action)

                # Update robot position
                if target:
                    # This is handled in execute_action, but we ensure position is updated
                    robot.move_towards(target, dt)

                # Update particle effects
                robot.update_particles(dt)

                # Apply power-up effects
                if robot.memory.get("speed_boost_end", 0) < current_time:
                    robot.speed = Config.ROBOT_SPEED
                    robot.memory["speed_boost_end"] = 0

                if robot.memory.get("shield_end", 0) < current_time:
                    robot.memory["shield"] = False
                    robot.memory["shield_end"] = 0

                if robot.memory.get("weapon_upgrade_end", 0) < current_time:
                    robot.weapon.damage -= 10
                    robot.weapon.range -= 50
                    robot.memory["weapon_upgrade_end"] = 0
                    robot.weapon.damage = max(robot.weapon.damage, 25)
                    robot.weapon.range = max(robot.weapon.range, Config.RANGED_RANGE)

                if robot.memory.get("silence_end", 0) < current_time:
                    robot.memory["silenced"] = False
                    robot.memory["silence_end"] = 0

        # Update objectives
        for obj in self.game_state.objectives[:]:
            if obj.is_active:
                completed = obj.update(dt, self.game_state.robots)
                if completed:
                    obj.is_active = False
                    self.game_state.objectives_completed[obj.type] += 1
                    self.game_state.team_scores[obj.captured_by] += Config.SCORE_OBJECTIVE
                    # Play objective complete sound
                    if self.sounds.get('objective_complete'):
                        self.sounds['objective_complete'].play()

                    # Add learning data
                    self.game_state.learning_data.append({
                        "timestamp": current_time,
                        "objective": obj.type,
                        "team": obj.captured_by,
                        "robots_involved": [r.id for r in self.game_state.robots 
                                          if r.team == obj.captured_by and r.is_alive]
                    })

                    # Spawn new objective
                    new_obj_type = random.choice(list(ObjectiveType))
                    new_obj_team = random.choice([Team.RED, Team.BLUE])
                    new_obj_pos = Vector2D(
                        random.randint(100, Config.WORLD_WIDTH - 100),
                        random.randint(100, Config.WORLD_HEIGHT - 100)
                    )
                    new_obj = Objective(
                        type=new_obj_type,
                        position=new_obj_pos,
                        team=new_obj_team
                    )
                    if new_obj_type == ObjectiveType.ESCAPE_PAYLOAD:
                        new_obj.target = Vector2D(
                            random.randint(100, Config.WORLD_WIDTH - 100),
                            random.randint(100, Config.WORLD_HEIGHT - 100)
                        )
                    self.game_state.objectives.append(new_obj)

        # Update power-ups
        for powerup in self.game_state.powerups[:]:
            if powerup.active:
                for robot in self.game_state.robots:
                    if robot.is_alive and robot.position.distance_to(powerup.position) < 40:
                        powerup.apply_effect(robot)
                        powerup.active = False
                        robot.add_particle_effect("powerup", 2.0, (255, 215, 0))
                        if self.sounds.get('pickup'):
                            self.sounds['pickup'].play()

                        # Add learning data for power-up usage
                        self.game_state.learning_data.append({
                            "timestamp": current_time,
                            "powerup": powerup.type,
                            "robot": robot.id,
                            "team": robot.team
                        })

        # Remove inactive power-ups after a while
        self.game_state.powerups = [p for p in self.game_state.powerups if p.active]

        # Spawn new power-ups periodically
        if current_time - self.game_state.last_powerup_spawn > Config.POWERUP_SPAWN_INTERVAL:
            powerup_type = random.choice(list(PowerUpType))
            powerup = PowerUp(
                type=powerup_type,
                position=Vector2D(
                    random.randint(50, Config.WORLD_WIDTH - 50),
                    random.randint(50, Config.WORLD_HEIGHT - 50)
                ),
                spawn_time=current_time
            )
            self.game_state.powerups.append(powerup)
            self.game_state.last_powerup_spawn = current_time

        # Update hazards
        for hazard in self.game_state.hazards:
            if hazard.active:
                for robot in self.game_state.robots:
                    if robot.is_alive:
                        damage = hazard.affect_robot(robot)
                        if damage > 0:
                            robot.add_particle_effect("hazard", 1.0, hazard.color)
                            # Add learning data for hazard interaction
                            self.game_state.learning_data.append({
                                "timestamp": current_time,
                                "hazard": hazard.type,
                                "robot": robot.id,
                                "team": robot.team,
                                "damage": damage
                            })

        # Check for robot deaths and update scores
        for robot in self.game_state.robots:
            if not robot.is_alive:
                # Find who killed this robot
                killer = None
                for other_robot in self.game_state.robots:
                    if other_robot.team != robot.team and other_robot.is_alive:
                        # Check if they shot recently
                        if (current_time - other_robot.last_shot_time) < 1.0:
                            killer = other_robot
                            break

                if killer:
                    self.game_state.team_scores[killer.team] += Config.SCORE_KILL
                    # Add assist for teammates nearby
                    for ally in self.game_state.robots:
                        if ally.team == killer.team and ally.id != killer.id and ally.is_alive:
                            if robot.position.distance_to(ally.position) < 150:
                                self.game_state.team_scores[ally.team] += Config.SCORE_ASSIST
                else:
                    # Death by hazard or other causes
                    pass

