@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def copy(self):
        return Vector2D(self.x, self.y)

@dataclass
class Weapon:
    type: WeaponType
    damage: int
    range: float
    cooldown: float
    ammo: int = -1  # -1 means infinite ammo
    max_ammo: int = 100
    fire_rate: float = 1.0  # shots per second
    name: str = "Weapon"

@dataclass
class Robot:
    id: int
    team: Team
    position: Vector2D
    health: int = Config.ROBOT_HEALTH
    energy: int = Config.ROBOT_MAX_ENERGY
    role: RobotRole = RobotRole.ATTACKER
    weapon: Weapon = field(default_factory=lambda: Weapon(
        type=WeaponType.RANGED, damage=25, range=Config.RANGED_RANGE, cooldown=Config.RANGED_COOLDOWN, name="Plasma Rifle"))
    speed: float = Config.ROBOT_SPEED
    last_action_time: float = 0.0
    last_shot_time: float = 0.0
    is_alive: bool = True
    objectives: List[ObjectiveType] = field(default_factory=list)
    memory: Dict[str, Any] = field(default_factory=dict)  # For learning and adaptation
    skills: Dict[str, float] = field(default_factory=dict)  # Skill proficiency
    particle_effects: List[Dict] = field(default_factory=list)
    vision_range: float = 400.0

    def __post_init__(self):
        # Initialize skills if not present
        if not self.skills:
            self.skills = {
                "aiming": 0.7,
                "movement": 0.7,
                "tactical": 0.7,
                "teamwork": 0.7
            }

    def take_damage(self, damage: int) -> bool:
        self.health -= damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
        return self.is_alive

    def heal(self, amount: int):
        self.health = min(self.health + amount, Config.ROBOT_HEALTH)

    def use_energy(self, amount: int):
        self.energy = max(0, self.energy - amount)

    def restore_energy(self, amount: int):
        self.energy = min(self.energy + amount, Config.ROBOT_MAX_ENERGY)

    def can_attack(self, current_time: float) -> bool:
        return current_time - self.last_shot_time >= self.weapon.cooldown

    def shoot(self, target: Vector2D, current_time: float) -> bool:
        if not self.can_attack(current_time) or self.energy < 10:
            return False

        self.last_shot_time = current_time
        self.use_energy(10)
        return True

    def move_towards(self, target: Vector2D, dt: float) -> Vector2D:
        if not self.is_alive:
            return self.position

        direction = (target - self.position).normalize()
        movement = direction * (self.speed * dt)
        new_pos = self.position + movement

        # Boundary checking
        new_pos.x = max(0, min(new_pos.x, Config.WORLD_WIDTH))
        new_pos.y = max(0, min(new_pos.y, Config.WORLD_HEIGHT))

        self.position = new_pos
        return self.position

    def add_particle_effect(self, effect_type: str, duration: float, color: Tuple[int, int, int]):
        self.particle_effects.append({
            'type': effect_type,
            'life': duration,
            'color': color,
            'position': self.position.copy()
        })

    def update_particles(self, dt: float):
        for particle in self.particle_effects[:]:
            particle['life'] -= dt
            if particle['life'] <= 0:
                self.particle_effects.remove(particle)

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team: Team
    progress: float = 0.0
    is_active: bool = True
    target: Optional[Vector2D] = None  # For escort objectives
    captured_by: Optional[Team] = None
    capture_timer: float = 0.0
    radius: float = 50.0

    def update(self, dt: float, robots: List[Robot]) -> bool:
        """Update objective state and return True if completed"""
        if not self.is_active:
            return False

        if self.type == ObjectiveType.CAPTURE_FLAG:
            # Check for robot proximity and capture progress
            nearby_robots = [r for r in robots if r.is_alive and r.team != self.team and 
                           self.position.distance_to(r.position) <= self.radius]

            if nearby_robots:
                # Capture progress based on number of robots and their skill
                total_skill = sum(r.skills["tactical"] for r in nearby_robots)
                progress_rate = (len(nearby_robots) * total_skill / len(nearby_robots)) * 0.1 * dt
                self.progress += progress_rate

                if self.progress >= 1.0:
                    self.captured_by = nearby_robots[0].team
                    return True
            else:
                # Slowly reset capture if no one is near
                self.progress = max(0, self.progress - 0.02 * dt)
                self.captured_by = None

        elif self.type == ObjectiveType.ESCAPE_PAYLOAD:
            if self.target:
                # Move payload towards target
                direction = (self.target - self.position).normalize()
                move_dist = Config.PAYLOAD_SPEED * dt
                self.position = self.position + direction * move_dist

                # Check if payload reached target
                if self.position.distance_to(self.target) < 10:
                    return True

        return False

