    def reset_blackboard(self):
        self.blackboard = {
            "enemy_targets": [],
            "ally_targets": [],
            "current_objective": None,
            "last_known_enemy": None,
            "path_to_objective": [],
            "is_in_danger": False,
            "is_low_health": False,
