        elif self.robot.role == RobotRole.Scout:
            return self._scout_behavior()
        else:  # CONTROLLER
            return self._controller_behavior()

    def _attacker_behavior(self) -> str:
        if self.blackboard["is_low_health"]:
            return "retreat"

        if self.blackboard["enemy_targets"]:
            # Attack the closest enemy
            target = self.blackboard["last_known_enemy"]
            if target and self.robot.can_attack(time.time()):
                return f"attack_{target.id}"
            else:
                return "move_to_enemy"

        # If no enemies, go for objective
        if self.blackboard["current_objective"]:
            return "move_to_objective"

        # Patrol or roam
        return "patrol"

    def _defender_behavior(self) -> str:
        # Defenders prioritize protecting objectives
        if self.blackboard["current_objective"] and self.blackboard["current_objective"].team == self.robot.team:
            # Defend our own objective
            return "defend_objective"

        # If an enemy is near our objective, engage
        for obj in self.game_state.objectives:
            if obj.team == self.robot.team and obj.is_active:
                nearby_enemies = [r for r in self.blackboard["enemy_targets"] 
                                if r.position.distance_to(obj.position) < obj.radius + 100]
                if nearby_enemies:
                    return f"attack_{nearby_enemies[0].id}"

        # Otherwise, move toward the nearest objective
        if self.blackboard["current_objective"]:
            return "move_to_objective"

        return "patrol"

    def _support_behavior(self) -> str:
        # Support robots heal and buff allies
        if self.blackboard["is_low_energy"]:
            # Look for powerups
            powerup = self._find_nearest_powerup()
            if powerup:
                return f"collect_{powerup.type.name}"

        if self.blackboard["ally_targets"]:
            # Find the most injured ally
            injured_ally = min(
                self.blackboard["ally_targets"],
                key=lambda r: r.health,
                default=None
            )
            if injured_ally and injured_ally.health < Config.ROBOT_HEALTH * 0.7:
                return f"heal_{injured_ally.id}"

            # Find allies under attack
            under_attack = [r for r in self.blackboard["ally_targets"] 
                          if any(r.position.distance_to(e.position) < 100 for e in self.blackboard["enemy_targets"])]
            if under_attack:
                return f"assist_{under_attack[0].id}"

        # If no allies need help, support the objective
        if self.blackboard["current_objective"]:
            return "move_to_objective"

        return "patrol"

    def _scout_behavior(self) -> str:
        # Scouts prioritize reconnaissance
        if self.blackboard["enemy_targets"]:
            # Report enemies to team
            # This will be handled in the communication system
            pass

        # Move to high ground or flanking positions
        # For simplicity, move toward enemy base or objective
        if self.blackboard["current_objective"]:
            return "move_to_objective"

        # Roam to explore map
        return "explore"

    def _controller_behavior(self) -> str:
        # Controllers coordinate team efforts
        if self.blackboard["ally_targets"] and self.blackboard["enemy_targets"]:
            # Coordinate attack on enemy
            return "coordinate_attack"

        if self.blackboard["current_objective"] and self.blackboard["current_objective"].team != self.robot.team:
            # Lead the charge on enemy objective
            return "lead_objective_capture"

        # Stay near objectives and support
        return "support_objective"

    def _find_nearest_powerup(self) -> Optional[PowerUp]:
        if not self.game_state.powerups:
            return None

        nearest = min(
            self.game_state.powerups,
            key=lambda p: self.robot.position.distance_to(p.position),
            default=None
        )
        if nearest and nearest.active:
            return nearest
        return None

    def execute_action(self, action: str) -> Tuple[str, Optional[Vector2D]]:
        """Execute the selected action and return result"""
        if action.startswith("attack_"):
            enemy_id = int(action.split("_")[1])
            enemy_robot = next((r for r in self.game_state.robots if r.id == enemy_id and r.is_alive), None)
            if enemy_robot and self.robot.can_attack(time.time()):
                self.robot.shoot(enemy_robot.position, time.time())
                return "attack", enemy_robot.position
            return "failed_attack", None

        elif action == "move_to_enemy" and self.blackboard["last_known_enemy"]:
            target = self.blackboard["last_known_enemy"].position
            self.robot.move_towards(target, 1/60)  # Assuming 60fps
            return "move", target

        elif action == "move_to_objective" and self.blackboard["current_objective"]:
            target = self.blackboard["current_objective"].position
            self.robot.move_towards(target, 1/60)
            return "move", target

        elif action == "defend_objective":
            # Defend the closest allied objective
            allied_obj = next((obj for obj in self.game_state.objectives 
                              if obj.team == self.robot.team and obj.is_active), None)
            if allied_obj:
                self.robot.move_towards(allied_obj.position, 1/60)
                return "move", allied_obj.position

        elif action == "patrol":
            # Patrol a random point
            patrol_point = Vector2D(
                random.randint(100, Config.WORLD_WIDTH - 100),
                random.randint(100, Config.WORLD_HEIGHT - 100)
            )
            self.robot.move_towards(patrol_point, 1/60)
            return "move", patrol_point

        elif action == "retreat":
            # Retreat from enemies
            if self.blackboard["enemy_targets"]:
                # Move in opposite direction of nearest enemy
                enemy = self.blackboard["last_known_enemy"]
                escape_direction = (self.robot.position - enemy.position).normalize()
                retreat_point = self.robot.position + escape_direction * 100
                self.robot.move_towards(retreat_point, 1/60)
                return "move", retreat_point
            return "failed_retreat", None

        elif action == "collect_health_pack":
            # Find and collect health pack
            health_pack = next((p for p in self.game_state.powerups 
                              if p.type == PowerUpType.HEALTH_PACK and p.active), None)
            if health_pack:
                self.robot.move_towards(health_pack.position, 1/60)
                return "move", health_pack.position
            return "failed_collect", None

        elif action.startswith("heal_"):
            ally_id = int(action.split("_")[1])
            ally = next((r for r in self.game_state.robots if r.id == ally_id and r.is_alive), None)
            if ally and self.robot.position.distance_to(ally.position) < 100:
                # Heal ally (simulated)
                ally.heal(15)
                self.robot.use_energy(20)
                return "heal", ally.position
            return "failed_heal", None

        elif action.startswith("assist_"):
            ally_id = int(action.split("_")[1])
            ally = next((r for r in self.game_state.robots if r.id == ally_id and r.is_alive), None)
            if ally:
                # Move to assist
                self.robot.move_towards(ally.position, 1/60)
                return "move", ally.position
            return "failed_assist", None

        elif action == "explore":
            # Explore randomly
            explore_point = Vector2D(
                random.randint(50, Config.WORLD_WIDTH - 50),
                random.randint(50, Config.WORLD_HEIGHT - 50)
            )
            self.robot.move_towards(explore_point, 1/60)
            return "move", explore_point

        elif action == "coordinate_attack":
            # Coordinate with teammates
            # For now, just move toward objective
            if self.blackboard["current_objective"]:
                target = self.blackboard["current_objective"].position
                self.robot.move_towards(target, 1/60)
                return "move", target
            return "wait", None

        elif action == "lead_objective_capture":
            if self.blackboard["current_objective"]:
                target = self.blackboard["current_objective"].position
                self.robot.move_towards(target, 1/60)
                return "move", target
            return "wait", None

        elif action == "support_objective":
            # Support the nearest objective
            obj = next((o for o in self.game_state.objectives if o.is_active), None)
            if obj:
                self.robot.move_towards(obj.position, 1/60)
                return "move", obj.position
            return "wait", None

        return "wait", None

