class RealTimeManager:
    def __init__(self):
        self.subscribers: Dict[str, queue.Queue] = {}
        self.lock = threading.Lock()

    def subscribe(self, player_id: str):
        with self.lock:
            self.subscribers[player_id] = queue.Queue()

    def unsubscribe(self, player_id: str):
        with self.lock:
            if player_id in self.subscribers:
                del self.subscribers[player_id]

    def broadcast(self, event: Dict):
        with self.lock:
            for q in self.subscribers.values():
                q.put(event)

    def send_to_player(self, player_id: str, event: Dict):
        with self.lock:
            if player_id in self.subscribers:
                self.subscribers[player_id].put(event)

    def get_updates(self, player_id: str) -> Optional[Dict]:
        with self.lock:
            if player_id in self.subscribers:
                try:
                    return self.subscribers[player_id].get_nowait()
                except queue.Empty:
                    return None
        return None

