    def get_player_stats(self, player_id: str) -> Dict:
        player = self.get_player(player_id)
        if not player:
            return {}
        games_played = sum(1 for game in self.games.values() if player_id in game.players)
        avg_score = sum(p.score for p in self.players.values() if p.team_id and p.player_id == player_id) / max(1, games_played)
        return {
            "games_played": games_played,
            "avg_score": avg_score,
            "strategy_insights": player.strategy_insights,
            "win_rate": self._compute_win_rate_for_player(player_id)
        }

    def _compute_win_rate_for_player(self, player_id: str) -> float:
        total_games = 0
        wins = 0
        for game in self.games.values():
            if player_id in game.players:
                total_games += 1
                if game.state == GameState.FINISHED:
                    winner_team = self._determine_winner(game)
                    if winner_team and game.players[player_id].team_id == winner_team:
                        wins += 1
        return wins / max(1, total_games)

    def _determine_winner(self, game: GameSession) -> Optional[str]:
        if not game.teams:
            return None
        max_score = max(team.score for team in game.teams.values())
        winners = [team_id for team_id, team in game.teams.items() if team.score == max_score]
        return winners[0] if len(winners) == 1 else None

    def get_team_strategy_trends(self, team_id: str) -> Dict:
        team = self.get_team(team_id)
        if not team:
            return {}
        trends = {
            "total_turns": len(team.strategy_history),
            "successful_moves": sum(1 for h in team.strategy_history if h.get("outcome") == "success"),
            "avg_resources_collected": sum(h.get("resources_collected", 0) for h in team.strategy_history) / max(1, len(team.strategy_history)),
            "common_strategies": self._analyze_common_strategies(team.strategy_history)
        }
        return trends

    def _analyze_common_strategies(self, history: List[Dict]) -> List[str]:
        # Simple keyword extraction from move descriptions
        keywords = defaultdict(int)
        for entry in history:
            moves = entry.get("moves", [])
            for move in moves:
                if isinstance(move, str):
                    for word in move.lower().split():
                        if len(word) > 3:  # ignore short words
                            keywords[word] += 1
        top_keywords = sorted(keywords.items(), key=lambda x: x[1], reverse=True)[:5]
        return [kw for kw, count in top_keywords]

