@dataclass
class Objective:
    """Game objective that robots must complete"""
    id: str
    type: ObjectiveType
    position: Vector2D
    status: str = "neutral"  # neutral, contested, captured
    holder: Optional[int] = None  # team ID of holder
    progress: float = 0.0  # 0.0 to 1.0
    capture_radius: float = 40.0
    capture_time: float = 10.0  # seconds to capture
    capture_progress_rate: float = 0.1  # progress per second
    defense_points: int = 3  # number of defenders needed to hold

    def contest(self, team_id: int) -> bool:
        """Robot of team_id is contesting this objective"""
        if self.status == "captured" and self.holder == team_id:
            return False  # Already captured by team

        if self.status == "neutral":
            self.status = "contested"
            self.holder = team_id
            self.progress = 0.0
            return True
        elif self.status == "contested" and self.holder == team_id:
            # Continue contesting
            self.progress += self.capture_progress_rate * TICK_DURATION
            if self.progress >= 1.0:
                self.status = "captured"
                return True
        elif self.status == "contested" and self.holder != team_id:
            # Other team is contesting, reduce progress
            if self.progress > 0:
                self.progress -= self.capture_progress_rate * TICK_DURATION * 0.5
            else:
                self.holder = team_id
                self.progress = 0.0

        return False

    def get_capture_status(self) -> str:
        """Return human-readable status"""
        if self.status == "captured":
            return f"Captured by team {self.holder}"
        elif self.status == "contested":
            return f"Contested by team {self.holder} ({self.progress:.1%})"
        else:
            return "Neutral"

    def get_state_dict(self) -> Dict[str, Any]:
        return {
            'id': self.id,
            'type': self.type.value,
            'position': {'x': self.position.x, 'y': self.position.y},
            'status': self.status,
            'holder': self.holder,
            'progress': self.progress
        }

