@dataclass
class Hazard:
    """Environmental hazard that affects robots"""
    id: str
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float = 5.0
    speed_reduction: float = 0.5  # multiplier
    active: bool = True
    spawn_time: float = 0.0
    duration: float = 30.0  # seconds

    def affect_robot(self, robot: Robot) -> Dict[str, Any]:
        """Apply effects to robot if within hazard radius"""
        if not self.active:
            return {}

        if self.position.distance_to(robot.position) < self.radius:
            if self.type == HazardType.ELECTRIC_FIELD:
                damage = self.damage_per_second * TICK_DURATION
                robot.take_damage(damage, f"electric_field_{self.id}")
                return {"effect": "damage", "amount": damage}
            elif self.type == HazardType.SLOW_FIELD:
                # Apply speed reduction
                robot.speed *= self.speed_reduction
                return {"effect": "slow", "amount": self.speed_reduction}
            elif self.type == HazardType.MINE_FIELD:
                # Random chance to detonate
                if random.random() < 0.1:
                    damage = self.damage_per_second * 2 * TICK_DURATION
                    robot.take_damage(damage, f"mine_field_{self.id}")
                    return {"effect": "damage", "amount": damage}
            elif self.type == HazardType.BLACK_HOLE:
                # Pull robots toward center
                direction = (self.position - robot.position).normalize()
                robot.velocity += direction * 0.5
                return {"effect": "pull", "amount": 0.5}
            elif self.type == HazardType.WEATHER_STORM:
                # Reduce visibility and accuracy
                robot.vision_radius *= 0.7
                return {"effect": "vision_reduced", "amount": 0.7}

        return {}

    def update(self, delta_time: float):
        """Update hazard state"""
        if not self.active:
            return

        self.duration -= delta_time
        if self.duration <= 0:
            self.active = False

    def get_state_dict(self) -> Dict[str, Any]:
        return {
            'id': self.id,
            'type': self.type.value,
            'position': {'x': self.position.x, 'y': self.position.y},
            'radius': self.radius,
            'active': self.active,
            'duration': self.duration
        }

@dataclass
class Projectile:
    """Projectile fired from weapons"""
    id: str
    owner_id: str
    position: Vector2D
    velocity: Vector2D
    damage: float
    weapon_type: WeaponType
    area_effect: float = 0.0
    lifetime: float = 5.0
    age: float = 0.0
    is_active: bool = True

    def update(self, delta_time: float):
        """Update projectile position and check for expiration"""
        if not self.is_active:
            return

        self.age += delta_time
        self.position += self.velocity * delta_time

        # Check if out of bounds
        if (self.position.x < 0 or self.position.x > GAME_WIDTH or
            self.position.y < 0 or self.position.y > GAME_HEIGHT):
            self.is_active = False
            return

        # Check lifetime
        if self.age >= self.lifetime:
            self.is_active = False
            return

    def get_state_dict(self) -> Dict[str, Any]:
        return {
            'id': self.id,
            'owner_id': self.owner_id,
            'position': {'x': self.position.x, 'y': self.position.y},
            'velocity': {'x': self.velocity.x, 'y': self.velocity.y},
            'damage': self.damage,
            'weapon_type': self.weapon_type.value,
            'area_effect': self.area_effect,
            'lifetime': self.lifetime,
            'age': self.age,
            'is_active': self.is_active
        }

