@dataclass
class Vector2D:
    """2D Vector for position, velocity, and direction"""
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def copy(self):
        return Vector2D(self.x, self.y)

@dataclass
class Weapon:
    """Weapon configuration for robots"""
    name: str
    weapon_type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    cooldown: float = 0.0
    projectile_speed: float = 15.0
    area_effect: float = 0.0  # for explosives

    def can_fire(self):
        return self.cooldown <= 0 and self.ammo > 0

    def fire(self):
        if self.can_fire():
            self.ammo -= 1
            self.cooldown = self.fire_rate
            return True
        return False

    def update(self, delta_time: float):
        if self.cooldown > 0:
            self.cooldown -= delta_time
        if self.ammo < self.max_ammo:
            self.ammo = min(self.max_ammo, self.ammo + delta_time * 0.5)  # slow reload

@dataclass
class Robot:
    """Represents a single AI-controlled robot"""
    id: str
    team: int
    role: RobotRole
    position: Vector2D
    velocity: Vector2D
    health: float
    max_health: float
    armor: float
    speed: float
    weapons: List[Weapon]
    current_weapon_index: int = 0
    last_seen_enemy: Optional[Vector2D] = None
    target: Optional[Vector2D] = None
    objectives: List[str] = field(default_factory=list)
    memory: Dict[str, Any] = field(default_factory=dict)
    last_action_time: float = 0.0
    action_cooldown: float = 0.0
    team_cooperation_score: float = 0.0
    battle_experience: float = 0.0  # Used for learning
    active_powerups: Dict[PowerUpType, float] = field(default_factory=dict)
    is_alive: bool = True
    last_heard_team: float = 0.0
    vision_radius: float = 150.0
    radar_radius: float = 300.0

    def __post_init__(self):
        # Initialize weapon cooldowns
        for weapon in self.weapons:
            weapon.cooldown = 0.0
        self.memory = {
            'enemy_positions': [],
            'allied_positions': [],
            'objective_status': {},
            'battle_history': [],
            'strategy_adaptation': {},
            'team_roles': {}
        }
        self.active_powerups = {}

    def take_damage(self, amount: float, source: str = "unknown") -> float:
        """Apply damage to robot, considering armor"""
        if not self.is_alive:
            return 0.0

        damage_reduction = self.armor / (self.armor + 100)
        actual_damage = amount * (1 - damage_reduction)
        self.health -= actual_damage

        if self.health <= 0:
            self.health = 0
            self.is_alive = False
            self.velocity = Vector2D(0, 0)

        # Log damage event in memory
        self.memory['battle_history'].append({
            'time': time.time(),
            'event': 'damage',
            'amount': actual_damage,
            'source': source,
            'health_remaining': self.health
        })

        return actual_damage

    def heal(self, amount: float):
        """Heal robot"""
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)

    def add_powerup(self, powerup_type: PowerUpType, duration: float):
        """Apply a power-up effect"""
        self.active_powerups[powerup_type] = duration
        self.memory['battle_history'].append({
            'time': time.time(),
            'event': 'powerup',
            'type': powerup_type.value,
            'duration': duration
        })

        # Apply power-up effects
        if powerup_type == PowerUpType.SPEED_BOOST:
            self.speed *= 1.5
        elif powerup_type == PowerUpType.DAMAGE_BOOST:
            for weapon in self.weapons:
                weapon.damage *= 1.3
        elif powerup_type == PowerUpType.SHIELD:
            self.armor += 50
        elif powerup_type == PowerUpType.REGEN:
            self.health = min(self.max_health, self.health + 20)

    def update_powerups(self, delta_time: float):
        """Update active power-ups and remove expired ones"""
        expired = []
        for powerup_type, duration in self.active_powerups.items():
            self.active_powerups[powerup_type] = max(0, duration - delta_time)
            if self.active_powerups[powerup_type] <= 0:
                expired.append(powerup_type)

        for powerup_type in expired:
            del self.active_powerups[powerup_type]
            # Restore original stats
            if powerup_type == PowerUpType.SPEED_BOOST:
                self.speed /= 1.5
            elif powerup_type == PowerUpType.DAMAGE_BOOST:
                for weapon in self.weapons:
                    weapon.damage /= 1.3
            elif powerup_type == PowerUpType.SHIELD:
                self.armor -= 50
                self.armor = max(0, self.armor)

    def get_active_weapon(self) -> Optional[Weapon]:
        """Get the currently selected weapon"""
        if 0 <= self.current_weapon_index < len(self.weapons):
            return self.weapons[self.current_weapon_index]
        return None

    def can_see(self, target_position: Vector2D, obstacles: List[Any]) -> bool:
        """Check if robot can see a target position (line of sight)"""
        if self.position.distance_to(target_position) > self.vision_radius:
            return False

        # Simple ray casting - check if any obstacle blocks the line
        direction = (target_position - self.position).normalize()
        distance = self.position.distance_to(target_position)

        # Check for obstacles in line of sight
        for obstacle in obstacles:
            if hasattr(obstacle, 'position') and hasattr(obstacle, 'radius'):
                # Check if obstacle intersects with the line
                if self._line_circle_intersection(
                    self.position, target_position, 
                    obstacle.position, obstacle.radius
                ):
                    return False
        return True

    def _line_circle_intersection(self, line_start, line_end, circle_center, radius):
        """Simple line-circle intersection detection"""
        # Vector from line start to circle center
        l = circle_center - line_start
        # Direction of line
        d = (line_end - line_start).normalize()
        # Projection of l onto d
        proj = l.dot(d)

        if proj < 0:
            closest = line_start
        elif proj > (line_end - line_start).magnitude():
            closest = line_end
        else:
            closest = line_start + d * proj

        return closest.distance_to(circle_center) <= radius

    def strategize(self, game_state: 'GameState') -> str:
        """AI decision making - determine next action"""
        if not self.is_alive:
            return "dead"

        # Update memory with current game state
        self._update_memory(game_state)

        # Apply learning-based strategy adaptation
        self._adapt_strategy(game_state)

        # Get current strategy based on role, objectives, and game state
        strategy = self._determine_strategy(game_state)

        # Update action cooldown
        self.last_action_time = time.time()

        return strategy

    def _update_memory(self, game_state: 'GameState'):
        """Update robot's memory with current observations"""
        # Update enemy positions
        self.memory['enemy_positions'] = []
        for robot in game_state.robots:
            if robot.team != self.team and robot.is_alive:
                self.memory['enemy_positions'].append(robot.position)

        # Update allied positions
        self.memory['allied_positions'] = []
        for robot in game_state.robots:
            if robot.team == self.team and robot.is_alive:
                self.memory['allied_positions'].append(robot.position)

        # Update objective status
        for obj in game_state.objectives:
            self.memory['objective_status'][obj.id] = {
                'status': obj.status,
                'holder': obj.holder,
                'progress': obj.progress
            }

        # Update team role perceptions
        for robot in game_state.robots:
            if robot.team == self.team and robot.id != self.id:
                if robot.role not in self.memory['team_roles']:
                    self.memory['team_roles'][robot.role] = 0
                self.memory['team_roles'][robot.role] += 1

    def _adapt_strategy(self, game_state: 'GameState'):
        """Adapt strategy based on learning from past battles"""
        # Only adapt every few ticks for efficiency
        if game_state.tick_count % LEARNING_UPDATE_INTERVAL != 0:
            return

        # Calculate performance metrics
        survival_rate = self.battle_experience / (self.battle_experience + 10)
        objective_success = sum(1 for obj in game_state.objectives 
                               if obj.holder == self.team and obj.status == "captured")

        # Adjust AI weights based on performance
        if survival_rate > 0.7 and objective_success > 1:
            # Too successful, increase challenge (more aggressive)
            self.memory['strategy_adaptation']['aggression'] = min(
                1.0, self.memory.get('strategy_adaptation', {}).get('aggression', 0.5) + 0.1
            )
        elif survival_rate < 0.3:
            # Poor performance, become more defensive
            self.memory['strategy_adaptation']['defense'] = min(
                1.0, self.memory.get('strategy_adaptation', {}).get('defense', 0.3) + 0.1
            )

        # Balance cooperation based on team success
        team_success = self._calculate_team_success(game_state)
        if team_success > 0.6:
            self.memory['strategy_adaptation']['cooperation'] = min(
                1.0, self.memory.get('strategy_adaptation', {}).get('cooperation', 0.4) + 0.05
            )
        elif team_success < 0.3:
            self.memory['strategy_adaptation']['cooperation'] = max(
                0.1, self.memory.get('strategy_adaptation', {}).get('cooperation', 0.4) - 0.05
            )

    def _calculate_team_success(self, game_state: 'GameState') -> float:
        """Calculate overall team success rate"""
        if not game_state.robots:
            return 0.0

        teammates_alive = sum(1 for r in game_state.robots 
                             if r.team == self.team and r.is_alive)
        total_teammates = sum(1 for r in game_state.robots 
                             if r.team == self.team)

        objectives_completed = sum(1 for obj in game_state.objectives 
                                  if obj.holder == self.team and obj.status == "captured")
        total_objectives = len(game_state.objectives)

        return (teammates_alive / max(total_teammates, 1) + 
                objectives_completed / max(total_objectives, 1)) / 2

    def _determine_strategy(self, game_state: 'GameState') -> str:
        """Determine the best action based on role, objectives, and environment"""
        # Get current weapon
        weapon = self.get_active_weapon()
        if not weapon:
            return "move"

        # Find nearest enemy
        nearest_enemy = None
        min_distance = float('inf')

        for robot in game_state.robots:
            if robot.team != self.team and robot.is_alive:
                distance = self.position.distance_to(robot.position)
                if distance < min_distance and distance <= self.radar_radius:
                    min_distance = distance
                    nearest_enemy = robot

        # Find nearest objective
        nearest_objective = None
        min_obj_dist = float('inf')

        for objective in game_state.objectives:
            if objective.status != "captured":  # Only care about uncaptured objectives
                distance = self.position.distance_to(objective.position)
                if distance < min_obj_dist:
                    min_obj_dist = distance
                    nearest_objective = objective

        # Check if we can attack
        can_attack = nearest_enemy and weapon.can_fire()
        if can_attack and self.position.distance_to(nearest_enemy.position) <= weapon.range:
            # Consider if we should attack or if we're too exposed
            if self.health < self.max_health * 0.3 and self._should_flee():
                return "retreat"
            return "attack"

        # Role-based strategy
        if self.role == RobotRole.ATTACKER:
            if nearest_enemy and min_distance <= self.radar_radius:
                return "engage_enemy"
            elif nearest_objective:
                return "capture_objective"
            else:
                return "search"

        elif self.role == RobotRole.DEFENDER:
            if nearest_enemy and min_distance <= 200:  # Close proximity
                return "defend_base"
            elif nearest_objective and nearest_objective.type == ObjectiveType.BASE_DEFENSE:
                return "defend_objective"
            else:
                return "patrol_base"

        elif self.role == RobotRole.SUPPORT:
            # Find nearest allied robot that needs help
            ally_needs_help = None
            for robot in game_state.robots:
                if robot.team == self.team and robot.is_alive and robot != self:
                    if robot.health < robot.max_health * 0.4:
                        ally_needs_help = robot
                        break

            if ally_needs_help:
                return "heal_allied"
            elif nearest_objective:
                return "support_objective"
            else:
                return "patrol"

        elif self.role == RobotRole.SCOUT:
            # Scout should find and report enemies
            if nearest_enemy:
                return "report_enemy"
            elif min_obj_dist < 200:  # Get to objective quickly
                return "scout_objective"
            else:
                return "explore"

        elif self.role == RobotRole.CONTROLLER:
            # Controller focuses on objectives and coordination
            if nearest_objective and nearest_objective.status == "neutral":
                return "control_objective"
            elif len(self.memory['enemy_positions']) > 0:
                return "coordinate_attack"
            else:
                return "control_area"

        # Default fallback
        if nearest_enemy and min_distance < 100:
            return "move_to_safe"
        elif nearest_objective:
            return "move_to_objective"
        else:
            return "patrol"

    def _should_flee(self) -> bool:
        """Determine if robot should retreat based on health and enemy proximity"""
        if self.health < self.max_health * 0.2:
            return True
        if len(self.memory['enemy_positions']) > 2:
            # Multiple enemies nearby
            for enemy_pos in self.memory['enemy_positions']:
                if self.position.distance_to(enemy_pos) < 80:
                    return True
        return False

    def execute_action(self, action: str, game_state: 'GameState') -> Dict[str, Any]:
        """Execute the chosen action"""
        result = {"action": action, "success": False}

        if action == "dead":
            return result

        weapon = self.get_active_weapon()

        if action == "attack":
            if weapon and weapon.can_fire():
                # Find closest enemy to attack
                nearest_enemy = None
                min_dist = float('inf')
                for robot in game_state.robots:
                    if robot.team != self.team and robot.is_alive:
                        dist = self.position.distance_to(robot.position)
                        if dist < min_dist and dist <= weapon.range:
                            min_dist = dist
                            nearest_enemy = robot

                if nearest_enemy:
                    # Calculate projectile trajectory
                    direction = (nearest_enemy.position - self.position).normalize()
                    projectile = Projectile(
                        id=f"proj_{self.id}_{time.time()}",
                        owner_id=self.id,
                        position=self.position.copy(),
                        velocity=direction * weapon.projectile_speed,
                        damage=weapon.damage,
                        weapon_type=weapon.weapon_type,
                        area_effect=weapon.area_effect
                    )
                    game_state.projectiles.append(projectile)
                    weapon.fire()
                    result["success"] = True
                    self.memory['battle_history'].append({
                        'time': time.time(),
                        'event': 'attack',
                        'target': nearest_enemy.id,
                        'damage': weapon.damage
                    })

        elif action == "move_to_objective":
            if game_state.objectives:
                # Move towards nearest uncaptured objective
                nearest_obj = None
                min_dist = float('inf')
                for obj in game_state.objectives:
                    if obj.status != "captured":
                        dist = self.position.distance_to(obj.position)
                        if dist < min_dist:
                            min_dist = dist
                            nearest_obj = obj

                if nearest_obj:
                    direction = (nearest_obj.position - self.position).normalize()
                    self.velocity = direction * self.speed
                    result["success"] = True
                    result["target"] = nearest_obj.position

        elif action == "engage_enemy":
            if game_state.robots:
                nearest_enemy = None
                min_dist = float('inf')
                for robot in game_state.robots:
                    if robot.team != self.team and robot.is_alive:
                        dist = self.position.distance_to(robot.position)
                        if dist < min_dist and dist <= 150:
                            min_dist = dist
                            nearest_enemy = robot

                if nearest_enemy:
                    direction = (nearest_enemy.position - self.position).normalize()
                    self.velocity = direction * self.speed
                    result["success"] = True
                    result["target"] = nearest_enemy.position

        elif action == "retreat":
            # Move away from nearest enemy
            nearest_enemy = None
            min_dist = float('inf')
            for robot in game_state.robots:
                if robot.team != self.team and robot.is_alive:
                    dist = self.position.distance_to(robot.position)
                    if dist < min_dist:
                        min_dist = dist
                        nearest_enemy = robot

            if nearest_enemy:
                direction = (self.position - nearest_enemy.position).normalize()
                self.velocity = direction * self.speed * 0.8  # Retreat slower
                result["success"] = True
                result["target"] = self.position + direction * 50

        elif action == "patrol":
            # Move in a patrol pattern
            if not self.target or self.position.distance_to(self.target) < 20:
                # Generate new patrol point
                self.target = Vector2D(
                    random.uniform(100, GAME_WIDTH - 100),
                    random.uniform(100, GAME_HEIGHT - 100)
                )

            direction = (self.target - self.position).normalize()
            self.velocity = direction * self.speed
            result["success"] = True
            result["target"] = self.target

        elif action == "heal_allied":
            # Find nearest allied robot with low health
            nearest_ally = None
            min_health = float('inf')
            for robot in game_state.robots:
                if robot.team == self.team and robot.is_alive and robot != self:
                    if robot.health < min_health and robot.health < robot.max_health * 0.4:
                        min_health = robot.health
                        nearest_ally = robot

            if nearest_ally:
                # Move toward ally to heal
                direction = (nearest_ally.position - self.position).normalize()
                self.velocity = direction * self.speed * 0.7
                result["success"] = True
                result["target"] = nearest_ally.position

        elif action == "defend_base":
            # Move to base position
            base_pos = game_state.get_team_base_position(self.team)
            if base_pos:
                direction = (base_pos - self.position).normalize()
                self.velocity = direction * self.speed * 0.9
                result["success"] = True
                result["target"] = base_pos

        elif action == "control_objective":
            # Move to objective and attempt to control it
            if game_state.objectives:
                nearest_obj = None
                min_dist = float('inf')
                for obj in game_state.objectives:
                    if obj.status != "captured":
                        dist = self.position.distance_to(obj.position)
                        if dist < min_dist:
                            min_dist = dist
                            nearest_obj = obj

                if nearest_obj:
                    # If in range, start controlling
                    if self.position.distance_to(nearest_obj.position) < 30:
                        nearest_obj.contest(self.team)
                    else:
                        direction = (nearest_obj.position - self.position).normalize()
                        self.velocity = direction * self.speed
                    result["success"] = True
                    result["target"] = nearest_obj.position

        # Apply velocity to position
        if self.velocity.magnitude() > 0:
            self.position += self.velocity * TICK_DURATION

            # Clamp position to arena bounds
            self.position.x = max(0, min(GAME_WIDTH, self.position.x))
            self.position.y = max(0, min(GAME_HEIGHT, self.position.y))

        return result

    def get_state_dict(self) -> Dict[str, Any]:
        """Serialize robot state for monitoring/debugging"""
        return {
            'id': self.id,
            'team': self.team,
            'role': self.role.value,
            'position': {'x': self.position.x, 'y': self.position.y},
            'health': self.health,
            'max_health': self.max_health,
            'armor': self.armor,
            'speed': self.speed,
            'alive': self.is_alive,
            'weapons': [w.name for w in self.weapons],
            'active_powerups': [p.value for p in self.active_powerups.keys()],
            'memory_summary': {
                'enemy_positions': len(self.memory['enemy_positions']),
                'allied_positions': len(self.memory['allied_positions']),
                'objectives': len(self.memory['objective_status'])
            }
        }

@dataclass
class Objective:
    """Game objective that robots must complete"""
    id: str
    type: ObjectiveType
    position: Vector2D
    status: str = "neutral"  # neutral, contested, captured
    holder: Optional[int] = None  # team ID of holder
    progress: float = 0.0  # 0.0 to 1.0
    capture_radius: float = 40.0
    capture_time: float = 10.0  # seconds to capture
    capture_progress_rate: float = 0.1  # progress per second
    defense_points: int = 3  # number of defenders needed to hold

    def contest(self, team_id: int) -> bool:
        """Robot of team_id is contesting this objective"""
        if self.status == "captured" and self.holder == team_id:
            return False  # Already captured by team

        if self.status == "neutral":
            self.status = "contested"
            self.holder = team_id
            self.progress = 0.0
            return True
        elif self.status == "contested" and self.holder == team_id:
            # Continue contesting
            self.progress += self.capture_progress_rate * TICK_DURATION
            if self.progress >= 1.0:
                self.status = "captured"
                return True
        elif self.status == "contested" and self.holder != team_id:
            # Other team is contesting, reduce progress
            if self.progress > 0:
                self.progress -= self.capture_progress_rate * TICK_DURATION * 0.5
            else:
                self.holder = team_id
                self.progress = 0.0

        return False

    def get_capture_status(self) -> str:
        """Return human-readable status"""
        if self.status == "captured":
            return f"Captured by team {self.holder}"
        elif self.status == "contested":
            return f"Contested by team {self.holder} ({self.progress:.1%})"
        else:
            return "Neutral"

    def get_state_dict(self) -> Dict[str, Any]:
        return {
            'id': self.id,
            'type': self.type.value,
            'position': {'x': self.position.x, 'y': self.position.y},
            'status': self.status,
            'holder': self.holder,
            'progress': self.progress
        }

@dataclass
class PowerUp:
    """Power-up item that can be collected by robots"""
    id: str
    type: PowerUpType
    position: Vector2D
    duration: float = 15.0  # seconds
    spawn_time: float = 0.0
    collected: bool = False
    radius: float = 20.0

    def is_collected_by(self, robot: Robot) -> bool:
        """Check if robot collected this power-up"""
        if self.collected:
            return False
        if self.position.distance_to(robot.position) < self.radius:
            self.collected = True
            robot.add_powerup(self.type, self.duration)
            return True
        return False

    def get_state_dict(self) -> Dict[str, Any]:
        return {
            'id': self.id,
            'type': self.type.value,
            'position': {'x': self.position.x, 'y': self.position.y},
            'duration': self.duration,
            'collected': self.collected
        }

@dataclass
class Hazard:
    """Environmental hazard that affects robots"""
    id: str
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float = 5.0
    speed_reduction: float = 0.5  # multiplier
    active: bool = True
    spawn_time: float = 0.0
    duration: float = 30.0  # seconds

    def affect_robot(self, robot: Robot) -> Dict[str, Any]:
        """Apply effects to robot if within hazard radius"""
