# ==============================
# ENUMS AND DATA CLASSES
# ==============================

class Team(Enum):
    RED = "Red"
    BLUE = "Blue"
    NEUTRAL = "Neutral"

class WeaponType(Enum):
    RANGED = "Ranged"
    MELEE = "Melee"
    EXPLOSIVE = "Explosive"
    SUPPORT = "Support"

class RobotRole(Enum):
    ATTACKER = "Attacker"
    DEFENDER = "Defender"
    SUPPORT = "Support"
    SCOUT = "Scout"
    CONTROLLER = "Controller"

class ObjectType(Enum):
    FLAG = "Flag"
    BASE = "Base"
    PAYLOAD = "Payload"
    POWER_UP = "PowerUp"
    HAZARD = "Hazard"

class GameState(Enum):
    PREPARING = "Preparing"
    IN_PROGRESS = "InProgress"
    PAUSED = "Paused"
    ENDED = "Ended"

@dataclass
class Position:
    x: float
    y: float
    z: float = 0.0

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2 + (self.z - other.z)**2)

    def __add__(self, other: 'Position') -> 'Position':
        return Position(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other: 'Position') -> 'Position':
        return Position(self.x - other.x, self.y - other.y, self.z - other.z)

    def normalize(self) -> 'Position':
        mag = math.sqrt(self.x**2 + self.y**2 + self.z**2)
        if mag == 0:
            return Position(0, 0, 0)
        return Position(self.x/mag, self.y/mag, self.z/mag)

@dataclass
class Weapon:
    type: WeaponType
    name: str
    damage: float
    range: float
    cooldown: float  # seconds
    ammo: int = -1  # -1 means infinite
    max_ammo: int = -1
    burst: int = 1
    sound_effect: str = "weapon_fire"

    def __post_init__(self):
        self.last_fired = 0.0
        self.current_ammo = self.ammo if self.ammo != -1 else float('inf')

@dataclass
class PowerUp:
    type: str  # e.g., "speed_boost", "health_regen", "shield", "damage_boost"
    duration: float  # seconds
    value: float  # multiplier or absolute value
    description: str = ""
    sound_effect: str = "powerup_acquire"

    def __post_init__(self):
        if not self.description:
            self.description = f"{self.type} activated"

@dataclass
class Robot:
    id: str
    team: Team
    role: RobotRole
    position: Position
    health: float
    max_health: float
    speed: float
    weapons: List[Weapon]
    current_weapon_index: int = 0
    inventory: List[PowerUp] = field(default_factory=list)
    active_effects: Dict[str, float] = field(default_factory=dict)  # effect_name -> expiration_time
    last_seen_enemies: List[str] = field(default_factory=list)
    strategy_memory: Dict[str, float] = field(default_factory=dict)  # strategy -> success_rate
    last_action_time: float = 0.0
    is_dead: bool = False
    respawn_time: float = 0.0
    experience: float = 0.0  # for learning system

    @property
    def current_weapon(self) -> Weapon:
        return self.weapons[self.current_weapon_index] if self.weapons else None

    def apply_effect(self, effect_name: str, duration: float, value: float = 1.0):
        """Apply a temporary effect like speed boost or shield."""
        self.active_effects[effect_name] = time.time() + duration

        # Apply effect modifiers
        if effect_name == "speed_boost":
            self.speed *= value
        elif effect_name == "damage_boost":
            for weapon in self.weapons:
                weapon.damage *= value
        elif effect_name == "shield":
            # Shield will absorb damage before health
            # This would be handled in combat system
            pass

    def update_effects(self):
        """Remove expired effects and revert modifiers."""
        current_time = time.time()
        expired = []

        for effect, expire_time in self.active_effects.items():
            if current_time > expire_time:
                expired.append(effect)

        for effect in expired:
            del self.active_effects[effect]
            # Revert modifiers
            if effect == "speed_boost":
                self.speed /= 1.5  # Assuming 1.5x boost
            elif effect == "damage_boost":
                for weapon in self.weapons:
                    weapon.damage /= 1.5  # Assuming 1.5x boost

    def take_damage(self, damage: float) -> bool:
        """Apply damage to robot and return True if robot died."""
        if self.is_dead:
            return False

        # Apply damage
        self.health -= damage

        # Check if dead
        if self.health <= 0:
            self.health = 0
            self.is_dead = True
            return True

        return False

    def heal(self, amount: float):
        """Heal robot by specified amount."""
        self.health = min(self.max_health, self.health + amount)

    def add_experience(self, exp: float):
        """Add experience and trigger learning updates."""
        self.experience += exp
        # Learning threshold - every 100 exp triggers strategy update
        if self.experience >= 100:
            self.experience -= 100
            self.adapt_strategy()

    def adapt_strategy(self):
        """Adapt strategy based on past performance."""
        # This is a simplified version - in practice this would use ML models
        if not self.strategy_memory:
            return

        # Find best performing strategy
        best_strategy = max(self.strategy_memory.keys(), key=lambda k: self.strategy_memory[k])

        # Increase probability of using best strategy
        # This is a simple reinforcement mechanism
        if random.random() < 0.7:  # 70% chance to stick with best strategy
            # Reassign role based on successful strategy
            if "capture_flag" in best_strategy:
                self.role = RobotRole.ATTACKER
            elif "defend_base" in best_strategy:
                self.role = RobotRole.DEFENDER
            elif "escort_payload" in best_strategy:
                self.role = RobotRole.CONTROLLER
            elif "scout" in best_strategy:
                self.role = RobotRole.SCOUT


@dataclass
class Objective:
    type: ObjectType
    position: Position
    team: Team
    captured_by: Optional[Team] = None
    progress: float = 0.0  # 0.0 to 1.0
    is_active: bool = True
    capture_radius: float = 5.0
    required_team_members: int = 1
    completion_bonus: float = 100.0
    name: str = ""

    def __post_init__(self):
        if not self.name:
            self.name = f"{self.type.value}_{self.team.value}"

    def is_capturable_by(self, robot: Robot) -> bool:
        """Check if a robot can capture this objective."""
        return self.team != robot.team and self.captured_by != robot.team

    def update_capture(self, robots: List[Robot]) -> bool:
        """Update capture progress based on nearby robots."""
        if not self.is_active:
            return False

        # Count robots of the same team near the objective
        nearby_robots = [
            r for r in robots 
            if r.team == self.team and r.position.distance_to(self.position) <= self.capture_radius
        ]

        # Only count if enough robots are present
        if len(nearby_robots) >= self.required_team_members:
            self.progress += 0.01 * len(nearby_robots)  # Base progress rate
            if self.progress >= 1.0:
                self.captured_by = self.team
                self.is_active = False
                return True
        else:
            # If no robots of correct team nearby, reset progress
            self.progress = max(0, self.progress - 0.005)

        return False


