class CombatSystem:
    """Handles real-time combat logic between robots."""

    def __init__(self, robots: List[Robot], environment: Environment):
        self.robots = robots
        self.environment = environment
        self.last_update_time = time.time()
        self.particle_effects = []  # For visual effects
        self.sound_queue = deque()  # Audio events queue

    def update(self, delta_time: float):
        """Update combat system."""
        current_time = time.time()

        # Update weapons cooldown
        for robot in self.robots:
            if robot.is_dead:
                continue

            weapon = robot.current_weapon
            if weapon and weapon.last_fired > 0:
                weapon.last_fired += delta_time
                if weapon.last_fired >= weapon.cooldown:
                    weapon.last_fired = 0.0  # Ready to fire again

        # Process weapon firing
        self.process_weapon_firing(delta_time)

        # Update particle effects
        self.update_particle_effects(delta_time)

        # Update audio context
        self.update_audio_context()

        self.last_update_time = current_time

    def process_weapon_firing(self, delta_time: float):
        """Process weapon firing logic for all robots."""
        for robot in self.robots:
            if robot.is_dead:
                continue

            target = self.find_best_target(robot)
            if not target:
                continue

            weapon = robot.current_weapon
            if not weapon:
                continue

            # Check if weapon is ready to fire
            if weapon.last_fired >= weapon.cooldown and weapon.current_ammo > 0:
                distance = robot.position.distance_to(target.position)

                # Check if within range
                if distance <= weapon.range:
                    # Simple hit detection - if target is within cone
                    direction = (target.position - robot.position).normalize()
                    robot_direction = self.get_robot_facing_direction(robot)

                    # Check if target is in front of robot (simplified cone)
                    dot_product = direction.x * robot_direction.x + direction.y * robot_direction.y
                    if dot_product > 0.5:  # 60-degree cone
                        # Fire weapon
                        self.fire_weapon(robot, target, weapon, distance)

    def find_best_target(self, robot: Robot) -> Optional[Robot]:
        """Find the best target for a robot based on distance and threat level."""
        if robot.is_dead:
            return None

        targets = [
            r for r in self.robots 
            if r.team != robot.team and not r.is_dead
        ]

        if not targets:
            return None

        # Prioritize targets based on health, distance, and recent threat
        best_target = None
        best_score = -1

        for target in targets:
            distance = robot.position.distance_to(target.position)
            health_factor = target.health / target.max_health
            threat_factor = 1.0  # Base threat

            # Use strategy memory to prioritize targets that have caused damage
            if target.id in robot.last_seen_enemies:
                threat_factor += 0.5

            # Score is inverse distance * health factor * threat factor
            score = (1.0 / (distance + 0.1)) * (1.0 - health_factor) * threat_factor

            if score > best_score:
                best_score = score
                best_target = target

        return best_target

    def fire_weapon(self, robot: Robot, target: Robot, weapon: Weapon, distance: float):
        """Handle weapon firing logic."""
        # Reduce ammo
        if weapon.ammo != -1:
            weapon.current_ammo -= 1
            if weapon.current_ammo <= 0:
                weapon.current_ammo = 0
                self.sound_queue.append(("out_of_ammo", robot.id))

        # Calculate damage with distance falloff
        damage = weapon.damage * max(0.2, 1.0 - (distance / weapon.range))

        # Apply damage
        target.take_damage(damage)

        # Add experience for successful hit
        robot.add_experience(damage * 1.5)
        target.add_experience(damage * 0.5)  # Small reward for surviving

        # Record target as recently seen
        if target.id not in robot.last_seen_enemies:
            robot.last_seen_enemies.append(target.id)
        if len(robot.last_seen_enemies) > 5:
            robot.last_seen_enemies.pop(0)

        # Add visual effects
        self.create_hit_effect(target.position, weapon.type)

        # Play sound
        self.sound_queue.append((weapon.sound_effect, robot.id))

        # Update weapon last fired
        weapon.last_fired = 0.0

        # Check for kill
        if target.is_dead:
            robot.add_experience(100.0)
            self.sound_queue.append(("enemy_down", robot.id))

    def create_hit_effect(self, position: Position, weapon_type: WeaponType):
        """Create particle effect for weapon hit."""
        colors = {
            WeaponType.RANGED: (1.0, 0.2, 0.2),
            WeaponType.MELEE: (1.0, 0.8, 0.2),
            WeaponType.EXPLOSIVE: (1.0, 0.5, 0.0),
            WeaponType.SUPPORT: (0.2, 0.8, 1.0)
        }

        color = colors.get(weapon_type, (1.0, 1.0, 1.0))

        self.particle_effects.append({
            'position': position,
            'color': color,
            'life': 0.5,
            'max_life': 0.5,
            'type': 'hit',
            'size': 0.5
        })

    def update_particle_effects(self, delta_time: float):
        """Update and remove expired particle effects."""
        for effect in self.particle_effects[:]:
            effect['life'] -= delta_time
            if effect['life'] <= 0:
                self.particle_effects.remove(effect)
            else:
                # Scale size based on remaining life
                effect['size'] = 0.5 * (effect['life'] / effect['max_life'])

    def update_audio_context(self):
        """Update audio context based on combat events."""
        # This would interface with an audio system in a real implementation
        pass

    def get_robot_facing_direction(self, robot: Robot) -> Position:
        """Simplified facing direction - in a real system this would be based on rotation."""
        # This is a placeholder - in a full 3D system, we'd use actual rotation
        return Position(1.0, 0.0, 0.0)


class ObjectiveSystem:
    """Manages team-based objectives and dynamic roles."""

    def __init__(self, robots: List[Robot], environment: Environment, objectives: List[Objective]):
        self.robots = robots
        self.environment = environment
        self.objectives = objectives
        self.last_update_time = time.time()
        self.completed_objectives = []

    def update(self, delta_time: float):
        """Update objective system."""
        current_time = time.time()

        # Update all objectives
        for objective in self.objectives[:]:
            if objective.is_active:
                # Check if objective is captured
                if objective.update_capture(self.robots):
                    self.objective_complete(objective)

        # Assign dynamic roles based on objectives
        self.assign_dynamic_roles()

        self.last_update_time = current_time

    def objective_complete(self, objective: Objective):
        """Handle completion of an objective."""
        self.completed_objectives.append(objective)
        self.sound_queue.append(("objective_complete", objective.name))

        # Award points to team
        for robot in self.robots:
            if robot.team == objective.team:
                robot.add_experience(objective.completion_bonus)

        # Reset objective if it's a repeating type
        if objective.type == ObjectType.FLAG:
            objective.progress = 0.0
            objective.captured_by = None
            objective.is_active = True
        elif objective.type == ObjectType.PAYLOAD:
            # Payload might be reset or removed
            pass

    def assign_dynamic_roles(self):
        """Assign roles based on current objectives and robot performance."""
        # Count robots per team
        team_counts = defaultdict(int)
        for robot in self.robots:
            if not robot.is_dead:
                team_counts[robot.team] += 1

        # For each team, assign roles based on objectives
        for team in Team:
            if team == Team.NEUTRAL:
                continue

            team_robots = [r for r in self.robots if r.team == team and not r.is_dead]
            if not team_robots:
                continue

            # Find active objectives for this team
            team_objectives = [
                obj for obj in self.objectives 
                if obj.team == team and obj.is_active
            ]

            # Assign roles based on objectives
            if team_objectives:
                for i, robot in enumerate(team_robots):
                    if i == 0:
                        # First robot becomes attacker if objectives need capturing
                        if any(obj.captured_by != team for obj in team_objectives):
                            robot.role = RobotRole.ATTACKER
                        else:
                            robot.role = RobotRole.DEFENDER
                    elif i == 1 and len(team_robots) > 1:
                        # Second robot becomes defender or support
                        if any(obj.captured_by != team for obj in team_objectives):
                            robot.role = RobotRole.SUPPORT
                        else:
                            robot.role = RobotRole.DEFENDER
                    else:
                        # Others become scouts or controllers
                        if len(team_robots) > 3 and random.random() < 0.3:
                            robot.role = RobotRole.SCOUT
                        else:
                            robot.role = RobotRole.CONTROLLER
            else:
                # No active objectives, default roles
                for i, robot in enumerate(team_robots):
                    if i == 0:
                        robot.role = RobotRole.ATTACKER
                    elif i == 1:
                        robot.role = RobotRole.DEFENDER
                    else:
                        robot.role = RobotRole.SCOUT


class AdaptiveDifficultySystem:
    """Adjusts AI behavior and challenge level based on performance."""

    def __init__(self, robots: List[Robot], objectives: List[Objective]):
        self.robots = robots
        self.objectives = objectives
        self.difficulty_level = 1.0  # 0.0 to 3.0
        self.performance_history = []
        self.last_update_time = time.time()
        self.max_difficulty = 3.0
        self.min_difficulty = 0.5

    def update(self, delta_time: float):
        """Update difficulty based on robot performance."""
        current_time = time.time()

        # Calculate team performance every few seconds
        if current_time - self.last_update_time > 10.0:  # Every 10 seconds
            self.evaluate_performance()
            self.adjust_difficulty()
            self.last_update_time = current_time

        # Adjust AI behavior based on difficulty
        self.adjust_ai_behavior()

    def evaluate_performance(self):
        """Evaluate performance of all robots and calculate average."""
        total_score = 0
        robot_count = 0

        for robot in self.robots:
            if robot.is_dead:
                continue

            # Score based on experience, kills, objective contributions
            score = robot.experience
            score += len(robot.last_seen_enemies) * 10

            # Add objective contribution
            for obj in self.objectives:
                if obj.captured_by == robot.team:
                    score += 50

            total_score += score
            robot_count += 1

        if robot_count > 0:
            average_score = total_score / robot_count
            self.performance_history.append(average_score)
            # Keep only last 10 scores
            if len(self.performance_history) > 10:
                self.performance_history.pop(0)

    def adjust_difficulty(self):
        """Adjust difficulty based on average performance."""
        if not self.performance_history:
            return

        avg_performance = sum(self.performance_history) / len(self.performance_history)

        # If performance is high, increase difficulty
        if avg_performance > 150:
            self.difficulty_level = min(self.max_difficulty, self.difficulty_level + 0.1)
        elif avg_performance < 75:
            self.difficulty_level = max(self.min_difficulty, self.difficulty_level - 0.1)

    def adjust_ai_behavior(self):
        """Adjust AI behavior based on difficulty level."""
        difficulty_factor = self.difficulty_level

        # Adjust robot behavior based on difficulty
        for robot in self.robots:
            if robot.team == Team.NEUTRAL:
                continue

            # More aggressive AI at higher difficulty
            if difficulty_factor > 1.5:
                # Increase weapon damage slightly
                for weapon in robot.weapons:
                    weapon.damage *= (1.0 + (difficulty_factor - 1.0) * 0.2)

                # Increase movement speed
                robot.speed *= (1.0 + (difficulty_factor - 1.0) * 0.1)

                # Increase awareness range
                robot.last_seen_enemies = robot.last_seen_enemies[:10]  # Keep more targets

                # More aggressive role switching
                if random.random() < 0.7:
                    robot.role = random.choice(list(RobotRole))

            # More defensive at lower difficulty
            elif difficulty_factor < 1.0:
                # Reduce damage
                for weapon in robot.weapons:
                    weapon.damage *= (1.0 - (1.0 - difficulty_factor) * 0.1)

                # Reduce speed
                robot.speed *= (1.0 - (1.0 - difficulty_factor) * 0.05)


