            del self.active_effects[effect]
            # Revert modifiers
            if effect == "speed_boost":
                self.speed /= 1.5  # Assuming 1.5x boost
            elif effect == "damage_boost":
                for weapon in self.weapons:
                    weapon.damage /= 1.5  # Assuming 1.5x boost

    def take_damage(self, damage: float) -> bool:
        """Apply damage to robot and return True if robot died."""
        if self.is_dead:
            return False

        # Apply damage
        self.health -= damage

        # Check if dead
        if self.health <= 0:
            self.health = 0
            self.is_dead = True
            return True

        return False

    def heal(self, amount: float):
        """Heal robot by specified amount."""
        self.health = min(self.max_health, self.health + amount)

    def add_experience(self, exp: float):
        """Add experience and trigger learning updates."""
        self.experience += exp
        # Learning threshold - every 100 exp triggers strategy update
        if self.experience >= 100:
            self.experience -= 100
            self.adapt_strategy()

    def adapt_strategy(self):
        """Adapt strategy based on past performance."""
        # This is a simplified version - in practice this would use ML models
        if not self.strategy_memory:
            return

        # Find best performing strategy
        best_strategy = max(self.strategy_memory.keys(), key=lambda k: self.strategy_memory[k])

        # Increase probability of using best strategy
        # This is a simple reinforcement mechanism
        if random.random() < 0.7:  # 70% chance to stick with best strategy
            # Reassign role based on successful strategy
            if "capture_flag" in best_strategy:
                self.role = RobotRole.ATTACKER
            elif "defend_base" in best_strategy:
                self.role = RobotRole.DEFENDER
            elif "escort_payload" in best_strategy:
                self.role = RobotRole.CONTROLLER
            elif "scout" in best_strategy:
                self.role = RobotRole.SCOUT


@dataclass
class Objective:
    type: ObjectType
    position: Position
    team: Team
    captured_by: Optional[Team] = None
    progress: float = 0.0  # 0.0 to 1.0
    is_active: bool = True
    capture_radius: float = 5.0
    required_team_members: int = 1
    completion_bonus: float = 100.0
    name: str = ""

    def __post_init__(self):
        if not self.name:
            self.name = f"{self.type.value}_{self.team.value}"

    def is_capturable_by(self, robot: Robot) -> bool:
        """Check if a robot can capture this objective."""
        return self.team != robot.team and self.captured_by != robot.team

    def update_capture(self, robots: List[Robot]) -> bool:
        """Update capture progress based on nearby robots."""
        if not self.is_active:
            return False

        # Count robots of the same team near the objective
        nearby_robots = [
            r for r in robots 
            if r.team == self.team and r.position.distance_to(self.position) <= self.capture_radius
        ]

        # Only count if enough robots are present
        if len(nearby_robots) >= self.required_team_members:
            self.progress += 0.01 * len(nearby_robots)  # Base progress rate
            if self.progress >= 1.0:
                self.captured_by = self.team
                self.is_active = False
                return True
        else:
            # If no robots of correct team nearby, reset progress
            self.progress = max(0, self.progress - 0.005)

        return False


