                        environment.add_particle_effect(self.position, "explosion", 10)

    def _constrain_to_arena(self, environment: 'Environment'):
        """Keep robot within arena boundaries."""
        margin = 20
        if self.position.x < margin:
            self.position.x = margin
            self.velocity.x = 0
        if self.position.x > environment.width - margin:
            self.position.x = environment.width - margin
            self.velocity.x = 0
        if self.position.y < margin:
            self.position.y = margin
            self.velocity.y = 0
        if self.position.y > environment.height - margin:
            self.position.y = environment.height - margin
            self.velocity.y = 0

    def _update_experience(self, delta_time: float):
        """Update robot's experience based on actions."""
        # Gain experience for being alive, dealing damage, completing objectives
        if self.is_alive:
            self.experience += delta_time * 0.1

            # Bonus for successful actions
            if self.last_action in ["attack", "capture", "defend", "escort"]:
                self.experience += delta_time * 0.5

            # Cap experience to prevent runaway growth
            self.experience = min(self.experience, 1000.0)

    def _ai_decision_making(self, environment: 'Environment', robots: List['Robot']):
