# DATA CLASSES
# ----------------------------

@dataclass
class Vector2D:
    """2D Vector for position, velocity, and direction."""
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def length(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        length = self.length()
        if length == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / length, self.y / length)

    def distance_to(self, other):
        return (self - other).length()

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def as_tuple(self):
        return (self.x, self.y)

@dataclass
class Robot:
    """Represents an AI-controlled robot in the arena."""
    id: int
    team: str
    role: RobotRole
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D())
    health: float = 100.0
    max_health: float = 100.0
    armor: float = 0.0
    weapon: Optional['Weapon'] = None
    abilities: List['Ability'] = field(default_factory=list)
    last_updated: float = 0.0
    is_alive: bool = True
    objective_progress: float = 0.0
    target: Optional[Vector2D] = None
    strategy_memory: List[Dict] = field(default_factory=list)
    experience: float = 0.0
    cooldowns: Dict[str, float] = field(default_factory=dict)
    vision_range: float = 150.0
    movement_speed: float = 2.0
    last_action: str = "idle"
    team_memory: List[Dict] = field(default_factory=list)

    def update(self, delta_time: float, environment: 'Environment', robots: List['Robot']):
        """Update robot state based on environment and AI decisions."""
        self.last_updated = time.time()

        # Update cooldowns
        for ability_name in list(self.cooldowns.keys()):
            self.cooldowns[ability_name] -= delta_time
            if self.cooldowns[ability_name] <= 0:
                del self.cooldowns[ability_name]

        # Apply damage over time from hazards
        self._apply_hazard_damage(environment)

        # Update position based on velocity
        self.position += self.velocity * delta_time

        # Keep robot within bounds
        self._constrain_to_arena(environment)

        # AI decision making
        if self.is_alive:
            self._ai_decision_making(environment, robots)

        # Update movement smoothing
        self.velocity *= 0.9  # Friction

        # Update experience based on actions
        self._update_experience(delta_time)

    def _apply_hazard_damage(self, environment: 'Environment'):
        """Apply damage from environmental hazards."""
        for hazard in environment.hazards:
            if hazard.type == HazardType.ELECTRIC_FIELD:
                if self.position.distance_to(hazard.position) < hazard.radius:
                    damage = 0.5 * hazard.intensity
                    self.take_damage(damage)
            elif hazard.type == HazardType.LAVA_POOL:
                if self.position.distance_to(hazard.position) < hazard.radius:
                    damage = 1.0 * hazard.intensity
                    self.take_damage(damage)
            elif hazard.type == HazardType.MINEFIELD:
                if self.position.distance_to(hazard.position) < hazard.radius:
                    # Random chance to trigger mine
                    if random.random() < 0.1:
                        damage = hazard.intensity * 3
                        self.take_damage(damage)
                        # Create explosion effect
                        environment.add_particle_effect(self.position, "explosion", 10)

    def _constrain_to_arena(self, environment: 'Environment'):
        """Keep robot within arena boundaries."""
        margin = 20
        if self.position.x < margin:
            self.position.x = margin
            self.velocity.x = 0
        if self.position.x > environment.width - margin:
            self.position.x = environment.width - margin
            self.velocity.x = 0
        if self.position.y < margin:
            self.position.y = margin
            self.velocity.y = 0
        if self.position.y > environment.height - margin:
            self.position.y = environment.height - margin
            self.velocity.y = 0

    def _update_experience(self, delta_time: float):
        """Update robot's experience based on actions."""
        # Gain experience for being alive, dealing damage, completing objectives
        if self.is_alive:
            self.experience += delta_time * 0.1

            # Bonus for successful actions
            if self.last_action in ["attack", "capture", "defend", "escort"]:
                self.experience += delta_time * 0.5

            # Cap experience to prevent runaway growth
            self.experience = min(self.experience, 1000.0)

    def _ai_decision_making(self, environment: 'Environment', robots: List['Robot']):
        """AI decision making system with adaptive behavior."""
        # Get nearby robots and objectives
        nearby_robots = self._get_nearby_robots(robots)
        objectives = environment.objectives

        # Determine target based on team role and objective
        target = self._find_best_target(nearby_robots, objectives, environment)
        self.target = target

        # Execute appropriate action based on role and situation
        self._execute_action(target, nearby_robots, environment, robots)

    def _get_nearby_robots(self, robots: List['Robot']) -> List['Robot']:
        """Get nearby robots within vision range."""
        return [
            robot for robot in robots 
            if robot != self and robot.is_alive and 
            self.position.distance_to(robot.position) <= self.vision_range
        ]

    def _find_best_target(self, nearby_robots: List['Robot'], objectives: List['Objective'], environment: 'Environment') -> Optional[Vector2D]:
        """Find best target based on role and current situation."""
        # Priority: teammates in danger, then enemy targets, then objectives
        team_robots = [r for r in nearby_robots if r.team == self.team]
        enemy_robots = [r for r in nearby_robots if r.team != self.team]

        # If teammate is low on health, prioritize helping
        if team_robots:
            lowest_health_teammate = min(team_robots, key=lambda r: r.health)
            if lowest_health_teammate.health < 30 and self.role in [RobotRole.SUPPORT, RobotRole.DEFENDER]:
                return lowest_health_teammate.position

        # If enemy is vulnerable, prioritize attack
        if enemy_robots:
            vulnerable_enemy = min(enemy_robots, key=lambda r: r.health)
            if vulnerable_enemy.health < 40:
                return vulnerable_enemy.position

        # Check objectives
        if objectives:
            # Find closest objective of appropriate type for role
            for objective in objectives:
                if self.role == RobotRole.ATTACKER and objective.type == ObjectiveType.CAPTURE_FLAG:
                    return objective.position
                if self.role == RobotRole.DEFENDER and objective.type == ObjectiveType.DEFEND_BASE:
                    return objective.position
                if self.role == RobotRole.CONTROLLER and objective.type == ObjectiveType.CONTROL_POINT:
                    return objective.position
                if self.role == RobotRole.SUPPORT and objective.type == ObjectiveType.ESCAPE_PAYLOAD:
                    return objective.position

        # Default: move toward center of objectives
        if objectives:
            center = Vector2D(
                sum(o.position.x for o in objectives) / len(objectives),
                sum(o.position.y for o in objectives) / len(objectives)
            )
            return center

        # Default: random position in arena
        return Vector2D(
            random.uniform(50, environment.width - 50),
            random.uniform(50, environment.height - 50)
        )

    def _execute_action(self, target: Optional[Vector2D], nearby_robots: List['Robot'], environment: 'Environment', all_robots: List['Robot']):
        """Execute AI action based on current situation."""
        if target is None:
            return

        # Calculate direction to target
        if target:
            direction = (target - self.position).normalize()
        else:
            direction = Vector2D(random.uniform(-1, 1), random.uniform(-1, 1)).normalize()

        # Apply movement
        self.velocity = direction * self.movement_speed

        # Determine action based on role and situation
        enemy_robots = [r for r in nearby_robots if r.team != self.team]
        team_robots = [r for r in nearby_robots if r.team == self.team]

        # Check if we can use ability
        if self._can_use_ability(environment, nearby_robots):
            ability_to_use = self._choose_ability_to_use(environment, nearby_robots)
            if ability_to_use:
                self._use_ability(ability_to_use, environment, nearby_robots)
                self.last_action = ability_to_use.name
                return

        # Check if we can attack
        if enemy_robots and self.weapon:
            closest_enemy = min(enemy_robots, key=lambda r: self.position.distance_to(r.position))
            if self.position.distance_to(closest_enemy.position) <= self.weapon.range:
                # Attack enemy
                damage = self.weapon.damage
                if self.weapon.type == WeaponType.MELEE:
                    # Melee attack
                    self.last_action = "attack"
                    closest_enemy.take_damage(damage)
                    # Add particle effect
                    environment.add_particle_effect(closest_enemy.position, "hit", 5)
                else:
                    # Ranged attack
                    self.last_action = "attack"
                    environment.add_projectile(self.position, closest_enemy.position, self.weapon, self.team)
                    # Sound effect
                    environment.add_sound_effect("weapon_fire", self.position)
                return

        # If no direct attack possible, move toward target
        if self.position.distance_to(target) > 10:
            self.last_action = "move"
        else:
            # Check if we're at objective
            for objective in environment.objectives:
                if self.position.distance_to(objective.position) < 30:
                    if objective.type == ObjectiveType.CAPTURE_FLAG and self.role == RobotRole.ATTACKER:
                        objective.capture(self.team)
                        self.last_action = "capture"
                    elif objective.type == ObjectiveType.DEFEND_BASE and self.role == RobotRole.DEFENDER:
                        objective.defend(self.team)
                        self.last_action = "defend"
                    elif objective.type == ObjectiveType.ESCAPE_PAYLOAD and self.role == RobotRole.SUPPORT:
                        objective.escort(self.team)
                        self.last_action = "escort"

        # Support behavior for support robots
        if self.role == RobotRole.SUPPORT and team_robots:
            lowest_health_teammate = min(team_robots, key=lambda r: r.health)
            if lowest_health_teammate.health < 50:
                # Use healing ability if available
                for ability in self.abilities:
                    if ability.name == "heal" and ability.name not in self.cooldowns:
                        self._use_ability(ability, environment, [lowest_health_teammate])
                        self.last_action = "heal"
                        return

    def _can_use_ability(self, environment: 'Environment', nearby_robots: List['Robot']) -> bool:
        """Check if robot can use any ability."""
        for ability in self.abilities:
            if ability.name not in self.cooldowns:
                # Check if ability can be used in current situation
                if ability.type == "heal":
                    # Only use if teammate is low on health
                    team_robots = [r for r in nearby_robots if r.team == self.team]
                    if team_robots and min(team_robots, key=lambda r: r.health).health < 40:
                        return True
                elif ability.type == "shield":
                    # Use shield if under attack
                    enemy_robots = [r for r in nearby_robots if r.team != self.team]
                    if enemy_robots and min(enemy_robots, key=lambda r: self.position.distance_to(r.position)).position.distance_to(self.position) < 80:
                        return True
                elif ability.type == "teleport":
                    # Use teleport if surrounded
                    enemy_robots = [r for r in nearby_robots if r.team != self.team]
                    if len(enemy_robots) > 2:
                        return True
                else:
                    return True
        return False

    def _choose_ability_to_use(self, environment: 'Environment', nearby_robots: List['Robot']) -> Optional['Ability']:
        """Choose the best ability to use based on situation."""
        for ability in self.abilities:
            if ability.name not in self.cooldowns:
                # Prioritize based on role and situation
                if self.role == RobotRole.SUPPORT and ability.name == "heal":
                    team_robots = [r for r in nearby_robots if r.team == self.team]
                    if team_robots and min(team_robots, key=lambda r: r.health).health < 40:
                        return ability
                elif self.role == RobotRole.DEFENDER and ability.name == "shield":
                    enemy_robots = [r for r in nearby_robots if r.team != self.team]
                    if enemy_robots and min(enemy_robots, key=lambda r: self.position.distance_to(r.position)).position.distance_to(self.position) < 80:
                        return ability
                elif self.role == RobotRole.SCATTER and ability.name == "teleport":
                    enemy_robots = [r for r in nearby_robots if r.team != self.team]
                    if len(enemy_robots) > 2:
                        return ability
                elif self.role == RobotRole.ATTACKER and ability.name == "overdrive":
                    return ability
                elif ability.type == "weapon_upgrade" and self.weapon and self.weapon.level < 5:
                    return ability
        return None

    def _use_ability(self, ability: 'Ability', environment: 'Environment', targets: List['Robot']):
        """Use an ability."""
        self.cooldowns[ability.name] = ability.cooldown

        if ability.name == "heal":
            for target in targets:
                if target.team == self.team and target.is_alive:
                    heal_amount = ability.effect_value
                    target.health = min(target.max_health, target.health + heal_amount)
                    environment.add_particle_effect(target.position, "heal", 8)
                    environment.add_sound_effect("heal", target.position)

        elif ability.name == "shield":
            self.armor += ability.effect_value
            self.armor = min(80, self.armor)  # Cap armor
            environment.add_particle_effect(self.position, "shield", 15)
            environment.add_sound_effect("shield", self.position)

        elif ability.name == "teleport":
            # Teleport to a random position within range
            angle = random.uniform(0, 2 * math.pi)
            distance = ability.effect_value
            new_x = self.position.x + math.cos(angle) * distance
            new_y = self.position.y + math.sin(angle) * distance
            self.position = Vector2D(new_x, new_y)
            environment.add_particle_effect(self.position, "teleport", 20)
            environment.add_sound_effect("teleport", self.position)

        elif ability.name == "overdrive":
            self.movement_speed *= 1.5
            self.weapon.damage *= 1.5
            # Reset after 5 seconds
            threading.Timer(5.0, self._reset_overdrive).start()
            environment.add_particle_effect(self.position, "overdrive", 30)
            environment.add_sound_effect("overdrive", self.position)

    def _reset_overdrive(self):
        """Reset overdrive effect."""
        self.movement_speed = 2.0
        self.weapon.damage = self.weapon.base_damage

    def take_damage(self, damage: float):
        """Apply damage to the robot."""
        if not self.is_alive:
            return

        # Apply armor reduction
        damage_after_armor = damage * (1 - self.armor / 100)
        self.health -= damage_after_armor

        # Kill robot if health <= 0
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            self.velocity = Vector2D()
            # Add death particle effect
            from solution import Environment  # Avoid circular import
            environment = Environment.get_instance()
            if environment:
                environment.add_particle_effect(self.position, "death", 25)
                environment.add_sound_effect("death", self.position)

    def heal(self, amount: float):
        """Heal the robot."""
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)

    def get_status(self) -> Dict:
        """Get robot status for display."""
        return {
            "id": self.id,
            "team": self.team,
            "role": self.role.value,
            "health": self.health,
            "max_health": self.max_health,
            "armor": self.armor,
            "weapon": self.weapon.name if self.weapon else "None",
            "experience": self.experience,
            "alive": self.is_alive,
            "position": (self.position.x, self.position.y),
            "last_action": self.last_action
        }

@dataclass
class Weapon:
    """Represents a weapon a robot can use."""
    name: str
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # shots per second
    ammo: int = -1  # -1 means infinite
    max_ammo: int = -1
    reload_time: float = 2.0
    level: int = 1
    base_damage: float = 0.0  # Store original damage for upgrades

    def __post_init__(self):
        self.base_damage = self.damage

    def fire(self) -> bool:
        """Attempt to fire the weapon. Returns True if successful."""
        if self.ammo != -1:
            if self.ammo <= 0:
                return False
            self.ammo -= 1
        return True

@dataclass
class Ability:
    """Represents a special ability a robot can use."""
    name: str
    type: str  # "heal", "shield", "teleport", "overdrive", "weapon_upgrade", etc.
    cooldown: float  # seconds
    effect_value: float  # depends on type (healing amount, shield strength, teleport distance, etc.)
    description: str = ""

    def __post_init__(self):
        if not self.description:
            self.description = f"{self.name.capitalize()} ability with {self.effect_value} effect"

@dataclass
class Objective:
    """Represents a team-based objective."""
    id: int
    type: ObjectiveType
    position: Vector2D
    team: str = None
    capture_points: int = 0
    max_capture_points: int = 100
    is_active: bool = True
    capture_progress: float = 0.0
    capture_team: Optional[str] = None
    defenders: Set[int] = field(default_factory=set)
    escort_target: Optional[Vector2D] = None
    payload_speed: float = 1.0

    def capture(self, team: str):
        """Attempt to capture the objective."""
        if not self.is_active:
            return

        if team == self.capture_team:
            # Already captured by this team
            self.capture_progress = min(100.0, self.capture_progress + 0.5)
        else:
            # Capture attempt by opposing team
            self.capture_progress = min(100.0, self.capture_progress + 0.3)
            self.capture_team = team
            self.capture_points = min(100, self.capture_points + 1)

        # Complete capture if reached 100%
        if self.capture_progress >= 100:
            self.is_active = False
            # Award points to team
            environment = Environment.get_instance()
            if environment:
                environment.add_score(team, 50)
                environment.add_sound_effect("objective_complete", self.position)

    def defend(self, team: str):
        """Defend the objective."""
        if team == self.capture_team:
            self.capture_progress = min(100.0, self.capture_progress + 0.1)
        else:
            self.capture_progress = max(0.0, self.capture_progress - 0.05)

    def escort(self, team: str):
        """Escort the payload."""
        if team == self.capture_team:
            if self.escort_target:
                distance = self.position.distance_to(self.escort_target)
                if distance < 10:
                    self.is_active = False
                    # Complete escort
                    environment = Environment.get_instance()
                    if environment:
                        environment.add_score(team, 75)
                        environment.add_sound_effect("objective_complete", self.position)
                else:
                    # Move payload toward target
                    direction = (self.escort_target - self.position).normalize()
                    self.position += direction * self.payload_speed
                    self.capture_progress = min(100.0, self.capture_progress + 0.2)

    def get_status(self) -> Dict:
        """Get objective status for display."""
        return {
            "id": self.id,
            "type": self.type.value,
            "position": (self.position.x, self.position.y),
            "team": self.capture_team,
            "progress": self.capture_progress,
            "active": self.is_active,
            "defenders": len(self.defenders)
        }

