@dataclass
class Projectile:
    """Represents a projectile fired from a weapon."""
    position: Vector2D
    velocity: Vector2D
    weapon: Weapon
    owner_team: str
    created_at: float = field(default_factory=time.time)
    damage: float = 0.0
    range: float = 0.0

    def __post_init__(self):
        self.damage = self.weapon.damage
        self.range = self.weapon.range
        self.velocity = self.velocity.normalize() * 10.0  # Fixed speed

    def update(self, delta_time: float) -> bool:
        """Update projectile position. Returns False if projectile should be removed."""
        self.position += self.velocity * delta_time

        # Remove if out of range or too old
        if time.time() - self.created_at > 5.0:
            return False
        return True

@dataclass
class ParticleEffect:
    """Represents a visual particle effect."""
    position: Vector2D
    type: str  # "explosion", "hit", "heal", "shield", "teleport", "death", "overdrive"
    particles: List[Dict] = field(default_factory=list)
    created_at: float = field(default_factory=time.time)
    lifetime: float = 2.0

    def __post_init__(self):
        # Generate particles based on type
        count = 10
        if self.type == "explosion":
            count = 20
        elif self.type == "teleport":
            count = 30
        elif self.type == "death":
            count = 15
        elif self.type == "overdrive":
            count = 25

        for _ in range(count):
            angle = random.uniform(0, 2 * math.pi)
            speed = random.uniform(1.0, 5.0)
            self.particles.append({
                "position": Vector2D(self.position.x, self.position.y),
                "velocity": Vector2D(math.cos(angle) * speed, math.sin(angle) * speed),
                "color": self._get_color(),
                "lifetime": random.uniform(0.5, self.lifetime),
                "size": random.uniform(2, 6)
            })

    def _get_color(self):
        """Get color based on particle type."""
        colors = {
            "explosion": (255, 165, 0),
            "hit": (255, 50, 50),
            "heal": (50, 255, 50),
            "shield": (50, 150, 255),
            "teleport": (150, 50, 255),
            "death": (100, 100, 100),
            "overdrive": (255, 255, 0)
        }
        return colors.get(self.type, (255, 255, 255))

    def update(self, delta_time: float) -> bool:
        """Update particle effect. Returns False if expired."""
        # Update each particle
        updated_particles = []
        for particle in self.particles:
            particle["position"] += particle["velocity"] * delta_time
            particle["lifetime"] -= delta_time
            particle["size"] *= 0.98  # Fade out

            # Keep particles that still have lifetime
            if particle["lifetime"] > 0:
                updated_particles.append(particle)

        self.particles = updated_particles

        # Return True if we still have particles
        return len(self.particles) > 0 and (time.time() - self.created_at) < self.lifetime

    def get_particles(self) -> List[Dict]:
        """Get current particles."""
        return self.particles

@dataclass
class SoundEffect:
    """Represents an audio effect."""
    type: str  # "weapon_fire", "heal", "shield", "teleport", "death", "overdrive", "objective_complete"
    position: Vector2D
    volume: float = 1.0
    created_at: float = field(default_factory=time.time)

    def get_status(self) -> Dict:
        """Get sound effect status."""
        return {
            "type": self.type,
            "position": (self.position.x, self.position.y),
            "volume": self.volume,
            "age": time.time() - self.created_at
        }

