class Environment:
    """Manages the game environment including robots, objectives, and effects."""
    _instance = None

    @classmethod
    def get_instance(cls):
        """Singleton pattern to ensure one environment."""
        if cls._instance is None:
            cls._instance = Environment()
        return cls._instance

    def __init__(self):
        if hasattr(self, 'initialized'):
            return

        self.initialized = True
        self.width = SCREEN_WIDTH
        self.height = SCREEN_HEIGHT
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []
        self.projectiles: List[Projectile] = []
        self.particle_effects: List[ParticleEffect] = []
        self.sound_effects: List[SoundEffect] = []
        self.scores: Dict[str, int] = defaultdict(int)
        self.game_state: str = "waiting"  # "waiting", "playing", "paused", "ended"
        self.spawn_points: List[Vector2D] = []
        self.team_spawn_points: Dict[str, List[Vector2D]] = {}
        self.adaptive_difficulty: float = 1.0  # 1.0 = normal, >1.0 = harder
        self.battle_log: List[str] = []
        self.last_time: float = time.time()
        self.game_time: float = 0.0
        self.map_seed: int = random.randint(1, 1000)

        # Initialize spawn points
        self._generate_spawn_points()

        # Initialize environment
        self._generate_environment()

    def _generate_spawn_points(self):
        """Generate spawn points for teams."""
        # Define spawn points for 2 teams
        self.spawn_points = [
            Vector2D(100, 100),
            Vector2D(100, self.height - 100),
            Vector2D(self.width - 100, 100),
            Vector2D(self.width - 100, self.height - 100),
            Vector2D(self.width // 2, 100),
            Vector2D(self.width // 2, self.height - 100)
        ]

        # Assign to teams
        self.team_spawn_points = {
            "RED": [self.spawn_points[0], self.spawn_points[1]],
            "BLUE": [self.spawn_points[2], self.spawn_points[3]]
        }

    def _generate_environment(self):
        """Generate initial environment with objectives, hazards, and power-ups."""
        # Generate objectives
        objective_types = [
            ObjectiveType.CAPTURE_FLAG,
            ObjectiveType.DEFEND_BASE,
            ObjectiveType.ESCAPE_PAYLOAD,
            ObjectiveType.CONTROL_POINT
        ]

        # Create 3 objectives
        for i in range(3):
            x = random.randint(200, self.width - 200)
            y = random.randint(200, self.height - 200)
            obj_type = random.choice(objective_types)
            obj = Objective(
                id=i,
                type=obj_type,
                position=Vector2D(x, y),
                capture_points=0,
                max_capture_points=100,
                is_active=True
            )

            # Set escort target for escort objectives
            if obj_type == ObjectiveType.ESCAPE_PAYLOAD:
                # Random target location
                target_x = random.randint(100, self.width - 100)
                target_y = random.randint(100, self.height - 100)
                obj.escort_target = Vector2D(target_x, target_y)
                obj.payload_speed = random.uniform(0.5, 1.5)

            self.objectives.append(obj)

        # Generate hazards
        hazard_types = [
            HazardType.ELECTRIC_FIELD,
            HazardType.LAVA_POOL,
            HazardType.MINEFIELD,
            HazardType.GRAVITY_WELL
        ]

        for i in range(4):
            x = random.randint(150, self.width - 150)
            y = random.randint(150, self.height - 150)
            hazard_type = random.choice(hazard_types)
            hazard = Hazard(
                type=hazard_type,
                position=Vector2D(x, y),
                radius=random.uniform(40, 80),
                intensity=random.uniform(0.5, 1.5)
            )
            self.hazards.append(hazard)

        # Generate power-ups
        power_up_types = [
            PowerUpType.HEALTH_PACK,
            PowerUpType.SPEED_BOOST,
            PowerUpType.SHIELD,
            PowerUpType.WEAPON_UPGRADE,
            PowerUpType.TELEPORT
        ]

        for i in range(5):
            x = random.randint(100, self.width - 100)
            y = random.randint(100, self.height - 100)
            power_up_type = random.choice(power_up_types)
            power_up = PowerUp(
                type=power_up_type,
                position=Vector2D(x, y),
                duration=random.uniform(5, 15),
                value=random.uniform(20, 80)
            )
            self.power_ups.append(power_up)

    def add_robot(self, robot: Robot):
        """Add a robot to the environment."""
        self.robots.append(robot)

    def remove_robot(self, robot: Robot):
        """Remove a robot from the environment."""
        if robot in self.robots:
            self.robots.remove(robot)

    def add_projectile(self, start_pos: Vector2D, target_pos: Vector2D, weapon: Weapon, owner_team: str):
