    skills: Dict[str, float] = field(default_factory=dict)

    def __post_init__(self):
        if self.weapon is None:
            self.weapon = Weapon(WeaponType.RANGED, 25, 1.0, 150)
        # Initialize skills if not present
        for skill in ["accuracy", "aggression", "teamwork", "adaptability"]:
            if skill not in self.skills:
                self.skills[skill] = random.uniform(0.5, 1.0)

    def update(self, delta_time: float, environment: 'Environment'):
        if not self.is_alive:
            return

        # Update cooldowns
        if self.cooldown > 0:
            self.cooldown = max(0, self.cooldown - delta_time)

        # Update energy (regeneration)
        self.energy = min(self.max_energy, self.energy + 10 * delta_time)

        # Apply shield regeneration if active
        if self.shield > 0:
            self.shield = max(0, self.shield - 2 * delta_time)

        # Update position if moving
        if self.movement_target:
            direction = (self.movement_target - self.position).normalize()
            distance_to_target = self.position.distance_to(self.movement_target)

            if distance_to_target > self.speed * delta_time:
                move_distance = self.speed * delta_time
                self.position = self.position + direction * move_distance
            else:
                # Reached target
                self.position = self.movement_target
                self.movement_target = None

        # Update learning from environment
        self._learn_from_environment(environment)

    def _learn_from_environment(self, environment: 'Environment'):
        """Adaptive learning mechanism based on experience"""
        # Simple reinforcement learning: adjust skills based on recent success/failure
        if "recent_outcomes" in self.memory:
            recent_successes = sum(1 for outcome in self.memory["recent_outcomes"][-5:] 
                                 if outcome == "success")

            if len(self.memory["recent_outcomes"]) >= 5:
                success_rate = recent_successes / 5.0

                # Adjust skills based on success rate
                if success_rate > 0.7:
                    # Improve teamwork and adaptability
                    self.skills["teamwork"] = min(1.0, self.skills["teamwork"] + 0.01)
                    self.skills["adaptability"] = min(1.0, self.skills["adaptability"] + 0.01)
                elif success_rate < 0.3:
                    # Improve aggression and accuracy if failing
                    self.skills["aggression"] = min(1.0, self.skills["aggression"] + 0.01)
                    self.skills["accuracy"] = min(1.0, self.skills["accuracy"] + 0.01)

    def take_damage(self, damage: float, attacker: Optional['Robot'] = None):
        """Apply damage to robot, considering shields"""
        if not self.is_alive:
            return

        # Apply shield first
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        # Apply remaining damage to health
        self.health = max(0, self.health - damage)

        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            # Add to memory that this robot was eliminated
            if attacker and attacker.team != self.team:
                if "eliminated_by" not in self.memory:
                    self.memory["eliminated_by"] = []
                self.memory["eliminated_by"].append({
                    "attacker": attacker.id,
                    "time": time.time(),
                    "weapon": attacker.weapon.type.name if attacker.weapon else "unknown"
                })

    def heal(self, amount: float):
        """Heal robot"""
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)

    def activate_shield(self, duration: float, strength: float):
