    def take_damage(self, damage: float, attacker: Optional['Robot'] = None):
        """Apply damage to robot, considering shields"""
        if not self.is_alive:
            return

        # Apply shield first
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        # Apply remaining damage to health
        self.health = max(0, self.health - damage)

        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            # Add to memory that this robot was eliminated
            if attacker and attacker.team != self.team:
                if "eliminated_by" not in self.memory:
                    self.memory["eliminated_by"] = []
                self.memory["eliminated_by"].append({
                    "attacker": attacker.id,
                    "time": time.time(),
                    "weapon": attacker.weapon.type.name if attacker.weapon else "unknown"
                })

    def heal(self, amount: float):
        """Heal robot"""
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)

    def activate_shield(self, duration: float, strength: float):
        """Activate shield"""
        if not self.is_alive:
            return
        self.shield = strength

    def can_attack(self) -> bool:
        """Check if robot can attack (not on cooldown)"""
        return self.cooldown <= 0 and self.is_alive and self.energy >= self.weapon.energy_cost

    def attack(self, target: Vector2D, environment: 'Environment') -> bool:
        """Attempt to attack target position"""
        if not self.can_attack():
            return False

        # Check if target is within range
        if self.position.distance_to(target) > self.weapon.range:
            return False

        # Find target robot in range
        target_robot = None
        for robot in environment.robots:
            if robot.team != self.team and robot.is_alive:
                if self.position.distance_to(robot.position) <= self.weapon.range:
                    # Check if target is in line of sight
                    if self._is_line_of_sight_clear(robot.position, environment):
                        target_robot = robot
                        break

        if target_robot:
            # Calculate hit based on accuracy skill
            hit_chance = self.skills["accuracy"]
            if random.random() < hit_chance:
                # Apply damage
                damage = self.weapon.damage
                target_robot.take_damage(damage, self)

                # Add to memory
                if "successful_attacks" not in self.memory:
                    self.memory["successful_attacks"] = []
                self.memory["successful_attacks"].append({
                    "target": target_robot.id,
                    "damage": damage,
                    "time": time.time()
                })

                # Apply cooldown and energy cost
                self.cooldown = self.weapon.cooldown
                self.energy -= self.weapon.energy_cost
                return True
            else:
                # Missed shot
                if "missed_attacks" not in self.memory:
                    self.memory["missed_attacks"] = []
                self.memory["missed_attacks"].append({
                    "target": target_robot.id,
                    "time": time.time()
                })
                self.cooldown = self.weapon.cooldown
                self.energy -= self.weapon.energy_cost * 0.5  # Partial energy cost for miss
                return False
        else:
            # No valid target in range
            return False

    def _is_line_of_sight_clear(self, target: Vector2D, environment: 'Environment') -> bool:
        """Check if there's a clear line of sight to target"""
        # Simple line-of-sight check: check for obstacles
        direction = (target - self.position).normalize()
        distance = self.position.distance_to(target)
        steps = int(distance / 10)  # Check every 10 units

        for i in range(1, steps + 1):
            check_point = self.position + direction * (i * 10)

            # Check if point is inside an obstacle
            for obstacle in environment.obstacles:
                if obstacle.contains_point(check_point):
                    return False

            # Check if point is inside a hazard
            for hazard in environment.hazards:
                if hazard.contains_point(check_point):
                    return False

        return True

    def get_team_members_in_range(self, environment: 'Environment', range_radius: float) -> List['Robot']:
        """Return list of team members within range"""
        teammates = []
        for robot in environment.robots:
            if robot.team == self.team and robot.is_alive:
                if self.position.distance_to(robot.position) <= range_radius:
                    teammates.append(robot)
        return teammates

    def get_enemies_in_range(self, environment: 'Environment', range_radius: float) -> List['Robot']:
        """Return list of enemies within range"""
        enemies = []
        for robot in environment.robots:
            if robot.team != self.team and robot.is_alive:
                if self.position.distance_to(robot.position) <= range_radius:
                    enemies.append(robot)
        return enemies

@dataclass
class Weapon:
    type: WeaponType
    damage: float
    cooldown: float
    range: float
    energy_cost: float = 20.0
    area_radius: float = 50.0  # For area effect weapons
    healing_amount: float = 25.0  # For healing weapons

    def __post_init__(self):
        # Adjust properties based on weapon type
        if self.type == WeaponType.MELEE:
            self.range = 80
            self.energy_cost = 15.0
        elif self.type == WeaponType.HEALING:
            self.damage = 0
            self.cooldown = 3.0
            self.range = 120
            self.energy_cost = 30.0
        elif self.type == WeaponType.AREA_EFFECT:
            self.range = 100
            self.energy_cost = 40.0
            self.damage *= 0.7  # Area weapons do less damage per target

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team: Team
    captured_by: Optional[Team] = None
    progress: float = 0.0  # 0.0 to 1.0
    required_robots: int = 1
    is_active: bool = True
    name: str = ""

    def __post_init__(self):
        if not self.name:
            self.name = f"{self.type.value}_{self.team.value}"

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0
    value: float = 1.5  # Boost multiplier (e.g., 1.5x speed)
    active: bool = True
    spawn_time: float = field(default_factory=time.time)

    def apply_effect(self, robot: Robot):
        """Apply power-up effect to robot"""
        if not robot.is_alive:
            return

        if self.type == PowerUpType.SPEED_BOOST:
            robot.speed *= self.value
            robot.memory["speed_boost_end"] = time.time() + self.duration
        elif self.type == PowerUpType.DAMAGE_BOOST:
            # Find and modify robot's weapon
            if robot.weapon:
                original_damage = robot.weapon.damage
                robot.weapon.damage *= self.value
                robot.memory["damage_boost_end"] = time.time() + self.duration
                robot.memory["original_damage"] = original_damage
        elif self.type == PowerUpType.SHIELD:
            robot.activate_shield(self.duration, robot.max_health * 0.5)
        elif self.type == PowerUpType.REGEN:
            robot.max_health *= self.value
            robot.health = robot.max_health
            robot.memory["regen_end"] = time.time() + self.duration
        elif self.type == PowerUpType.TELEPORT:
            # Teleport to random location
            robot.position = Vector2D(
                random.uniform(50, GAME_WIDTH - 50),
                random.uniform(50, GAME_HEIGHT - 50)
            )
            robot.memory["teleport_used"] = True
        elif self.type == PowerUpType.SILENCE:
            # Disable weapons for enemies in range
            robot.memory["silence_end"] = time.time() + self.duration
            # This will be applied in environment update

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float = 60.0
    damage_per_second: float = 5.0
    active: bool = True

    def contains_point(self, point: Vector2D) -> bool:
        return self.position.distance_to(point) <= self.radius

    def apply_damage(self, robot: Robot) -> bool:
        """Apply damage to robot if in hazard"""
        if not self.active or not robot.is_alive:
            return False

        if self.contains_point(robot.position):
            robot.take_damage(self.damage_per_second / FPS)  # Damage per frame
            return True
        return False

@dataclass
class Environment:
    width: int = GAME_WIDTH
    height: int = GAME_HEIGHT
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    powerups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    obstacles: List[Vector2D] = field(default_factory=list)  # List of obstacle positions
    lighting: Dict[str, Any] = field(default_factory=dict)
    sound_effects: Dict[str, List] = field(default_factory=dict)
    game_time: float = 0.0
    last_update: float = 0.0
    team_scores: Dict[Team, float] = field(default_factory=lambda: {team: 0.0 for team in Team})
    round_history: List[Dict] = field(default_factory=list)

    def __post_init__(self):
        # Initialize lighting with ambient and dynamic sources
        self.lighting = {
            "ambient": 0.3,  # Base ambient light
            "dynamic": [],   # List of dynamic light sources (e.g., explosions)
            "team_colors": {
                Team.RED: (1.0, 0.2, 0.2),
                Team.BLUE: (0.2, 0.2, 1.0),
                Team.GREEN: (0.2, 1.0, 0.2),
                Team.YELLOW: (1.0, 1.0, 0.2)
            }
        }

        # Initialize sound effects system
        self.sound_effects = {
            "weapon_fire": [],
            "explosion": [],
            "heal": [],
            "powerup": [],
            "team_score": [],
            "enemy_killed": []
        }

    def add_robot(self, robot: Robot):
        self.robots.append(robot)

    def add_objective(self, objective: Objective):
        self.objectives.append(objective)

    def add_powerup(self, powerup: PowerUp):
        self.powerups.append(powerup)

    def add_hazard(self, hazard: Hazard):
        self.hazards.append(hazard)

    def add_obstacle(self, position: Vector2D):
        self.obstacles.append(position)

    def update(self, delta_time: float):
        """Update the entire environment"""
        self.game_time += delta_time

        # Update robots
        for robot in self.robots:
            if robot.is_alive:
                robot.update(delta_time, self)

                # Check if any active power-ups should expire
                if "speed_boost_end" in robot.memory:
                    if time.time() >= robot.memory["speed_boost_end"]:
                        robot.speed /= 1.5
                        del robot.memory["speed_boost_end"]

                if "damage_boost_end" in robot.memory:
                    if time.time() >= robot.memory["damage_boost_end"]:
                        if "original_damage" in robot.memory:
                            robot.weapon.damage = robot.memory["original_damage"]
                            del robot.memory["original_damage"]
                        del robot.memory["damage_boost_end"]

                if "regen_end" in robot.memory:
                    if time.time() >= robot.memory["regen_end"]:
                        robot.max_health = DEFAULT_HEALTH
                        robot.health = min(robot.health, robot.max_health)
                        del robot.memory["regen_end"]

                if "silence_end" in robot.memory:
                    if time.time() >= robot.memory["silence_end"]:
                        del robot.memory["silence_end"]

        # Update power-ups
        for powerup in self.powerups[:]:
            if not powerup.active:
                self.powerups.remove(powerup)
                continue

            # Check if power-up should expire
            if time.time() - powerup.spawn_time > 30.0:  # 30 second spawn limit
                powerup.active = False
                self.powerups.remove(powerup)
                self._add_sound_effect("powerup", "expired")
                continue

            # Check if any robot is within range to collect
            for robot in self.robots:
                if robot.is_alive and robot.position.distance_to(powerup.position) < 50:
                    powerup.apply_effect(robot)
                    powerup.active = False
                    self._add_sound_effect("powerup", "collected")
                    self.powerups.remove(powerup)
                    break

        # Update hazards
        for hazard in self.hazards:
            if hazard.active:
                for robot in self.robots:
                    if robot.is_alive:
                        hazard.apply_damage(robot)

        # Update objectives
        for objective in self.objectives:
            if not objective.is_active:
                continue

            # Calculate progress for capture objectives
            if objective.type == ObjectiveType.CAPTURE_FLAG:
                team_robots = 0
                for robot in self.robots:
                    if robot.team == objective.team and robot.is_alive:
                        if robot.position.distance_to(objective.position) < 80:
                            team_robots += 1

                if team_robots >= objective.required_robots:
                    objective.progress = min(1.0, objective.progress + delta_time * 0.1)
                    if objective.progress >= 1.0 and objective.captured_by != objective.team:
                        objective.captured_by = objective.team
                        self.team_scores[objective.team] += 100
                        self._add_sound_effect("team_score", "objective_captured")
                        self._add_dynamic_lighting(objective.position, 0.8, 0.4, 0.2, 2.0)
                else:
                    # If not enough robots, reduce progress slowly
                    objective.progress = max(0, objective.progress - delta_time * 0.05)
                    if objective.progress <= 0 and objective.captured_by == objective.team:
                        objective.captured_by = None

            # For defense objectives, just track if team is present
            elif objective.type == ObjectiveType.DEFEND_BASE:
                team_robots = 0
                for robot in self.robots:
                    if robot.team == objective.team and robot.is_alive:
                        if robot.position.distance_to(objective.position) < 100:
                            team_robots += 1

                if team_robots >= objective.required_robots:
                    objective.progress = min(1.0, objective.progress + delta_time * 0.05)
                else:
                    objective.progress = max(0, objective.progress - delta_time * 0.02)

                # If defense is successful, score points
                if objective.progress >= 1.0 and not objective.captured_by:
                    objective.captured_by = objective.team
                    self.team_scores[objective.team] += 50
                    self._add_sound_effect("team_score", "objective_defended")
                    self._add_dynamic_lighting(objective.position, 0.2, 0.4, 0.8, 2.0)

            # For escort objectives
            elif objective.type == ObjectiveType.ESCAPE_PAYLOAD:
                # Find carrier robot
                carrier = None
                for robot in self.robots:
                    if robot.team == objective.team and robot.is_alive and robot.role == Role.CARRIER:
                        carrier = robot
                        break

                if carrier:
                    distance = carrier.position.distance_to(objective.position)
                    if distance < 80:
                        objective.progress = min(1.0, objective.progress + delta_time * 0.1)
                        if objective.progress >= 1.0 and objective.captured_by != objective.team:
                            objective.captured_by = objective.team
                            self.team_scores[objective.team] += 150
                            self._add_sound_effect("team_score", "objective_captured")
                            self._add_dynamic_lighting(objective.position, 0.8, 0.4, 0.2, 2.0)
                    else:
                        # Progress decreases if carrier is away
                        objective.progress = max(0, objective.progress - delta_time * 0.02)

        # Update dynamic lighting
        for light in self.lighting["dynamic"][:]:
            light["duration"] -= delta_time
            if light["duration"] <= 0:
                self.lighting["dynamic"].remove(light)

    def _add_dynamic_lighting(self, position: Vector2D, r: float, g: float, b: float, duration: float):
        """Add a dynamic light source"""
        self.lighting["dynamic"].append({
            "position": position,
            "color": (r, g, b),
            "intensity": 1.0,
            "duration": duration
        })

    def _add_sound_effect(self, effect_type: str, sound_name: str):
        """Add a sound effect to the queue"""
        if effect_type in self.sound_effects:
            self.sound_effects[effect_type].append({
                "name": sound_name,
                "time": time.time(),
                "position": None
            })

    def get_team_robots(self, team: Team) -> List[Robot]:
        """Return all robots on a specific team"""
        return [robot for robot in self.robots if robot.team == team and robot.is_alive]

    def get_nearest_objective(self, robot: Robot) -> Optional[Objective]:
        """Return the nearest active objective to robot"""
        active_objectives = [obj for obj in self.objectives if obj.is_active]
        if not active_objectives:
            return None

        nearest = min(active_objectives, key=lambda obj: robot.position.distance_to(obj.position))
        return nearest if robot.position.distance_to(nearest.position) < 500 else None

@dataclass
class AIController:
    """AI controller for robots"""
    environment: Environment

    def decide_action(self, robot: Robot) -> Dict[str, Any]:
        """Make decision for robot based on current state"""
        if not robot.is_alive:
            return {"action": "idle"}

        # Get current context
        teammates = robot.get_team_members_in_range(self.environment, 200)
        enemies = robot.get_enemies_in_range(self.environment, robot.vision_range)
        nearest_objective = self.environment.get_nearest_objective(robot)
        powerups = [pu for pu in self.environment.powerups if pu.active and 
                   robot.position.distance_to(pu.position) < 150]

        # Adaptive difficulty: adjust behavior based on team performance
        team_score = self.environment.team_scores[robot.team]
        opponent_score = sum(self.environment.team_scores[t] for t in Team if t != robot.team)

        # Adjust aggression based on relative performance
        if team_score < opponent_score * 0.7:
            # Team is losing - be more aggressive
            aggression_factor = 1.5
        elif team_score > opponent_score * 1.3:
            # Team is winning - be more defensive
            aggression_factor = 0.7
        else:
            # Balanced situation
            aggression_factor = 1.0

        # Calculate role-based behavior
        if robot.role == Role.ATTACKER:
            return self._decide_attacker(robot, enemies, teammates, nearest_objective, powerups, aggression_factor)
        elif robot.role == Role.DEFENDER:
            return self._decide_defender(robot, enemies, teammates, nearest_objective, powerups, aggression_factor)
        elif robot.role == Role.SUPPORT:
            return self._decide_support(robot, enemies, teammates, nearest_objective, powerups, aggression_factor)
        elif robot.role == Role.SCOUT:
            return self._decide_scout(robot, enemies, teammates, nearest_objective, powerups, aggression_factor)
        elif robot.role == Role.CARRIER:
            return self._decide_carrier(robot, enemies, teammates, nearest_objective, powerups, aggression_factor)
        else:
            # Default behavior
            return self._decide_default(robot, enemies, teammates, nearest_objective, powerups)

    def _decide_attacker(self, robot: Robot, enemies: List[Robot], teammates: List[Robot], 
                        nearest_objective: Optional[Objective], powerups: List[PowerUp], 
                        aggression_factor: float) -> Dict[str, Any]:
        """Attacker AI: Focus on eliminating enemies and capturing objectives"""

        # Look for targets
        if enemies:
            # Prioritize targets based on health and proximity
            target = min(enemies, key=lambda e: robot.position.distance_to(e.position))

            # Check if we can attack
            if robot.can_attack() and robot.position.distance_to(target.position) <= robot.weapon.range:
                return {
                    "action": "attack",
                    "target": target.position,
                    "reason": "enemy_in_range"
                }

            # Move toward target
            return {
                "action": "move",
                "target": target.position,
                "reason": "pursue_enemy"
            }

        # No enemies in range, look for objectives
        if nearest_objective and nearest_objective.captured_by != robot.team:
            # If objective is neutral or captured by enemy
            if robot.position.distance_to(nearest_objective.position) > 80:
                return {
                    "action": "move",
                    "target": nearest_objective.position,
                    "reason": "capture_objective"
                }

        # Look for power-ups
        if powerups:
            powerup = min(powerups, key=lambda pu: robot.position.distance_to(pu.position))
            return {
                "action": "move",
                "target": powerup.position,
                "reason": "collect_powerup"
            }

        # Default: patrol around objective if one exists
        if nearest_objective:
            return {
                "action": "patrol",
                "target": nearest_objective.position,
                "reason": "patrol_objective"
            }

        # Random roam
        return {
            "action": "move",
            "target": self._get_random_position(),
            "reason": "roam"
        }

    def _decide_defender(self, robot: Robot, enemies: List[Robot], teammates: List[Robot], 
                        nearest_objective: Optional[Objective], powerups: List[PowerUp], 
                        aggression_factor: float) -> Dict[str, Any]:
        """Defender AI: Protect objectives and allies"""

        # If there are enemies nearby, engage them
        if enemies:
            # Prioritize enemies closest to objective
            if nearest_objective:
                target = min(enemies, key=lambda e: e.position.distance_to(nearest_objective.position))
            else:
                target = min(enemies, key=lambda e: robot.position.distance_to(e.position))

            if robot.can_attack() and robot.position.distance_to(target.position) <= robot.weapon.range:
                return {
                    "action": "attack",
                    "target": target.position,
                    "reason": "defend_objective"
                }

            # Move toward target to intercept
            return {
                "action": "move",
                "target": target.position,
                "reason": "intercept_enemy"
            }

        # If no enemies, stay near objective
        if nearest_objective:
            # If objective is captured by our team, defend it
            if nearest_objective.captured_by == robot.team:
                # Patrol around objective
                angle = (time.time() % 10) * 0.6  # Rotate around objective
                patrol_x = nearest_objective.position.x + math.cos(angle) * 60
                patrol_y = nearest_objective.position.y + math.sin(angle) * 60
                return {
                    "action": "move",
                    "target": Vector2D(patrol_x, patrol_y),
                    "reason": "defend_objective"
                }

            # If objective is captured by enemy, attempt to retake
            elif nearest_objective.captured_by != robot.team and nearest_objective.captured_by:
                return {
                    "action": "move",
                    "target": nearest_objective.position,
                    "reason": "retake_objective"
                }

        # Look for power-ups
        if powerups:
            powerup = min(powerups, key=lambda pu: robot.position.distance_to(pu.position))
            return {
                "action": "move",
                "target": powerup.position,
                "reason": "collect_powerup"
            }

        # Default: patrol near team base
        return {
            "action": "move",
            "target": self._get_random_position_in_team_zone(robot.team),
            "reason": "patrol_base"
        }

    def _decide_support(self, robot: Robot, enemies: List[Robot], teammates: List[Robot], 
                       nearest_objective: Optional[Objective], powerups: List[PowerUp], 
                       aggression_factor: float) -> Dict[str, Any]:
        """Support AI: Heal allies and provide utility"""

        # Check for injured teammates
        injured_teammates = [t for t in teammates if t.health < t.max_health * 0.7]

        if injured_teammates:
            # Find the most injured teammate
            target = min(injured_teammates, key=lambda t: t.health / t.max_health)

            # If we have healing weapon and can use it
            if robot.weapon.type == WeaponType.HEALING and robot.can_attack():
                if robot.position.distance_to(target.position) <= robot.weapon.range:
                    return {
                        "action": "attack",
                        "target": target.position,
                        "reason": "heal_teammate"
                    }

            # Move toward injured teammate
            return {
                "action": "move",
                "target": target.position,
                "reason": "heal_teammate"
            }

        # If no injured teammates, look for enemies
        if enemies:
            # Keep distance from enemies but maintain support position
            closest_enemy = min(enemies, key=lambda e: robot.position.distance_to(e.position))

            # Move away from enemies but toward teammates
            if robot.position.distance_to(closest_enemy.position) < 120:
                # Move away from enemy but toward nearest teammate
                if teammates:
                    nearest_teammate = min(teammates, key=lambda t: robot.position.distance_to(t.position))
                    # Move in direction away from enemy but toward teammate
                    direction = (nearest_teammate.position - robot.position).normalize()
                    away_from_enemy = (robot.position - closest_enemy.position).normalize()
                    target_dir = (direction + away_from_enemy * 0.5).normalize()
                    target_pos = robot.position + target_dir * 80
                    return {
                        "action": "move",
                        "target": target_pos,
                        "reason": "avoid_enemy_support"
                    }

        # Look for power-ups for the team
        if powerups:
            powerup = min(powerups, key=lambda pu: robot.position.distance_to(pu.position))
            # Check if power-up benefits team
            if powerup.type in [PowerUpType.REGEN, PowerUpType.SHIELD]:
                return {
                    "action": "move",
                    "target": powerup.position,
                    "reason": "collect_team_powerup"
                }

        # Default: stay near objective or team center
        if nearest_objective and nearest_objective.captured_by == robot.team:
            return {
                "action": "move",
                "target": nearest_objective.position,
                "reason": "support_objective"
            }

        return {
            "action": "move",
