    def can_see(self, target_pos: Vector2D, environment: 'Environment') -> bool:
        """Check if robot has line of sight to target position"""
        # Simple line-of-sight check - check for obstacles
        line_points = self._get_line_points(self.position, target_pos)

        for point in line_points:
