    source_robot_id: int
    weapon_type: WeaponType
    lifetime: float = 3.0
    age: float = 0.0
    active: bool = True

    def update(self, dt: float, environment: 'Environment') -> bool:
        """Update projectile position and check for expiration or collision"""
        if not self.active:
            return False

        self.age += dt
        self.position += self.velocity * dt

        # Check lifetime
        if self.age >= self.lifetime:
            self.active = False
            return False

        # Check collision with environment
        for obstacle in environment.obstacles:
            if obstacle.contains_point(self.position):
                self.active = False
                return False

        # Check collision with robots
        for robot in environment.robots:
            if robot.team != self.team and not robot.is_dead:
                if self.position.distance_to(robot.position) < 30:  # Collision radius
                    robot.take_damage(self.damage)
                    self.active = False
                    return False

        return True

