                ammo=80,
                max_ammo=80,
                splash_radius=5.0,
                fire_sound="pew"
            )

        self.robots.append(robot)
        return robot

    def apply_powerup(self, robot: Robot, powerup: PowerUp):
        """Apply powerup effect to robot"""
        if powerup.type == PowerUpType.HEALTH_PACK:
            robot.heal(powerup.value)
        elif powerup.type == PowerUpType.SPEED_BOOST:
            robot.speed *= powerup.value
            # Reset speed after duration
            threading.Timer(powerup.duration, lambda: setattr(robot, 'speed', robot.speed / powerup.value)).start()
        elif powerup.type == PowerUpType.SHIELD:
            robot.shield = min(robot.shield_max, robot.shield + powerup.value)
        elif powerup.type == PowerUpType.WEAPON_UPGRADE:
            # Increase weapon damage
            original_damage = robot.weapon.damage
            robot.weapon.damage *= powerup.value
            # Reset damage after duration
            threading.Timer(powerup.duration, lambda: setattr(robot.weapon, 'damage', original_damage)).start()
        elif powerup.type == PowerUpType.TELEPORT:
            # Teleport to random location
            new_pos = random.choice(self.spawn_points)
            robot.position = new_pos

        # Play sound
        self.sound_manager.play_sound("powerup", robot.position)

