                type=WeaponType.RANGED,
                damage=25.0,
                range=300.0,
                cooldown=0.5,
                ammo=50,
                max_ammo=50,
                splash_radius=10.0
            )

        # Initialize skills if not provided
        if not self.skills:
            self.skills = {
                "accuracy": random.uniform(0.6, 0.9),
                "tactics": random.uniform(0.5, 0.9),
                "reaction": random.uniform(0.4, 0.8),
                "teamwork": random.uniform(0.3, 0.9)
            }

    def take_damage(self, amount: float, source: str = "unknown") -> bool:
        """Apply damage to robot, considering shield first"""
        if self.is_dead:
            return False

        # Apply shield first
        if self.shield > 0:
            shield_absorbed = min(amount, self.shield)
            self.shield -= shield_absorbed
            amount -= shield_absorbed

        # Apply remaining damage to health
        self.health -= amount
        if self.health <= 0:
            self.health = 0
            self.is_dead = True
            return True
        return False

    def heal(self, amount: float):
        """Heal robot, up to max_health"""
        if not self.is_dead:
            self.health = min(self.max_health, self.health + amount)

    def recharge_shield(self, dt: float):
        """Recharge shield over time"""
        if not self.is_dead and self.shield < self.shield_max:
            self.shield = min(self.shield_max, self.shield + self.shield_recharge_rate * dt)

    def update(self, dt: float, environment: 'Environment'):
        """Update robot state"""
        if self.is_dead:
            return

        # Update shield
        self.recharge_shield(dt)

        # Update weapon cooldown
        if self.weapon.last_fired > 0:
            self.weapon.last_fired -= dt
            if self.weapon.last_fired < 0:
                self.weapon.last_fired = 0

        # Update position based on velocity
        self.position += self.velocity * dt

        # Apply friction
        self.velocity *= FRICTION

        # Keep robot within bounds
        self.position.x = max(0, min(SCREEN_WIDTH, self.position.x))
        self.position.y = max(0, min(SCREEN_HEIGHT, self.position.y))

        # Check for environmental hazards
        self.check_hazards(environment)

        # Update last updated time
        self.last_updated = time.time()

    def check_hazards(self, environment: 'Environment'):
        """Check if robot is in a hazard zone and apply damage"""
        for hazard in environment.hazards:
            if hazard.type == HazardType.LAVA:
                if self.position.distance_to(hazard.position) < hazard.radius:
                    self.take_damage(2.0 * environment.hazard_intensity)
            elif hazard.type == HazardType.ELECTRIC_FENCE:
                if self.position.distance_to(hazard.position) < hazard.radius:
                    self.take_damage(1.5 * environment.hazard_intensity)
            elif hazard.type == HazardType.MINEFIELD:
                if self.position.distance_to(hazard.position) < hazard.radius:
                    if random.random() < 0.3 * environment.hazard_intensity:
                        self.take_damage(15.0 * environment.hazard_intensity)

    def can_see(self, target_pos: Vector2D, environment: 'Environment') -> bool:
        """Check if robot has line of sight to target position"""
        # Simple line-of-sight check - check for obstacles
        line_points = self._get_line_points(self.position, target_pos)

        for point in line_points:
            # Check if point is inside any obstacle
            for obstacle in environment.obstacles:
                if obstacle.contains_point(point):
                    return False

        # Check if target is within weapon range
        distance = self.position.distance_to(target_pos)
        return distance <= self.weapon.range * 1.5  # Allow some buffer

    def _get_line_points(self, start: Vector2D, end: Vector2D) -> List[Vector2D]:
        """Generate points along a line from start to end"""
        points = []
        distance = start.distance_to(end)
        if distance == 0:
            return [start]

        steps = int(distance)
        for i in range(steps + 1):
            ratio = i / steps
            x = start.x + ratio * (end.x - start.x)
            y = start.y + ratio * (end.y - start.y)
            points.append(Vector2D(x, y))

        return points

    def get_aim_vector(self, target_pos: Vector2D) -> Vector2D:
        """Calculate direction vector to aim at target position"""
        return (target_pos - self.position).normalize()

    def fire_weapon(self, target_pos: Vector2D, environment: 'Environment') -> Optional['Projectile']:
        """Fire weapon at target position"""
        if self.is_dead or self.weapon.last_fired > 0:
            return None

        # Check ammo if it's not infinite
        if self.weapon.ammo != -1 and self.weapon.current_ammo <= 0:
            return None

        # Calculate direction
        direction = (target_pos - self.position).normalize()

        # Create projectile
        projectile = Projectile(
            position=self.position + direction * 20,
            velocity=direction * 25,
            damage=self.weapon.damage,
            splash_radius=self.weapon.splash_radius,
            team=self.team,
            source_robot_id=self.id,
            weapon_type=self.weapon.type
        )

        # Update weapon state
        self.weapon.last_fired = self.weapon.cooldown
        if self.weapon.ammo != -1:
            self.weapon.current_ammo -= 1
            if self.weapon.current_ammo <= 0:
                self.weapon.current_ammo = 0

        # Play sound
        if hasattr(environment, 'sound_manager'):
            environment.sound_manager.play_sound(self.weapon.fire_sound, self.position)

        return projectile

    def find_nearest_target(self, robots: List['Robot']) -> Optional[int]:
        """Find nearest enemy robot within range"""
        enemies = [r for r in robots if r.team != self.team and not r.is_dead]
        if not enemies:
            return None

        nearest = min(enemies, key=lambda r: self.position.distance_to(r.position))
        if self.position.distance_to(nearest.position) <= self.weapon.range * 1.2:
            return nearest.id
        return None

    def think(self, environment: 'Environment', robots: List['Robot'], objectives: List['Objective']) -> str:
        """AI decision-making function - returns next action"""
        if self.is_dead:
            return "dead"

        # Get team members
        teammates = [r for r in robots if r.team == self.team and not r.is_dead]
        enemies = [r for r in robots if r.team != self.team and not r.is_dead]

        # Find nearest objective
        nearest_objective = None
        min_distance = float('inf')
        for obj in objectives:
            if obj.team == self.team and obj.completed:
                continue  # Skip completed objectives
            distance = self.position.distance_to(obj.position)
            if distance < min_distance:
                min_distance = distance
                nearest_objective = obj

        # Decision tree based on role
        if self.role == RobotRole.SCAT:
            # Scout: look for enemies and reportif self.role == RobotRole.Scout:            if len(enemies) > 0:
                nearest_enemy = min(enemies, key=lambda r: self.position.distance_to(r.position))
                if self.position.distance_to(nearest_enemy.position) < 400:  # Detection range
                    self.target = nearest_enemy.id
                    return f"engage_enemy_{nearest_enemy.id}"

            # If no enemies nearby, move toward objective
            if nearest_objective:
                self.target = nearest_objective.id
                return f"move_to_objective_{nearest_objective.id}"

        elif self.role == RobotRole.ATTACKER:
            # Attacker: seek and destroy enemies
            if len(enemies) > 0:
                nearest_enemy = min(enemies, key=lambda r: self.position.distance_to(r.position))
                if self.position.distance_to(nearest_enemy.position) <= self.weapon.range * 1.2:
                    self.target = nearest_enemy.id
                    return f"attack_{nearest_enemy.id}"
                else:
                    # Move toward nearest enemy
                    self.target = nearest_enemy.id
                    return f"move_to_enemy_{nearest_enemy.id}"

            # If no enemies, go to objective
            if nearest_objective:
                self.target = nearest_objective.id
                return f"move_to_objective_{nearest_objective.id}"

        elif self.role == RobotRole.DEFENDER:
            # Defender: protect base or objective
            if len(enemies) > 0:
                nearest_enemy = min(enemies, key=lambda r: self.position.distance_to(r.position))
                if self.position.distance_to(nearest_enemy.position) <= self.weapon.range:
                    self.target = nearest_enemy.id
                    return f"defend_{nearest_enemy.id}"

                # If enemy is far, move toward objective to defend
                if nearest_objective and nearest_objective.type == ObjectiveType.DEFEND_BASE:
                    self.target = nearest_objective.id
                    return f"defend_objective_{nearest_objective.id}"

            # If no threat, stay near objective
            if nearest_objective:
                self.target = nearest_objective.id
                return f"defend_objective_{nearest_objective.id}"

        elif self.role == RobotRole.SUPPORT:
            # Support: heal teammates or provide cover
            nearest_teammate_in_danger = None
            for teammate in teammates:
                if teammate.health < teammate.max_health * 0.5:
                    if not nearest_teammate_in_danger or teammate.health < nearest_teammate_in_danger.health:
                        nearest_teammate_in_danger = teammate

            if nearest_teammate_in_danger:
                self.target = nearest_teammate_in_danger.id
                return f"heal_teammate_{nearest_teammate_in_danger.id}"

            # If no one needs healing, go to objective
            if nearest_objective:
                self.target = nearest_objective.id
                return f"support_objective_{nearest_objective.id}"

            # Default: find and engage enemy
            if len(enemies) > 0:
                nearest_enemy = min(enemies, key=lambda r: self.position.distance_to(r.position))
                self.target = nearest_enemy.id
                return f"move_to_enemy_{nearest_enemy.id}"

        # Default behavior: move toward nearest objective
        if nearest_objective:
            self.target = nearest_objective.id
            return f"move_to_objective_{nearest_objective.id}"

        # If no objectives, just roam
        return "roam"

@dataclass
class Projectile:
    position: Vector2D
    velocity: Vector2D
    damage: float
    splash_radius: float
    team: str
    source_robot_id: int
    weapon_type: WeaponType
    lifetime: float = 3.0
    age: float = 0.0
    active: bool = True

    def update(self, dt: float, environment: 'Environment') -> bool:
        """Update projectile position and check for expiration or collision"""
        if not self.active:
            return False

        self.age += dt
        self.position += self.velocity * dt

        # Check lifetime
        if self.age >= self.lifetime:
            self.active = False
            return False

        # Check collision with environment
        for obstacle in environment.obstacles:
            if obstacle.contains_point(self.position):
                self.active = False
                return False

        # Check collision with robots
        for robot in environment.robots:
            if robot.team != self.team and not robot.is_dead:
                if self.position.distance_to(robot.position) < 30:  # Collision radius
                    robot.take_damage(self.damage)
                    self.active = False
                    return False

        return True

@dataclass
class Obstacle:
    position: Vector2D
