@dataclass
class Objective:
    id: str
    position: Vector2D
    team: str
    type: ObjectiveType
    progress: float = 0.0
    completed: bool = False
    required_progress: float = 100.0
    capture_radius: float = 80.0
    defending_robots: List[int] = field(default_factory=list)
    spawned_at: float = 0.0

    def update(self, robots: List[Robot], dt: float):
        """Update objective progress based on robots nearby"""
        if self.completed:
            return

        # Count robots from team near objective
        team_robots_nearby = 0
        enemy_robots_nearby = 0

        for robot in robots:
            if robot.position.distance_to(self.position) < self.capture_radius:
                if robot.team == self.team:
                    team_robots_nearby += 1
                else:
                    enemy_robots_nearby += 1

        # Adjust progress based on team control
        if team_robots_nearby > 0 and enemy_robots_nearby == 0:
            self.progress += dt * 10  # Capture rate
        elif enemy_robots_nearby > 0 and team_robots_nearby == 0:
            self.progress -= dt * 8  # Enemy capture rate
        elif team_robots_nearby > 0 and enemy_robots_nearby > 0:
            # Both teams present - slower progress
            self.progress += dt * (team_robots_nearby - enemy_robots_nearby) * 2

        # Clamp progress
        self.progress = max(0, min(self.required_progress, self.progress))

        # Check completion
        if self.progress >= self.required_progress:
            self.completed = True

