class DifficultyLevel:
    """Represents the current difficulty level"""
    level: int = 1
    enemy_count: int = 4
    enemy_accuracy: float = 0.6
    enemy_reaction: float = 0.5
    enemy_teamwork: float = 0.4
    hazard_intensity: float = 0.5
    powerup_frequency: float = 0.3
    objective_frequency: float = 0.2

    def adjust_based_on_performance(self, team_stats: Dict[str, Dict]):
        """Adjust difficulty based on team performance"""
        # Calculate average team performance (win rate, objective success, etc.)
        total_score = 0
        team_count = 0

        for team_name, stats in team_stats.items():
            if stats.get('wins', 0) > 0:
                win_rate = stats.get('wins', 0) / max(1, stats.get('games', 1))
                objective_success = stats.get('objectives_completed', 0) / max(1, stats.get('objectives_attempted', 1))
                total_score += (win_rate * 0.5 + objective_success * 0.5)
                team_count += 1

        if team_count == 0:
            return

        avg_performance = total_score / team_count

        # Adjust difficulty based on performance
        if avg_performance > 0.8 and self.level < 5:
            self.level += 1
            self.enemy_count = min(10, self.enemy_count + 1)
            self.enemy_accuracy = min(0.95, self.enemy_accuracy + 0.05)
            self.enemy_reaction = min(0.9, self.enemy_reaction + 0.05)
            self.enemy_teamwork = min(0.9, self.enemy_teamwork + 0.05)
            self.hazard_intensity = min(1.0, self.hazard_intensity + 0.1)
            self.powerup_frequency = min(0.8, self.powerup_frequency + 0.1)
            self.objective_frequency = min(0.8, self.objective_frequency + 0.1)
        elif avg_performance < 0.3 and self.level > 1:
            self.level -= 1
            self.enemy_count = max(2, self.enemy_count - 1)
            self.enemy_accuracy = max(0.5, self.enemy_accuracy - 0.05)
            self.enemy_reaction = max(0.4, self.enemy_reaction - 0.05)
            self.enemy_teamwork = max(0.3, self.enemy_teamwork - 0.05)
            self.hazard_intensity = max(0.1, self.hazard_intensity - 0.1)
            self.powerup_frequency = max(0.1, self.powerup_frequency - 0.1)
            self.objective_frequency = max(0.1, self.objective_frequency - 0.1)

