@dataclass
class DifficultyLevel:
    """Represents the current difficulty level"""
    level: int = 1
    enemy_count: int = 4
    enemy_accuracy: float = 0.6
    enemy_reaction: float = 0.5
    enemy_teamwork: float = 0.4
    hazard_intensity: float = 0.5
    powerup_frequency: float = 0.3
    objective_frequency: float = 0.2

    def adjust_based_on_performance(self, team_stats: Dict[str, Dict]):
        """Adjust difficulty based on team performance"""
        # Calculate average team performance (win rate, objective success, etc.)
        total_score = 0
        team_count = 0

        for team_name, stats in team_stats.items():
            if stats.get('wins', 0) > 0:
                win_rate = stats.get('wins', 0) / max(1, stats.get('games', 1))
                objective_success = stats.get('objectives_completed', 0) / max(1, stats.get('objectives_attempted', 1))
                total_score += (win_rate * 0.5 + objective_success * 0.5)
                team_count += 1

        if team_count == 0:
            return

        avg_performance = total_score / team_count

        # Adjust difficulty based on performance
        if avg_performance > 0.8 and self.level < 5:
            self.level += 1
            self.enemy_count = min(10, self.enemy_count + 1)
            self.enemy_accuracy = min(0.95, self.enemy_accuracy + 0.05)
            self.enemy_reaction = min(0.9, self.enemy_reaction + 0.05)
            self.enemy_teamwork = min(0.9, self.enemy_teamwork + 0.05)
            self.hazard_intensity = min(1.0, self.hazard_intensity + 0.1)
            self.powerup_frequency = min(0.8, self.powerup_frequency + 0.1)
            self.objective_frequency = min(0.8, self.objective_frequency + 0.1)
        elif avg_performance < 0.3 and self.level > 1:
            self.level -= 1
            self.enemy_count = max(2, self.enemy_count - 1)
            self.enemy_accuracy = max(0.5, self.enemy_accuracy - 0.05)
            self.enemy_reaction = max(0.4, self.enemy_reaction - 0.05)
            self.enemy_teamwork = max(0.3, self.enemy_teamwork - 0.05)
            self.hazard_intensity = max(0.1, self.hazard_intensity - 0.1)
            self.powerup_frequency = max(0.1, self.powerup_frequency - 0.1)
            self.objective_frequency = max(0.1, self.objective_frequency - 0.1)

@dataclass
class GameStats:
    """Tracks game statistics for learning and difficulty adjustment"""
    teams: Dict[str, Dict] = field(default_factory=lambda: defaultdict(lambda: {
        'wins': 0,
        'games': 0,
        'kills': 0,
        'deaths': 0,
        'assists': 0,
        'objectives_completed': 0,
        'objectives_attempted': 0,
        'damage_dealt': 0,
        'damage_taken': 0,
        'heals_given': 0,
        'teamwork_score': 0.0
    }))

    def record_kill(self, killer_team: str, victim_team: str):
        """Record a kill"""
        self.teams[killer_team]['kills'] += 1
        self.teams[victim_team]['deaths'] += 1
        # Increase teamwork score for team of killer
        self.teams[killer_team]['teamwork_score'] += 0.5

    def record_assist(self, team: str):
        """Record an assist"""
        self.teams[team]['assists'] += 1
        self.teams[team]['teamwork_score'] += 0.3

    def record_objective_completed(self, team: str):
        """Record successful objective completion"""
        self.teams[team]['objectives_completed'] += 1
        self.teams[team]['objectives_attempted'] += 1
        self.teams[team]['teamwork_score'] += 2.0

    def record_objective_attempted(self, team: str):
        """Record objective attempt"""
        self.teams[team]['objectives_attempted'] += 1

    def record_damage_dealt(self, team: str, amount: float):
        """Record damage dealt"""
        self.teams[team]['damage_dealt'] += amount

    def record_damage_taken(self, team: str, amount: float):
        """Record damage taken"""
        self.teams[team]['damage_taken'] += amount

    def record_heal(self, team: str):
        """Record healing"""
        self.teams[team]['heals_given'] += 1
        self.teams[team]['teamwork_score'] += 0.8

    def record_game_end(self, winner_team: str):
        """Record end of game"""
        if winner_team:
            self.teams[winner_team]['wins'] += 1
        self.teams[winner_team]['games'] += 1
        for team_name in self.teams:
            if team_name != winner_team:
                self.teams[team_name]['games'] += 1

@dataclass
class Environment:
    """Represents the game environment"""
    width: int = SCREEN_WIDTH
    height: int = SCREEN_HEIGHT
    robots: List[Robot] = field(default_factory=list)
    projectiles: List[Projectile] = field(default_factory=list)
    obstacles: List[Obstacle] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    powerups: List[PowerUp] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    sound_manager: SoundManager = field(default_factory=SoundManager)
    difficulty_level: DifficultyLevel = field(default_factory=DifficultyLevel)
    stats: GameStats = field(default_factory=GameStats)
    time: float = 0.0
    spawn_points: List[Vector2D] = field(default_factory=list)

    def __post_init__(self):
        # Initialize spawn points
        self.spawn_points = [
            Vector2D(100, 100),
            Vector2D(self.width - 100, 100),
            Vector2D(100, self.height - 100),
            Vector2D(self.width - 100, self.height - 100)
        ]

        # Create some obstacles
        self.obstacles = [
            Obstacle(Vector2D(300, 200), 60),
            Obstacle(Vector2D(700, 400), 80),
            Obstacle(Vector2D(500, 600), 50),
            Obstacle(Vector2D(900, 200), 70)
        ]

        # Create some hazards
        self.hazards = [
            Hazard(Vector2D(400, 300), 80, HazardType.LAVA),
            Hazard(Vector2D(800, 500), 70, HazardType.ELECTRIC_FENCE),
            Hazard(Vector2D(600, 150), 60, HazardType.MINEFIELD)
        ]

        # Create some powerups
        powerup_types = [
            PowerUpType.HEALTH_PACK,
            PowerUpType.SPEED_BOOST,
            PowerUpType.SHIELD,
            PowerUpType.WEAPON_UPGRADE
        ]

        for _ in range(3):
            x = random.randint(100, self.width - 100)
            y = random.randint(100, self.height - 100)
            powerup_type = random.choice(powerup_types)
            self.powerups.append(PowerUp(
                Vector2D(x, y),
                powerup_type,
                duration=15.0
            ))

        # Create objectives
        self.objectives = [
            Objective(
                id="flag_red",
                position=Vector2D(200, 400),
                team="RED",
                type=ObjectiveType.CAPTURE_FLAG
            ),
            Objective(
                id="flag_blue",
                position=Vector2D(1000, 400),
                team="BLUE",
                type=ObjectiveType.CAPTURE_FLAG
            ),
            Objective(
                id="base_red",
                position=Vector2D(150, 400),
                team="RED",
                type=ObjectiveType.DEFEND_BASE
            ),
            Objective(
                id="base_blue",
                position=Vector2D(1050, 400),
                team="BLUE",
                type=ObjectiveType.DEFEND_BASE
            )
        ]

    def update(self, dt: float):
        """Update all entities in the environment"""
        self.time += dt

        # Update robots
        for robot in self.robots:
            robot.update(dt, self)

        # Update projectiles
        for projectile in self.projectiles[:]:
            if not projectile.update(dt, self):
                self.projectiles.remove(projectile)

        # Update objectives
        for obj in self.objectives:
            obj.update(self.robots, dt)

        # Update powerups
        for powerup in self.powerups:
            if powerup.collected:
                continue
            # Check for collection
            for robot in self.robots:
                if robot.team == powerup.team or powerup.team == "NEUTRAL":
                    if robot.position.distance_to(powerup.position) < powerup.pickup_radius:
                        self.apply_powerup(robot, powerup)
                        powerup.collected = True

        # Spawn new powerups occasionally
        if random.random() < self.difficulty_level.powerup_frequency * dt:
            x = random.randint(100, self.width - 100)
            y = random.randint(100, self.height - 100)
            powerup_type = random.choice([
                PowerUpType.HEALTH_PACK,
                PowerUpType.SPEED_BOOST,
                PowerUpType.SHIELD,
                PowerUpType.WEAPON_UPGRADE
            ])
            self.powerups.append(PowerUp(
                Vector2D(x, y),
                powerup_type,
                duration=15.0
            ))

        # Spawn new objectives occasionally
        if random.random() < self.difficulty_level.objective_frequency * dt and len(self.objectives) < 6:
            x = random.randint(100, self.width - 100)
            y = random.randint(100, self.height - 100)
            team = random.choice(["RED", "BLUE"])
            obj_type = random.choice([
                ObjectiveType.CAPTURE_FLAG,
                ObjectiveType.DEFEND_BASE,
                ObjectiveType.ESCORT_PAYLOAD
            ])
            self.objectives.append(Objective(
                id=f"obj_{len(self.objectives)}",
                position=Vector2D(x, y),
                team=team,
                type=obj_type
            ))

        # Spawn new robots if needed (for AI control)
        red_count = len([r for r in self.robots if r.team == "RED"])
        blue_count = len([r for r in self.robots if r.team == "BLUE"])

        # Ensure minimum team size
        if red_count < 2:
            self.spawn_robot("RED")
        if blue_count < 2:
            self.spawn_robot("BLUE")

        # Spawn more robots based on difficulty
        if red_count < self.difficulty_level.enemy_count:
            if random.random() < dt * 0.1:
                self.spawn_robot("RED")

        if blue_count < self.difficulty_level.enemy_count:
            if random.random() < dt * 0.1:
                self.spawn_robot("BLUE")

    def spawn_robot(self, team: str) -> Robot:
        """Spawn a new robot at a spawn point"""
        spawn_point = random.choice(self.spawn_points)
        role = random.choice(list(RobotRole))

        # Adjust robot skills based on difficulty
        accuracy = random.uniform(
            self.difficulty_level.enemy_accuracy - 0.1, 
            self.difficulty_level.enemy_accuracy + 0.1
        )
        tactics = random.uniform(
            self.difficulty_level.enemy_teamwork - 0.1, 
            self.difficulty_level.enemy_teamwork + 0.1
        )
        reaction = random.uniform(
            self.difficulty_level.enemy_reaction - 0.1, 
            self.difficulty_level.enemy_reaction + 0.1
        )

        robot = Robot(
            id=len(self.robots),
            team=team,
            position=spawn_point,
            speed=5.0 + random.uniform(-1, 1),
            role=role,
            skills={
                "accuracy": max(0.3, min(0.95, accuracy)),
                "tactics": max(0.3, min(0.95, tactics)),
                "reaction": max(0.3, min(0.95, reaction)),
                "teamwork": random.uniform(0.3, 0.9)
            }
        )

        # Choose weapon based on role
        if role == RobotRole.ATTACKER:
            robot.weapon = Weapon(
                name="Plasma Rifle",
                type=WeaponType.RANGED,
                damage=25.0,
                range=300.0,
                cooldown=0.5,
                ammo=50,
                max_ammo=50,
                splash_radius=10.0,
                fire_sound="pew"
            )
        elif role == RobotRole.DEFENDER:
            robot.weapon = Weapon(
                name="Heavy Cannon",
                type=WeaponType.RANGED,
                damage=40.0,
                range=250.0,
                cooldown=1.5,
                ammo=20,
                max_ammo=20,
                splash_radius=15.0,
                fire_sound="boom"
            )
        elif role == RobotRole.SUPPORT:
            robot.weapon = Weapon(
                name="Healing Beam",
                type=WeaponType.SPECIAL,
                damage=0.0,
                range=200.0,
                cooldown=1.0,
                ammo=-1,
                max_ammo=-1,
                splash_radius=50.0,
                fire_sound="shhh"
            )
        else:  # SCOUT
            robot.weapon = Weapon(
                name="Stun Pistol",
                type=WeaponType.RANGED,
                damage=15.0,
                range=200.0,
                cooldown=0.3,
                ammo=80,
                max_ammo=80,
                splash_radius=5.0,
                fire_sound="pew"
            )

        self.robots.append(robot)
        return robot

    def apply_powerup(self, robot: Robot, powerup: PowerUp):
        """Apply powerup effect to robot"""
        if powerup.type == PowerUpType.HEALTH_PACK:
            robot.heal(powerup.value)
        elif powerup.type == PowerUpType.SPEED_BOOST:
            robot.speed *= powerup.value
            # Reset speed after duration
