    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive or not self.robot.target:
            return False

        # Check if we can attack (cooldown)
        if time.time() - self.last_attack_time < self.robot.weapon.fire_rate:
            return False

        nearest_enemy = self._find_nearest_enemy(environment)
        if not nearest_enemy:
            return False

        distance = self.robot.position.distance_to(nearest_enemy.position)
        if distance <= self.robot.weapon.range:
            # Apply damage
