        # Only support robots can use this ability
        if self.robot.role != Role.SUPPORT:
            return False

        # Check if we have a target
        if not self.robot.target:
            return False

        # Check cooldown
        if time.time() - self.last_use_time < 3.0:  # 3-second cooldown
            return False

        # Find teammate at target position
        teammates = [r for r in environment.robots 
                    if r.team == self.robot.team and r.is_alive 
                    and r.position.distance_to(self.robot.target) < 10.0]

        if teammates:
            teammate = teammates[0]
            # Apply healing
            heal_amount = 25.0
            teammate.heal(heal_amount)
            self.last_use_time = time.time()
            logger.info(f"Robot {self.robot.id} healed {teammate.id} by {heal_amount}")
            return True

        return False

class NodeProtectTeammate(Node):
    """Protect teammate by positioning between them and nearest enemy"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive:
            return False

        # Find nearest teammate
        teammates = [r for r in environment.robots if r.team == self.robot.team and r.is_alive and r != self.robot]
        if not teammates:
            return False

        # Find nearest enemy
        enemies = [r for r in environment.robots if r.team != self.robot.team and r.is_alive]
        if not enemies:
            return False

        # Pick a teammate to protect (lowest health)
        target_teammate = min(teammates, key=lambda r: r.health / r.max_health)
        nearest_enemy = min(enemies, key=lambda r: target_teammate.position.distance_to(r.position))

        # Calculate position between teammate and enemy
        if target_teammate.position.distance_to(nearest_enemy.position) > 0:
            direction = target_teammate.position - nearest_enemy.position
            direction = direction.normalize()
            # Position 10 units from teammate toward enemy
            self.robot.target = target_teammate.position + direction * 10.0
            return True

        return False

class NodeDefendObjective(Node):
    """Defend an objective"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive:
            return False

        # Find closest objective that needs defending
        objectives = [obj for obj in environment.objectives if obj.team == self.robot.team and obj.captured_by == self.robot.team]
        if not objectives:
            return False

        # Find the most threatened objective
        threat_objective = min(objectives, key=lambda obj: obj.progress / obj.max_progress)

        # Move to objective
        self.robot.target = threat_objective.position
