    def take_damage(self, damage: float) -> bool:
        """Apply damage to robot and return True if robot is killed"""
        if not self.is_alive:
            return False

        self.health -= damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
            logger.info(f"Robot {self.id} from {self.team} has been eliminated!")
            return True
        return False

    def heal(self, amount: float) -> None:
        """Heal robot by specified amount"""
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)

    def add_power_up(self, power_up_type: PowerUpType, duration: float) -> None:
        """Add a power-up with specified duration"""
        if not self.is_alive:
            return
        self.power_ups[power_up_type] = duration
        logger.info(f"Robot {self.id} picked up {power_up_type.value} for {duration:.1f}s")

    def update_power_ups(self, delta_time: float) -> None:
        """Update all active power-ups, remove expired ones"""
        expired = []
        for power_up_type, duration in self.power_ups.items():
            self.power_ups[power_up_type] = duration - delta_time
            if self.power_ups[power_up_type] <= 0:
                expired.append(power_up_type)

        for exp in expired:
            del self.power_ups[exp]
            logger.info(f"Robot {self.id} power-up {exp.value} expired")

    def get_speed_multiplier(self) -> float:
        """Calculate speed multiplier based on active power-ups"""
        multiplier = 1.0
        if PowerUpType.SPEED_BOOST in self.power_ups:
            multiplier += 0.5  # 50% speed boost
        return multiplier

    def get_damage_multiplier(self) -> float:
        """Calculate damage multiplier based on active power-ups"""
        multiplier = 1.0
        if PowerUpType.DAMAGE_BOOST in self.power_ups:
            multiplier += 0.75  # 75% damage boost
        return multiplier

    def get_shield_active(self) -> bool:
        """Check if shield power-up is active"""
        return PowerUpType.SHIELD in self.power_ups

