        if self.robot.weapon.ammo <= 0:
            # Simulate reload - in real implementation, this would take time
            self.robot.weapon.ammo = self.robot.weapon.max_ammo
            logger.info(f"Robot {self.robot.id} reloaded")
        return True

class NodeAttackTarget(Node):
    """Attack target if in range"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot
        self.last_attack_time = 0.0

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive or not self.robot.target:
            return False

        # Check if we can attack (cooldown)
        if time.time() - self.last_attack_time < self.robot.weapon.fire_rate:
            return False

        nearest_enemy = self._find_nearest_enemy(environment)
        if not nearest_enemy:
            return False

        distance = self.robot.position.distance_to(nearest_enemy.position)
        if distance <= self.robot.weapon.range:
            # Apply damage
            damage = self.robot.weapon.damage * self.robot.get_damage_multiplier()
            if nearest_enemy.take_damage(damage):
                # Robot eliminated, update stats
                environment.stats.team_kills[self.robot.team] += 1
                environment.stats.team_scores[self.robot.team] += 10
                logger.info(f"Robot {self.robot.id} eliminated {nearest_enemy.id}!")

            self.last_attack_time = time.time()
            return True

        return False

    def _find_nearest_enemy(self, environment: 'GameEnvironment') -> Optional[Robot]:
        enemy_robots = [r for r in environment.robots if r.team != self.robot.team and r.is_alive]
        if not enemy_robots:
            return None
        return min(enemy_robots, key=lambda r: self.robot.position.distance_to(r.position))

class NodeMoveToTarget(Node):
    """Move toward target position"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive or not self.robot.target:
            return False

        # Calculate direction to target
        direction = self.robot.target - self.robot.position
        if direction.x == 0 and direction.y == 0:
            return True  # Already at target

        # Normalize and move
        direction = direction.normalize()
        move_distance = self.robot.speed * self.robot.get_speed_multiplier() * delta_time
        new_position = self.robot.position + direction * move_distance

        # Check for collisions with hazards
        for hazard in environment.hazards:
            if hazard.active and hazard.position.distance_to(new_position) < hazard.radius:
                # Avoid hazard
                # Simple evasion: move perpendicular to hazard
                hazard_dir = self.robot.position - hazard.position
                if hazard_dir.x != 0 or hazard_dir.y != 0:
                    hazard_dir = hazard_dir.normalize()
                    # Rotate 90 degrees
                    perpendicular = Vector2D(-hazard_dir.y, hazard_dir.x)
                    new_position = self.robot.position + perpendicular * move_distance

        self.robot.position = new_position
        return True

class NodeGoToRandomPatrolPoint(Node):
    """Move to a random patrol point"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot
        self.patrol_points: List[Vector2D] = []
        self.current_patrol_point: Optional[Vector2D] = None
        self.last_point_time = 0.0

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive:
            return False

        # Generate patrol points if needed
        if not self.patrol_points:
            # Create random patrol points around the arena
            arena_size = 200.0
            for _ in range(5):
                self.patrol_points.append(Vector2D(
                    random.uniform(-arena_size/2, arena_size/2),
                    random.uniform(-arena_size/2, arena_size/2)
                ))
            self.current_patrol_point = random.choice(self.patrol_points)

        # If we reached current point, pick new one
        if self.current_patrol_point and self.robot.position.distance_to(self.current_patrol_point) < 5.0:
            self.current_patrol_point = random.choice(self.patrol_points)

        # Move toward patrol point
        if self.current_patrol_point:
            direction = self.current_patrol_point - self.robot.position
            if direction.x != 0 or direction.y != 0:
                direction = direction.normalize()
                move_distance = self.robot.speed * self.robot.get_speed_multiplier() * delta_time
                self.robot.position = self.robot.position + direction * move_distance

        return True

class NodeFindLowHealthTeammate(Node):
    """Find teammate with low health"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive:
            return False

        teammates = [r for r in environment.robots if r.team == self.robot.team and r.is_alive and r != self.robot]
        if not teammates:
            return False

        # Find teammate with lowest health percentage
        low_health_teammate = min(teammates, key=lambda r: r.health / r.max_health)

        # If teammate is below 50% health, target them
        if low_health_teammate.health / low_health_teammate.max_health < 0.5:
            self.robot.target = low_health_teammate.position
            return True

        return False

class NodeUseSupportAbility(Node):
    """Use support ability on targeted teammate"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot
        self.last_use_time = 0.0

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive:
            return False

        # Only support robots can use this ability
        if self.robot.role != Role.SUPPORT:
            return False

        # Check if we have a target
        if not self.robot.target:
            return False

        # Check cooldown
        if time.time() - self.last_use_time < 3.0:  # 3-second cooldown
            return False

        # Find teammate at target position
        teammates = [r for r in environment.robots 
                    if r.team == self.robot.team and r.is_alive 
                    and r.position.distance_to(self.robot.target) < 10.0]

        if teammates:
            teammate = teammates[0]
            # Apply healing
            heal_amount = 25.0
            teammate.heal(heal_amount)
            self.last_use_time = time.time()
            logger.info(f"Robot {self.robot.id} healed {teammate.id} by {heal_amount}")
            return True

        return False

class NodeProtectTeammate(Node):
    """Protect teammate by positioning between them and nearest enemy"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive:
            return False

        # Find nearest teammate
        teammates = [r for r in environment.robots if r.team == self.robot.team and r.is_alive and r != self.robot]
        if not teammates:
            return False

        # Find nearest enemy
        enemies = [r for r in environment.robots if r.team != self.robot.team and r.is_alive]
        if not enemies:
            return False

        # Pick a teammate to protect (lowest health)
        target_teammate = min(teammates, key=lambda r: r.health / r.max_health)
        nearest_enemy = min(enemies, key=lambda r: target_teammate.position.distance_to(r.position))

        # Calculate position between teammate and enemy
        if target_teammate.position.distance_to(nearest_enemy.position) > 0:
            direction = target_teammate.position - nearest_enemy.position
            direction = direction.normalize()
            # Position 10 units from teammate toward enemy
            self.robot.target = target_teammate.position + direction * 10.0
            return True

        return False

class NodeDefendObjective(Node):
    """Defend an objective"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive:
            return False

        # Find closest objective that needs defending
        objectives = [obj for obj in environment.objectives if obj.team == self.robot.team and obj.captured_by == self.robot.team]
        if not objectives:
            return False

        # Find the most threatened objective
        threat_objective = min(objectives, key=lambda obj: obj.progress / obj.max_progress)

        # Move to objective
        self.robot.target = threat_objective.position
        return True

class NodeWait(Node):
    """Wait for specified time"""

    def __init__(self, duration: float):
        super().__init__()
        self.duration = duration
        self.start_time = 0.0
        self.waiting = False

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.waiting:
            self.start_time = time.time()
            self.waiting = True

        if time.time() - self.start_time > self.duration:
            self.waiting = False
            return True

        return True  # Continue waiting

