class GameEnvironment:
    """Main game environment that manages robots, objectives, hazards, and power-ups"""

    def __init__(self, map_size: float = 200.0):
        self.map_size = map_size
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []
        self.stats = GameStats()
        self.game_time = 0.0
        self.battle_started = False
        self.battle_end_time = 0.0
        self.difficulty_level = 1.0  # 1.0 = normal, >1.0 = harder
        self.previous_performance = 0.0  # Track performance for adaptive difficulty
        self.learning_buffer: List[Dict] = []  # Buffer for learning from past battles

        # Initialize with some objectives
        self._initialize_objectives()

        # Initialize power-ups
        self._spawn_power_ups()

        # Initialize hazards
        self._spawn_hazards()

    def _initialize_objectives(self):
        """Initialize game objectives"""
        # Capture the flag objective
        self.objectives.append(Objective(
            type=ObjectiveType.CAPTURE_FLAG,
            position=Vector2D(-50, 0),
            team=Team.RED,
            radius=20.0
        ))

        self.objectives.append(Objective(
            type=ObjectiveType.CAPTURE_FLAG,
            position=Vector2D(50, 0),
            team=Team.BLUE,
            radius=20.0
        ))

        # Defend base objective
        self.objectives.append(Objective(
            type=ObjectiveType.DEFEND_BASE,
            position=Vector2D(-70, -30),
            team=Team.RED,
            radius=25.0,
            max_progress=150.0
        ))

        self.objectives.append(Objective(
            type=ObjectiveType.DEFEND_BASE,
            position=Vector2D(70, 30),
            team=Team.BLUE,
            radius=25.0,
            max_progress=150.0
        ))

    def _spawn_power_ups(self):
        """Spawn power-ups at random locations"""
        power_up_types = [
            PowerUpType.HEALTH_BOOST, 
            PowerUpType.SPEED_BOOST, 
            PowerUpType.DAMAGE_BOOST, 
            PowerUpType.SHIELD
        ]

        for _ in range(4):  # Spawn 4 power-ups
            power_up_type = random.choice(power_up_types)
            position = Vector2D(
                random.uniform(-self.map_size/2 + 20, self.map_size/2 - 20),
                random.uniform(-self.map_size/2 + 20, self.map_size/2 - 20)
            )
            self.power_ups.append(PowerUp(
                type=power_up_type,
                position=position,
                spawn_time=self.game_time,
                duration=60.0
            ))

    def _spawn_hazards(self):
        """Spawn environmental hazards"""
        hazard_types = [
            HazardType.ELECTRIC_FLOOR,
            HazardType.FIRE_ZONE,
            HazardType.TOXIC_GAS
        ]

        for _ in range(3):  # Spawn 3 hazards
            hazard_type = random.choice(hazard_types)
            position = Vector2D(
                random.uniform(-self.map_size/2 + 30, self.map_size/2 - 30),
                random.uniform(-self.map_size/2 + 30, self.map_size/2 - 30)
            )
            self.hazards.append(Hazard(
                type=hazard_type,
                position=position,
                radius=15.0,
                damage_per_second=3.0 + random.random() * 2.0
            ))

    def add_robot(self, robot: Robot) -> None:
        """Add a robot to the arena"""
        # Set initial position for robot
        if len([r for r in self.robots if r.team == robot.team]) == 0:
            # First robot of team - place near their base
            robot.position = Vector2D(-30 if robot.team == Team.RED else 30, 0)
        else:
            # Place near existing teammates
            teammates = [r for r in self.robots if r.team == robot.team]
            if teammates:
                avg_pos = Vector2D(
                    sum(r.position.x for r in teammates) / len(teammates),
                    sum(r.position.y for r in teammates) / len(teammates)
                )
                # Place at a slight offset
                offset = Vector2D(random.uniform(-10, 10), random.uniform(-10, 10))
                robot.position = avg_pos + offset

        self.robots.append(robot)
        logger.info(f"Robot {robot.id} added to {robot.team.value} team")

    def remove_robot(self, robot: Robot) -> None:
        """Remove a robot from the arena"""
        if robot in self.robots:
            self.robots.remove(robot)
            logger.info(f"Robot {robot.id} removed from arena")

    def update(self, delta_time: float) -> None:
        """Update the game environment"""
        self.game_time += delta_time

        # Update power-ups
        for power_up in self.power_ups[:]:
            if power_up.is_expired(self.game_time):
                power_up.active = False
                self.power_ups.remove(power_up)
                logger.info(f"Power-up {power_up.type.value} expired")

        # Update hazards
        for hazard in self.hazards:
            if hazard.active:
                # Apply damage to robots in hazard range
                for robot in self.robots:
                    if robot.is_alive and robot.position.distance_to(hazard.position) < hazard.radius:
                        damage = hazard.affect_robot(robot)
                        robot.take_damage(damage)

        # Update robot power-ups
        for robot in self.robots:
            robot.update_power_ups(delta_time)

        # Update objectives
        for objective in self.objectives:
            # Calculate progress based on robots near objective
            allies = [r for r in self.robots if r.team == objective.team and r.is_alive and 
                     r.position.distance_to(objective.position) < objective.radius]
            enemies = [r for r in self.robots if r.team != objective.team and r.is_alive and 
                      r.position.distance_to(objective.position) < objective.radius]

            if len(allies) > len(enemies):
                objective.update_progress(objective.team, 1.0 * delta_time)  # Defending progress
            elif len(enemies) > len(allies):
                objective.update_progress(objective.team, 1.5 * delta_time)  # Attacking progress

            # Award points for objective progress
            if objective.captured_by and objective.progress >= objective.max_progress:
                self.stats.team_scores[objective.captured_by] += 0.5 * delta_time

        # Update robot AI behavior
        for robot in self.robots:
            if not robot.is_alive:
                continue

            # Choose behavior based on role
            behavior = self._select_behavior(robot)
            action = behavior.update(self, delta_time)

            # Apply action effects
            if action == "attack":
                self._execute_attack(robot)
            elif action == "support":
                self._execute_support(robot)
            elif action == "patrol":
                self._execute_patrol(robot)

            # Update robot's knowledge base with recent experiences
            self._update_knowledge_base(robot)

        # Adaptive difficulty system
        self._adjust_difficulty()

        # Check for battle end conditions
        self._check_battle_end()

    def _select_behavior(self, robot: Robot) -> BehaviorTree:
        """Select appropriate behavior tree based on robot's role"""
        if robot.role == Role.ATTACKER:
            return AttackBehavior(robot)
        elif robot.role == Role.SUPPORT:
            return SupportBehavior(robot)
        elif robot.role == Role.DEFENDER:
            return PatrolBehavior(robot)
        elif robot.role == Role.SCOUT:
            return PatrolBehavior(robot)
        else:  # CONTROLLER
            return AttackBehavior(robot)

