        """Execute patrol actions"""
        # This is handled by the behavior tree
        pass

    def _update_knowledge_base(self, robot: Robot) -> None:
        """Update robot's knowledge base with recent battle experiences"""
        # Store recent performance metrics
        recent_performance = {
            "timestamp": self.game_time,
            "health": robot.health,
            "kills": self.stats.team_kills[robot.team],
            "objectives_scored": self.stats.team_objectives_completed[robot.team],
            "teamwork": self._calculate_teamwork_score(robot)
        }

        # Keep only last 50 entries
        if len(self.learning_buffer) > 50:
            self.learning_buffer.pop(0)

        self.learning_buffer.append(recent_performance)

        # Update knowledge base with patterns
        if len(self.learning_buffer) >= 10:
            # Simple learning: if robot has been doing well, try more aggressive tactics
            recent_avg_health = sum(p["health"] for p in self.learning_buffer[-10:]) / 10
            recent_avg_kills = sum(p["kills"] for p in self.learning_buffer[-10:]) / 10

            if recent_avg_health > robot.max_health * 0.7 and recent_avg_kills > 1.0:
                # Robot is performing well, be more aggressive
                robot.knowledge_base["aggression_level"] = min(1.0, robot.knowledge_base.get("aggression_level", 0.5) + 0.1)
            else:
                # Robot is struggling, be more defensive
                robot.knowledge_base["aggression_level"] = max(0.1, robot.knowledge_base.get("aggression_level", 0.5) - 0.05)

    def _calculate_teamwork_score(self, robot: Robot) -> float:
        """Calculate a teamwork score based on robot's collaborative behavior"""
        if not robot.is_alive:
            return 0.0

        # Count how many teammates are alive and nearby
        nearby_teammates = len([r for r in self.robots 
                               if r.team == robot.team and r.is_alive 
                               and r.position.distance_to(robot.position) < 30.0])

        # Count how many objectives the team has captured
        team_objectives_captured = sum(1 for obj in self.objectives 
                                      if obj.captured_by == robot.team)

        # Calculate score (0.0 to 1.0)
