@dataclass
class Robot:
    id: str = field(default_factory=lambda: str(uuid.uuid4())[:8])
    team: Team = Team.RED
    position: Vector2D = field(default_factory=Vector2D)
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 5.0
    role: Role = Role.ATTACKER
    weapon: Weapon = field(default_factory=lambda: Weapon(WeaponType.RANGED, 25.0, 100.0, 1.0, 30, 30, "Plasma Rifle"))
    inventory: List[Weapon] = field(default_factory=list)
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)  # power_up_type -> duration
    is_alive: bool = True
    last_action_time: float = 0.0
    knowledge_base: Dict[str, Any] = field(default_factory=dict)  # For learning from past battles
    target: Optional[Vector2D] = None
    objective: Optional[ObjectiveType] = None
    team_roles: Dict[str, Role] = field(default_factory=dict)  # Role assignments within team

    def take_damage(self, damage: float) -> bool:
        """Apply damage to robot and return True if robot is killed"""
        if not self.is_alive:
            return False

        self.health -= damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
            logger.info(f"Robot {self.id} from {self.team} has been eliminated!")
            return True
        return False

    def heal(self, amount: float) -> None:
        """Heal robot by specified amount"""
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)

    def add_power_up(self, power_up_type: PowerUpType, duration: float) -> None:
        """Add a power-up with specified duration"""
        if not self.is_alive:
            return
        self.power_ups[power_up_type] = duration
        logger.info(f"Robot {self.id} picked up {power_up_type.value} for {duration:.1f}s")

    def update_power_ups(self, delta_time: float) -> None:
        """Update all active power-ups, remove expired ones"""
        expired = []
        for power_up_type, duration in self.power_ups.items():
            self.power_ups[power_up_type] = duration - delta_time
            if self.power_ups[power_up_type] <= 0:
                expired.append(power_up_type)

        for exp in expired:
            del self.power_ups[exp]
            logger.info(f"Robot {self.id} power-up {exp.value} expired")

    def get_speed_multiplier(self) -> float:
        """Calculate speed multiplier based on active power-ups"""
        multiplier = 1.0
        if PowerUpType.SPEED_BOOST in self.power_ups:
            multiplier += 0.5  # 50% speed boost
        return multiplier

    def get_damage_multiplier(self) -> float:
        """Calculate damage multiplier based on active power-ups"""
        multiplier = 1.0
        if PowerUpType.DAMAGE_BOOST in self.power_ups:
            multiplier += 0.75  # 75% damage boost
        return multiplier

    def get_shield_active(self) -> bool:
        """Check if shield power-up is active"""
        return PowerUpType.SHIELD in self.power_ups

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team: Team
    progress: float = 0.0  # 0.0 to 1.0
    max_progress: float = 100.0
    radius: float = 15.0
    captured_by: Optional[Team] = None
    defenders: List[str] = field(default_factory=list)  # Robot IDs defending this objective
    attackers: List[str] = field(default_factory=list)  # Robot IDs attacking this objective

    def is_captured(self) -> bool:
        return self.progress >= self.max_progress

    def update_progress(self, team: Team, delta: float) -> None:
        """Update progress based on team interaction"""
        if team == self.team:
            self.progress = max(0, self.progress - delta)  # Defending team reduces progress
        else:
            self.progress = min(self.max_progress, self.progress + delta)  # Attacking team increases progress

        if self.progress >= self.max_progress:
            self.captured_by = team
        elif self.progress <= 0:
            self.captured_by = None

