class BehaviorTree(ABC):
    """Abstract base class for AI behavior trees"""

    def __init__(self, robot: Robot):
        self.robot = robot
        self.root_node = self.build_tree()

    @abstractmethod
    def build_tree(self):
        """Build the behavior tree structure"""
        pass

    @abstractmethod
    def update(self, environment: 'GameEnvironment', delta_time: float) -> str:
        """Update the behavior tree and return current action"""
        pass

class PatrolBehavior(BehaviorTree):
    """Patrol behavior for scouts and defenders"""

    def build_tree(self):
        return NodeSequence([
            NodeSelector([
                NodeCheckTargetInRange(self.robot, 30.0),
                NodeGoToRandomPatrolPoint(self.robot)
            ]),
            NodeWait(2.0)
        ])

    def update(self, environment: 'GameEnvironment', delta_time: float) -> str:
        # Return "patrol" as action
        return "patrol"

class AttackBehavior(BehaviorTree):
    """Aggressive attack behavior"""

    def build_tree(self):
        return NodeSequence([
            NodeFindNearestEnemy(self.robot),
            NodeCheckWeaponAmmo(self.robot),
            NodeAttackTarget(self.robot),
            NodeMoveToTarget(self.robot)
        ])

    def update(self, environment: 'GameEnvironment', delta_time: float) -> str:
        return "attack"

class SupportBehavior(BehaviorTree):
    """Support behavior for healers and buffer robots"""

    def build_tree(self):
        return NodeSequence([
            NodeFindLowHealthTeammate(self.robot),
            NodeUseSupportAbility(self.robot),
            NodeProtectTeammate(self.robot),
            NodeDefendObjective(self.robot)
        ])

    def update(self, environment: 'GameEnvironment', delta_time: float) -> str:
        return "support"

class Node(ABC):
    """Abstract base class for behavior tree nodes"""

    def __init__(self):
        self.children: List['Node'] = []

    @abstractmethod
    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        pass

class NodeSequence(Node):
    """Sequence node: executes children in order until one fails"""

    def __init__(self, children: List[Node]):
        super().__init__()
        self.children = children

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        for child in self.children:
            if not child.evaluate(environment, delta_time):
                return False
        return True

class NodeSelector(Node):
    """Selector node: executes children until one succeeds"""

    def __init__(self, children: List[Node]):
        super().__init__()
        self.children = children

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        for child in self.children:
            if child.evaluate(environment, delta_time):
                return True
        return False

class NodeCheckTargetInRange(Node):
    """Check if enemy is within attack range"""

    def __init__(self, robot: Robot, range_threshold: float):
        super().__init__()
        self.robot = robot
        self.range_threshold = range_threshold

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive:
            return False
        nearest_enemy = self._find_nearest_enemy(environment)
        if nearest_enemy and self.robot.position.distance_to(nearest_enemy.position) <= self.range_threshold:
            return True
        return False

    def _find_nearest_enemy(self, environment: 'GameEnvironment') -> Optional[Robot]:
        enemy_robots = [r for r in environment.robots if r.team != self.robot.team and r.is_alive]
        if not enemy_robots:
            return None
        return min(enemy_robots, key=lambda r: self.robot.position.distance_to(r.position))

class NodeFindNearestEnemy(Node):
    """Find nearest enemy robot"""

    def __init__(self, robot: Robot):
        super().__init__()
        self.robot = robot

    def evaluate(self, environment: 'GameEnvironment', delta_time: float) -> bool:
        if not self.robot.is_alive:
            return False
        enemy_robots = [r for r in environment.robots if r.team != self.robot.team and r.is_alive]
        if enemy_robots:
            nearest = min(enemy_robots, key=lambda r: self.robot.position.distance_to(r.position))
            self.robot.target = nearest.position
            return True
        return False

class NodeCheckWeaponAmmo(Node):
