# Enum for export formats
class ExportFormat(Enum):
    CSV = "csv"
    EXCEL = "excel"
    DATABASE = "database"

# Enum for validation status
class ValidationStatus(Enum):
    PENDING = "pending"
    PASSED = "passed"
    FAILED = "failed"

# Enum for stage status
class StageStatus(Enum):
    NOT_STARTED = "not_started"
    IN_PROGRESS = "in_progress"
    COMPLETED = "completed"
    FAILED = "failed"

@dataclass
class DataStage:
    name: str
    status: StageStatus = StageStatus.NOT_STARTED
    result: Optional[Any] = None
    error: Optional[str] = None

@dataclass
class DataFlowCoordinator:
    """Orchestrates data processing through ingestion, validation, transformation, and export stages."""

    def __init__(self):
        self.stages: Dict[str, DataStage] = {
            "ingestion": DataStage("ingestion"),
            "validation": DataStage("validation"),
            "transformation": DataStage("transformation"),
            "export": DataStage("export")
        }
        self.data: Optional[pd.DataFrame] = None
        self.transformation_rules: List[Callable] = []

    def ingest_data(self, source: str, source_type: DataSourceType, **kwargs) -> bool:
        """Ingest data from specified source and validate format."""
        self.stages["ingestion"].status = StageStatus.IN_PROGRESS
        logger.info(f"Starting data ingestion from {source} as {source_type.value}")

        try:
            if source_type == DataSourceType.CSV:
                self.data = pd.read_csv(source)
            elif source_type == DataSourceType.EXCEL:
                sheet_name = kwargs.get('sheet_name', 0)
                self.data = pd.read_excel(source, sheet_name=sheet_name)
            elif source_type == DataSourceType.DATABASE:
                connection_string = kwargs.get('connection_string')
                query = kwargs.get('query')
                if not connection_string or not query:
                    raise ValueError("connection_string and query are required for database ingestion")
                conn = sqlite3.connect(connection_string) if connection_string.endswith('.db') else sqlite3.connect(connection_string)
                self.data = pd.read_sql_query(query, conn)
                conn.close()
            else:
                raise ValueError(f"Unsupported source type: {source_type}")

            # Validate data format: check for non-empty DataFrame
            if self.data is None or self.data.empty:
                raise ValueError("Ingested data is empty")

            self.stages["ingestion"].result = len(self.data)
            self.stages["ingestion"].status = StageStatus.COMPLETED
            logger.info(f"Data ingestion completed successfully. Rows ingested: {len(self.data)}")
            return True

        except Exception as e:
            self.stages["ingestion"].status = StageStatus.FAILED
            self.stages["ingestion"].error = str(e)
            logger.error(f"Data ingestion failed: {e}")
            return False

    def validate_data(self, rules: Optional[List[Callable]] = None) -> bool:
        """Validate data integrity, consistency, accuracy, completeness, and validity."""
        if self.stages["ingestion"].status != StageStatus.COMPLETED:
            logger.error("Validation cannot start until ingestion is completed.")
            return False

        self.stages["validation"].status = StageStatus.IN_PROGRESS
        logger.info("Starting data validation...")

        try:
            if self.data is None:
                raise ValueError("No data available for validation")

            # Default validation rules if none provided
            if rules is None:
                rules = [
                    self._check_completeness,
                    self._check_consistency,
                    self._check_validity
                ]

            for rule in rules:
                if not rule():
                    raise ValueError(f"Validation rule failed: {rule.__name__}")

            self.stages["validation"].status = StageStatus.COMPLETED
            logger.info("Data validation completed successfully.")
            return True

        except Exception as e:
            self.stages["validation"].status = StageStatus.FAILED
            self.stages["validation"].error = str(e)
            logger.error(f"Data validation failed: {e}")
            return False

    def _check_completeness(self) -> bool:
        """Check for missing values in required columns."""
        if self.data is None:
            return False
        missing = self.data.isnull().sum().sum()
        if missing > 0:
            logger.warning(f"Found {missing} missing values in dataset.")
        return missing <= len(self.data) * 0.05  # Allow up to 5% missing

    def _check_consistency(self) -> bool:
        """Check for inconsistent data types and values."""
        if self.data is None:
            return False
        # Check that numeric columns don't contain string values
        numeric_cols = self.data.select_dtypes(include=["number"]).columns
        for col in numeric_cols:
            if self.data[col].dtype == "object":
                try:
                    pd.to_numeric(self.data[col])
                except ValueError:
                    logger.error(f"Inconsistent data in numeric column: {col}")
                    return False
        return True

    def _check_validity(self) -> bool:
        """Check for invalid values (e.g., negative ages, out-of-range dates)."""
        if self.data is None:
