        # Example: Assume any numeric column with negative values is invalid if it shouldn't be
        for col in self.data.select_dtypes(include=["number"]).columns:
            if self.data[col].min() < 0 and col.lower() not in ["cost", "discount", "balance"]:
                logger.warning(f"Potential invalid negative value in column: {col}")
        return True

    def add_transformation_rule(self, rule: Callable) -> None:
        """Add a transformation rule to be applied during transformation stage."""
        self.transformation_rules.append(rule)
        logger.info(f"Transformation rule added: {rule.__name__}")

    def transform_data(self) -> bool:
