from collections import defaultdict, deque

# ============================
# CONFIGURATION AND CONSTANTS
# ============================

# Game Constants
MAX_ROBOTS_PER_TEAM = 5
MAX_TEAMS = 4
MAP_SIZE = (100, 100)  # x, y coordinates
GAME_TICK_RATE = 1/60  # 60 FPS
LEARNING_RATE = 0.1  # For adaptive AI learning
MAX_HISTORY_DEPTH = 100  # Number of past battles to remember
POWERUP_SPAWN_RATE = 0.05  # 5% chance per tick for powerup spawn
Hazard_Density = 0.03  # 3% of map tiles are hazards

# Weapon Types
class WeaponType(Enum):
    RANGED = "ranged"
    MELEE = "melee"
    SUPPORT = "support"
    SPECIAL = "special"

# Robot Roles
class RobotRole(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SUPPORT = "support"
    SCOUT = "scout"
    CONTROLLER = "controller"

# Objectives
class ObjectiveType(Enum):
    FLAG_CAPTURE = "flag_capture"
    BASE_DEFENSE = "base_defense"
    ESCORT_PAYLOAD = "escort_payload"
    DOMINATION = "domination"

# Power-Up Types
class PowerUpType(Enum):
    SPEED_BOOST = "speed_boost"
    DAMAGE_BOOST = "damage_boost"
    SHIELD = "shield"
    REGEN = "regen"
    SILENCE = "silence"
    TELEPORT = "teleport"
    CLONE = "clone"

# Environmental Hazards
class HazardType(Enum):
    ELECTRIC_FLOOR = "electric_floor"
    LAVA_POOL = "lava_pool"
    TRAP_SPOT = "trap_spot"
    GRAVITY_WELL = "gravity_well"
    SLOW_FIELD = "slow_field"

# ============================
# DATA CLASSES
# ============================

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def __add__(self, other: 'Position') -> 'Position':
        return Position(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Position') -> 'Position':
        return Position(self.x - other.x, self.y - other.y)

    def normalize(self) -> 'Position':
        mag = math.sqrt(self.x**2 + self.y**2)
        if mag == 0:
            return Position(0, 0)
        return Position(self.x / mag, self.y / mag)

    def to_tuple(self) -> Tuple[float, float]:
        return (self.x, self.y)

@dataclass
class Robot:
    id: str
    team: str
    role: RobotRole
    position: Position
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 1.5
    weapon: 'Weapon' = None
    shield: float = 0.0
    cooldown: float = 0.0
    is_alive: bool = True
    last_action: str = "idle"
    strategy_memory: List[Dict] = field(default_factory=list)
    role_history: List[RobotRole] = field(default_factory=list)

    def update(self, delta_time: float):
        if self.cooldown > 0:
            self.cooldown -= delta_time
            if self.cooldown < 0:
                self.cooldown = 0

        if self.health <= 0:
            self.is_alive = False
            self.health = 0

@dataclass
class Weapon:
    type: WeaponType
    name: str
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    cooldown: float = 0.0
    ammo: int = -1  # -1 for infinite
    max_ammo: int = -1
    effect: Optional[str] = None  # e.g., "stun", "burn", "heal"

    def can_fire(self) -> bool:
        return self.cooldown <= 0 and (self.ammo > 0 or self.ammo == -1)

    def fire(self) -> Dict[str, Any]:
        if not self.can_fire():
            return {"success": False}
        self.cooldown = self.fire_rate
        if self.ammo > 0:
            self.ammo -= 1
        return {
            "success": True,
            "damage": self.damage,
            "effect": self.effect,
            "type": self.type
        }

@dataclass
class PowerUp:
    type: PowerUpType
    position: Position
    duration: float  # seconds
    value: float  # multiplier or bonus value
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())

    def update(self, current_time: float) -> bool:
        if self.active and (current_time - self.spawn_time) > self.duration:
            self.active = False
        return self.active

@dataclass
class Hazard:
    type: HazardType
    position: Position
    radius: float
    damage_per_second: float
    effect: str  # e.g., "slow", "stun", "damage"
    active: bool = True

    def apply_effect(self, robot: Robot) -> Dict[str, Any]:
        if self.active:
            return {
                "damage": self.damage_per_second * GAME_TICK_RATE,
                "effect": self.effect,
                "applied": True
            }
        return {"applied": False}

@dataclass
class Objective:
    type: ObjectiveType
    position: Position
    team_required: Optional[str] = None
    progress: float = 0.0  # 0.0 to 1.0
    max_progress: float = 1.0
    captured_by: Optional[str] = None
    radius: float = 5.0
    description: str = ""

    def update(self, robots_in_range: List[Robot]):
        if self.type == ObjectiveType.FLAG_CAPTURE:
            team_counts = defaultdict(int)
            for robot in robots_in_range:
                if robot.is_alive:
                    team_counts[robot.team] += 1

            # Capture logic: team with most robots in range gains progress
            if team_counts:
                leading_team = max(team_counts.keys(), key=lambda t: team_counts[t])
                if leading_team:
                    self.team_required = leading_team
                    self.progress = min(self.progress + (team_counts[leading_team] * 0.01 * GAME_TICK_RATE), self.max_progress)
                    if self.progress >= self.max_progress:
                        self.captured_by = leading_team
                        self.progress = self.max_progress
        elif self.type == ObjectiveType.BASE_DEFENSE:
            # Base defense: if enemy robots are near, progress decreases
            enemy_in_range = sum(1 for r in robots_in_range if r.team != self.team_required and r.is_alive)
            if enemy_in_range > 0:
                self.progress = max(0, self.progress - (enemy_in_range * 0.005 * GAME_TICK_RATE))
            else:
                self.progress = min(self.max_progress, self.progress + 0.001 * GAME_TICK_RATE)
        elif self.type == ObjectiveType.ESCORT_PAYLOAD:
            # Payload moves toward target when robots are near
            self.progress = min(self.progress + 0.002 * len(robots_in_range) * GAME_TICK_RATE, self.max_progress)
        elif self.type == ObjectiveType.DOMINATION:
            # Control points: each team gets points for having robots nearby
            team_counts = defaultdict(int)
            for r in robots_in_range:
                if r.is_alive:
                    team_counts[r.team] += 1
            if team_counts:
                leading_team = max(team_counts.keys(), key=lambda t: team_counts[t])
                if leading_team:
                    self.team_required = leading_team
                    self.progress = min(self.progress + (team_counts[leading_team] * 0.005 * GAME_TICK_RATE), self.max_progress)
                    if self.progress >= self.max_progress:
                        self.captured_by = leading_team

@dataclass
class GameState:
    timestamp: float
    teams: Dict[str, List[Robot]]
    objectives: List[Objective]
    powerups: List[PowerUp]
    hazards: List[Hazard]
    score: Dict[str, int] = field(default_factory=dict)
    round_time: float = 0.0
    active: bool = True
    winner: Optional[str] = None
    last_mission_completed: Optional[str] = None
    ai_adaptive_level: float = 0.5  # 0.0 to 1.0, 0.5 is normal
    battle_history: List[Dict] = field(default_factory=list)

# ============================
# UTILITY FUNCTIONS
# ============================

def generate_random_position() -> Position:
    return Position(
        random.uniform(0, MAP_SIZE[0]),
        random.uniform(0, MAP_SIZE[1])
    )

def distance_squared(pos1: Position, pos2: Position) -> float:
    return (pos1.x - pos2.x)**2 + (pos1.y - pos2.y)**2

def in_range(pos1: Position, pos2: Position, range_threshold: float) -> bool:
    return distance_squared(pos1, pos2) <= range_threshold**2

def get_closest_robot(target_pos: Position, robots: List[Robot], team_filter: Optional[str] = None) -> Optional[Robot]:
    closest = None
    min_dist = float('inf')
    for robot in robots:
        if not robot.is_alive:
            continue
        if team_filter and robot.team != team_filter:
            continue
        dist = target_pos.distance_to(robot.position)
        if dist < min_dist:
            min_dist = dist
            closest = robot
    return closest

def get_robots_in_range(pos: Position, robots: List[Robot], range_radius: float, team_filter: Optional[str] = None) -> List[Robot]:
    result = []
    for robot in robots:
        if not robot.is_alive:
            continue
        if team_filter and robot.team != team_filter:
            continue
        if in_range(pos, robot.position, range_radius):
            result.append(robot)
    return result

def calculate_team_score(team: str, game_state: GameState) -> int:
    score = game_state.score.get(team, 0)
    # Add bonus for objectives
    for obj in game_state.objectives:
        if obj.captured_by == team:
            score += 50
    return score

# ============================
# AI BEHAVIOR SYSTEM
# ============================

class RobotAI:
    def __init__(self, robot: Robot, game_state: GameState):
        self.robot = robot
        self.game_state = game_state
        self.target: Optional[Position] = None
        self.last_known_enemy_positions = []
        self.last_known_allied_positions = []
        self.behavior_tree = self.build_behavior_tree()

    def build_behavior_tree(self) -> Dict:
        """Builds a behavior tree for the robot based on its role and current situation."""
        return {
            "priority": [
                self.check_if_dead,
                self.check_objective_completion,
                self.check_for_powerup,
                self.check_for_enemies,
                self.check_for_allies,
                self.move_to_objective,
                self.patrol
            ]
        }

    def check_if_dead(self) -> bool:
        return not self.robot.is_alive

    def check_objective_completion(self) -> bool:
        """Check if objective is close to completion and assist."""
        for obj in self.game_state.objectives:
            if obj.captured_by == self.robot.team and obj.progress >= obj.max_progress * 0.8:
                # Defend the objective
                self.target = obj.position
                return True
            elif obj.captured_by is None and obj.progress < obj.max_progress * 0.5:
                # Try to capture an objective
                if in_range(self.robot.position, obj.position, obj.radius + 3):
                    return True
                self.target = obj.position
                return True
        return False

    def check_for_powerup(self) -> bool:
        """Find and move to nearest powerup."""
        powerups = [p for p in self.game_state.powerups if p.active]
        if not powerups:
            return False

        closest_powerup = min(powerups, key=lambda p: self.robot.position.distance_to(p.position))
        if self.robot.position.distance_to(closest_powerup.position) < 15:
            self.target = closest_powerup.position
            return True
        return False

    def check_for_enemies(self) -> bool:
        """Find and engage nearby enemies."""
        enemies = [r for r in self.game_state.teams.values() for r in r if r.team != self.robot.team and r.is_alive]
        if not enemies:
            return False

        closest_enemy = get_closest_robot(self.robot.position, enemies)
        if closest_enemy and self.robot.weapon and self.robot.weapon.can_fire():
            # Check if in weapon range
            if self.robot.position.distance_to(closest_enemy.position) <= self.robot.weapon.range:
                self.target = closest_enemy.position
                return True
            else:
                # Chase enemy
                self.target = closest_enemy.position
                return True
        return False

    def check_for_allies(self) -> bool:
        """Support allies in danger."""
        allies = [r for r in self.game_state.teams[self.robot.team] if r.is_alive and r != self.robot]
        if not allies:
            return False

        # Find allies with low health
        low_health_allies = [a for a in allies if a.health < a.max_health * 0.3]
        if low_health_allies:
            closest_low_health = min(low_health_allies, key=lambda a: self.robot.position.distance_to(a.position))
            if self.robot.role == RobotRole.SUPPORT and self.robot.weapon.type == WeaponType.SUPPORT:
                self.target = closest_low_health.position
                return True
        return False

    def move_to_objective(self) -> bool:
        """Move toward the nearest objective not owned by team."""
        for obj in self.game_state.objectives:
            if obj.captured_by != self.robot.team:
                # Only move if objective is not too close to enemy team
                if not any(r.team != self.robot.team and r.is_alive for r in get_robots_in_range(obj.position, self.game_state.teams.values(), 10)):
                    self.target = obj.position
                    return True
        return False

    def patrol(self) -> bool:
        """Default behavior: patrol a random area."""
        if self.target is None or self.robot.position.distance_to(self.target) < 2:
            # Choose a random patrol point
            self.target = Position(
                random.uniform(self.robot.position.x - 10, self.robot.position.x + 10),
                random.uniform(self.robot.position.y - 10, self.robot.position.y + 10)
            )
            # Clamp to map
            self.target.x = max(0, min(self.target.x, MAP_SIZE[0]))
            self.target.y = max(0, min(self.target.y, MAP_SIZE[1]))
        return True

    def get_next_action(self) -> str:
        """Execute behavior tree and return the next action."""
        for behavior in self.behavior_tree["priority"]:
            if behavior():
                if self.target:
                    # Move toward target
                    direction = (self.target - self.robot.position).normalize()
                    new_pos = Position(
                        self.robot.position.x + direction.x * self.robot.speed * GAME_TICK_RATE,
                        self.robot.position.y + direction.y * self.robot.speed * GAME_TICK_RATE
                    )
                    # Clamp position
                    new_pos.x = max(0, min(new_pos.x, MAP_SIZE[0]))
                    new_pos.y = max(0, min(new_pos.y, MAP_SIZE[1]))
                    self.robot.position = new_pos
                    self.robot.last_action = "moving"

                    # Check if we can attack
                    if self.robot.weapon and self.robot.weapon.can_fire():
                        # Find enemy in firing range
                        enemies = [r for r in self.game_state.teams.values() for r in r if r.team != self.robot.team and r.is_alive]
                        if enemies:
                            closest_enemy = get_closest_robot(self.robot.position, enemies)
                            if closest_enemy and self.robot.position.distance_to(closest_enemy.position) <= self.robot.weapon.range:
                                fire_result = self.robot.weapon.fire()
                                if fire_result["success"]:
                                    self.robot.last_action = f"attacking_{self.robot.weapon.type.value}"
                                    # Apply damage
                                    if closest_enemy:
                                        damage = fire_result["damage"]
                                        if fire_result.get("effect") == "stun":
                                            closest_enemy.cooldown = 2.0  # Stun for 2 seconds
                                        closest_enemy.health -= damage
                                        # Add feedback to robot's memory
                                        self.robot.strategy_memory.append({
                                            "action": "attack",
                                            "target": closest_enemy.id,
                                            "damage": damage,
                                            "success": True,
                                            "timestamp": time.time()
                                        })
                                        self.robot.role_history.append(self.robot.role)
                                        return "attack"

                return "move"
        return "idle"

    def learn_from_battle(self, battle_outcome: Dict):
        """Learn from past battles to improve future behavior."""
        if not battle_outcome.get("win", False):
            # If we lost, reduce aggression slightly
            self.robot.strategy_memory.append({
                "outcome": "loss",
                "timestamp": time.time()
            })
        else:
            self.robot.strategy_memory.append({
                "outcome": "win",
                "timestamp": time.time()
            })

        # Keep only last 100 entries
        if len(self.robot.strategy_memory) > MAX_HISTORY_DEPTH:
            self.robot.strategy_memory = self.robot.strategy_memory[-MAX_HISTORY_DEPTH:]

        # Adjust role preference based on success
        if len(self.robot.role_history) > 10:
            role_counts = defaultdict(int)
            for role in self.robot.role_history[-10:]:
                role_counts[role] += 1
            most_common_role = max(role_counts.keys(), key=lambda r: role_counts[r])
            if most_common_role != self.robot.role:
                self.robot.role = most_common_role

# ============================
# DYNAMIC ADAPTIVE SYSTEM
# ============================

class AdaptiveDifficulty:
    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.performance_history = deque(maxlen=20)  # Last 20 rounds
        self.difficulty_level = 0.5  # Normal difficulty

    def evaluate_performance(self) -> float:
        """Evaluate team performance based on various metrics."""
        if not self.game_state.teams:
            return 0.5

        team_scores = {}
        for team_name, robots in self.game_state.teams.items():
            alive_count = sum(1 for r in robots if r.is_alive)
            objective_points = sum(1 for obj in self.game_state.objectives if obj.captured_by == team_name)
            kills = sum(1 for r in robots for other in self.game_state.teams.values() for r2 in other if r2.team != team_name and r2.is_alive and r.weapon and r.weapon.cooldown <= 0)
            team_scores[team_name] = alive_count * 10 + objective_points * 50 + kills * 15

        if not team_scores:
            return 0.5

        avg_score = sum(team_scores.values()) / len(team_scores)
        max_score = max(team_scores.values()) if team_scores else 0
        min_score = min(team_scores.values()) if team_scores else 0

        # If one team dominates, difficulty increases for them
        if max_score > 0 and min_score < 0.5 * max_score:
            # Unbalanced game
            return min(1.0, self.difficulty_level + 0.05)
        elif max_score == min_score and max_score > 100:
            # High performance across teams
            return min(1.0, self.difficulty_level + 0.02)
        elif max_score < 50:
            # Low performance, decrease difficulty
            return max(0.0, self.difficulty_level - 0.03)

        return self.difficulty_level

    def adjust_ai_hardness(self):
