@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def __add__(self, other: 'Position') -> 'Position':
        return Position(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Position') -> 'Position':
        return Position(self.x - other.x, self.y - other.y)

    def normalize(self) -> 'Position':
        mag = math.sqrt(self.x**2 + self.y**2)
        if mag == 0:
            return Position(0, 0)
        return Position(self.x / mag, self.y / mag)

    def to_tuple(self) -> Tuple[float, float]:
        return (self.x, self.y)

@dataclass
class Robot:
    id: str
    team: str
    role: RobotRole
    position: Position
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 1.5
    weapon: 'Weapon' = None
    shield: float = 0.0
    cooldown: float = 0.0
    is_alive: bool = True
    last_action: str = "idle"
    strategy_memory: List[Dict] = field(default_factory=list)
    role_history: List[RobotRole] = field(default_factory=list)

    def update(self, delta_time: float):
        if self.cooldown > 0:
            self.cooldown -= delta_time
            if self.cooldown < 0:
                self.cooldown = 0

        if self.health <= 0:
            self.is_alive = False
            self.health = 0

@dataclass
class Weapon:
    type: WeaponType
    name: str
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    cooldown: float = 0.0
    ammo: int = -1  # -1 for infinite
    max_ammo: int = -1
    effect: Optional[str] = None  # e.g., "stun", "burn", "heal"

    def can_fire(self) -> bool:
        return self.cooldown <= 0 and (self.ammo > 0 or self.ammo == -1)

    def fire(self) -> Dict[str, Any]:
        if not self.can_fire():
            return {"success": False}
        self.cooldown = self.fire_rate
        if self.ammo > 0:
            self.ammo -= 1
        return {
            "success": True,
            "damage": self.damage,
            "effect": self.effect,
            "type": self.type
        }

@dataclass
class PowerUp:
    type: PowerUpType
    position: Position
    duration: float  # seconds
    value: float  # multiplier or bonus value
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())

    def update(self, current_time: float) -> bool:
        if self.active and (current_time - self.spawn_time) > self.duration:
            self.active = False
        return self.active

@dataclass
class Hazard:
    type: HazardType
    position: Position
    radius: float
    damage_per_second: float
    effect: str  # e.g., "slow", "stun", "damage"
    active: bool = True

    def apply_effect(self, robot: Robot) -> Dict[str, Any]:
        if self.active:
            return {
                "damage": self.damage_per_second * GAME_TICK_RATE,
                "effect": self.effect,
                "applied": True
            }
        return {"applied": False}

@dataclass
class Objective:
    type: ObjectiveType
    position: Position
    team_required: Optional[str] = None
    progress: float = 0.0  # 0.0 to 1.0
    max_progress: float = 1.0
    captured_by: Optional[str] = None
    radius: float = 5.0
    description: str = ""

    def update(self, robots_in_range: List[Robot]):
        if self.type == ObjectiveType.FLAG_CAPTURE:
            team_counts = defaultdict(int)
            for robot in robots_in_range:
                if robot.is_alive:
                    team_counts[robot.team] += 1

            # Capture logic: team with most robots in range gains progress
            if team_counts:
                leading_team = max(team_counts.keys(), key=lambda t: team_counts[t])
                if leading_team:
                    self.team_required = leading_team
                    self.progress = min(self.progress + (team_counts[leading_team] * 0.01 * GAME_TICK_RATE), self.max_progress)
                    if self.progress >= self.max_progress:
                        self.captured_by = leading_team
                        self.progress = self.max_progress
        elif self.type == ObjectiveType.BASE_DEFENSE:
            # Base defense: if enemy robots are near, progress decreases
            enemy_in_range = sum(1 for r in robots_in_range if r.team != self.team_required and r.is_alive)
            if enemy_in_range > 0:
                self.progress = max(0, self.progress - (enemy_in_range * 0.005 * GAME_TICK_RATE))
            else:
                self.progress = min(self.max_progress, self.progress + 0.001 * GAME_TICK_RATE)
        elif self.type == ObjectiveType.ESCORT_PAYLOAD:
            # Payload moves toward target when robots are near
            self.progress = min(self.progress + 0.002 * len(robots_in_range) * GAME_TICK_RATE, self.max_progress)
        elif self.type == ObjectiveType.DOMINATION:
            # Control points: each team gets points for having robots nearby
            team_counts = defaultdict(int)
            for r in robots_in_range:
                if r.is_alive:
                    team_counts[r.team] += 1
            if team_counts:
                leading_team = max(team_counts.keys(), key=lambda t: team_counts[t])
                if leading_team:
                    self.team_required = leading_team
                    self.progress = min(self.progress + (team_counts[leading_team] * 0.005 * GAME_TICK_RATE), self.max_progress)
                    if self.progress >= self.max_progress:
                        self.captured_by = leading_team

@dataclass
class GameState:
    timestamp: float
    teams: Dict[str, List[Robot]]
    objectives: List[Objective]
    powerups: List[PowerUp]
    hazards: List[Hazard]
    score: Dict[str, int] = field(default_factory=dict)
    round_time: float = 0.0
    active: bool = True
    winner: Optional[str] = None
    last_mission_completed: Optional[str] = None
    ai_adaptive_level: float = 0.5  # 0.0 to 1.0, 0.5 is normal
    battle_history: List[Dict] = field(default_factory=list)

# ============================
# UTILITY FUNCTIONS
# ============================

def generate_random_position() -> Position:
    return Position(
        random.uniform(0, MAP_SIZE[0]),
        random.uniform(0, MAP_SIZE[1])
    )

def distance_squared(pos1: Position, pos2: Position) -> float:
    return (pos1.x - pos2.x)**2 + (pos1.y - pos2.y)**2

def in_range(pos1: Position, pos2: Position, range_threshold: float) -> bool:
    return distance_squared(pos1, pos2) <= range_threshold**2

def get_closest_robot(target_pos: Position, robots: List[Robot], team_filter: Optional[str] = None) -> Optional[Robot]:
    closest = None
    min_dist = float('inf')
    for robot in robots:
        if not robot.is_alive:
            continue
        if team_filter and robot.team != team_filter:
            continue
        dist = target_pos.distance_to(robot.position)
        if dist < min_dist:
            min_dist = dist
            closest = robot
    return closest

def get_robots_in_range(pos: Position, robots: List[Robot], range_radius: float, team_filter: Optional[str] = None) -> List[Robot]:
    result = []
    for robot in robots:
        if not robot.is_alive:
            continue
        if team_filter and robot.team != team_filter:
            continue
        if in_range(pos, robot.position, range_radius):
            result.append(robot)
    return result

def calculate_team_score(team: str, game_state: GameState) -> int:
    score = game_state.score.get(team, 0)
    # Add bonus for objectives
    for obj in game_state.objectives:
        if obj.captured_by == team:
            score += 50
    return score

