# ============================

class RobotAI:
    def __init__(self, robot: Robot, game_state: GameState):
        self.robot = robot
        self.game_state = game_state
        self.target: Optional[Position] = None
        self.last_known_enemy_positions = []
        self.last_known_allied_positions = []
        self.behavior_tree = self.build_behavior_tree()

    def build_behavior_tree(self) -> Dict:
        """Builds a behavior tree for the robot based on its role and current situation."""
        return {
            "priority": [
                self.check_if_dead,
                self.check_objective_completion,
                self.check_for_powerup,
                self.check_for_enemies,
                self.check_for_allies,
                self.move_to_objective,
                self.patrol
            ]
        }

    def check_if_dead(self) -> bool:
        return not self.robot.is_alive

    def check_objective_completion(self) -> bool:
        """Check if objective is close to completion and assist."""
        for obj in self.game_state.objectives:
            if obj.captured_by == self.robot.team and obj.progress >= obj.max_progress * 0.8:
                # Defend the objective
                self.target = obj.position
                return True
            elif obj.captured_by is None and obj.progress < obj.max_progress * 0.5:
                # Try to capture an objective
                if in_range(self.robot.position, obj.position, obj.radius + 3):
                    return True
                self.target = obj.position
                return True
        return False

    def check_for_powerup(self) -> bool:
        """Find and move to nearest powerup."""
        powerups = [p for p in self.game_state.powerups if p.active]
        if not powerups:
            return False

        closest_powerup = min(powerups, key=lambda p: self.robot.position.distance_to(p.position))
        if self.robot.position.distance_to(closest_powerup.position) < 15:
            self.target = closest_powerup.position
            return True
        return False

    def check_for_enemies(self) -> bool:
        """Find and engage nearby enemies."""
        enemies = [r for r in self.game_state.teams.values() for r in r if r.team != self.robot.team and r.is_alive]
        if not enemies:
            return False

        closest_enemy = get_closest_robot(self.robot.position, enemies)
        if closest_enemy and self.robot.weapon and self.robot.weapon.can_fire():
            # Check if in weapon range
            if self.robot.position.distance_to(closest_enemy.position) <= self.robot.weapon.range:
                self.target = closest_enemy.position
                return True
            else:
                # Chase enemy
                self.target = closest_enemy.position
                return True
        return False

    def check_for_allies(self) -> bool:
        """Support allies in danger."""
        allies = [r for r in self.game_state.teams[self.robot.team] if r.is_alive and r != self.robot]
        if not allies:
            return False

        # Find allies with low health
        low_health_allies = [a for a in allies if a.health < a.max_health * 0.3]
        if low_health_allies:
            closest_low_health = min(low_health_allies, key=lambda a: self.robot.position.distance_to(a.position))
            if self.robot.role == RobotRole.SUPPORT and self.robot.weapon.type == WeaponType.SUPPORT:
                self.target = closest_low_health.position
                return True
        return False

    def move_to_objective(self) -> bool:
        """Move toward the nearest objective not owned by team."""
        for obj in self.game_state.objectives:
            if obj.captured_by != self.robot.team:
                # Only move if objective is not too close to enemy team
                if not any(r.team != self.robot.team and r.is_alive for r in get_robots_in_range(obj.position, self.game_state.teams.values(), 10)):
                    self.target = obj.position
                    return True
        return False

    def patrol(self) -> bool:
        """Default behavior: patrol a random area."""
        if self.target is None or self.robot.position.distance_to(self.target) < 2:
            # Choose a random patrol point
            self.target = Position(
                random.uniform(self.robot.position.x - 10, self.robot.position.x + 10),
                random.uniform(self.robot.position.y - 10, self.robot.position.y + 10)
            )
            # Clamp to map
            self.target.x = max(0, min(self.target.x, MAP_SIZE[0]))
            self.target.y = max(0, min(self.target.y, MAP_SIZE[1]))
        return True

    def get_next_action(self) -> str:
        """Execute behavior tree and return the next action."""
        for behavior in self.behavior_tree["priority"]:
            if behavior():
                if self.target:
                    # Move toward target
                    direction = (self.target - self.robot.position).normalize()
                    new_pos = Position(
                        self.robot.position.x + direction.x * self.robot.speed * GAME_TICK_RATE,
                        self.robot.position.y + direction.y * self.robot.speed * GAME_TICK_RATE
                    )
                    # Clamp position
                    new_pos.x = max(0, min(new_pos.x, MAP_SIZE[0]))
                    new_pos.y = max(0, min(new_pos.y, MAP_SIZE[1]))
                    self.robot.position = new_pos
                    self.robot.last_action = "moving"

                    # Check if we can attack
                    if self.robot.weapon and self.robot.weapon.can_fire():
                        # Find enemy in firing range
                        enemies = [r for r in self.game_state.teams.values() for r in r if r.team != self.robot.team and r.is_alive]
                        if enemies:
                            closest_enemy = get_closest_robot(self.robot.position, enemies)
                            if closest_enemy and self.robot.position.distance_to(closest_enemy.position) <= self.robot.weapon.range:
                                fire_result = self.robot.weapon.fire()
                                if fire_result["success"]:
                                    self.robot.last_action = f"attacking_{self.robot.weapon.type.value}"
                                    # Apply damage
                                    if closest_enemy:
                                        damage = fire_result["damage"]
                                        if fire_result.get("effect") == "stun":
                                            closest_enemy.cooldown = 2.0  # Stun for 2 seconds
                                        closest_enemy.health -= damage
                                        # Add feedback to robot's memory
                                        self.robot.strategy_memory.append({
                                            "action": "attack",
                                            "target": closest_enemy.id,
                                            "damage": damage,
                                            "success": True,
                                            "timestamp": time.time()
                                        })
                                        self.robot.role_history.append(self.robot.role)
                                        return "attack"

                return "move"
        return "idle"

    def learn_from_battle(self, battle_outcome: Dict):
        """Learn from past battles to improve future behavior."""
        if not battle_outcome.get("win", False):
            # If we lost, reduce aggression slightly
            self.robot.strategy_memory.append({
                "outcome": "loss",
                "timestamp": time.time()
            })
        else:
            self.robot.strategy_memory.append({
                "outcome": "win",
                "timestamp": time.time()
            })

        # Keep only last 100 entries
        if len(self.robot.strategy_memory) > MAX_HISTORY_DEPTH:
            self.robot.strategy_memory = self.robot.strategy_memory[-MAX_HISTORY_DEPTH:]

        # Adjust role preference based on success
        if len(self.robot.role_history) > 10:
            role_counts = defaultdict(int)
            for role in self.robot.role_history[-10:]:
                role_counts[role] += 1
            most_common_role = max(role_counts.keys(), key=lambda r: role_counts[r])
            if most_common_role != self.robot.role:
                self.robot.role = most_common_role

