class AudioVisualSystem:
    def __init__(self):
        self.effects_queue = []
        self.lighting_state = {"ambient": 0.6, "flicker": False, "team_colors": {}}
        self.sound_effects = {
            "fire": "weapon_fire.wav",
            "explosion": "explosion.wav",
            "powerup": "powerup_collect.wav",
            "hazard": "hazard_effect.wav",
            "capture": "objective_captured.wav",
            "death": "robot_death.wav"
        }

    def play_sound(self, effect: str, position: Optional[Position] = None):
        """Simulate sound effect playback."""
        if effect in self.sound_effects:
            self.effects_queue.append({
                "type": "sound",
                "effect": effect,
                "position": position,
                "timestamp": time.time()
            })

    def add_particle_effect(self, effect_type: str, position: Position, color: str = "white"):
        """Simulate particle effects."""
        self.effects_queue.append({
            "type": "particle",
            "effect": effect_type,
            "position": position,
            "color": color,
            "timestamp": time.time()
        })

    def update_lighting(self, team_colors: Dict[str, str]):
        """Update lighting based on active objectives and team positions."""
        self.lighting_state["team_colors"] = team_colors
        # Simulate flickering when battles occur
        if random.random() < 0.1:
            self.lighting_state["flicker"] = not self.lighting_state["flicker"]

        # Adjust ambient lighting based on number of active battles
        active_fights = 0
        for team in self.game_state.teams.values():
            for robot in team:
                if robot.is_alive and robot.last_action.startswith("attacking"):
                    active_fights += 1

        self.lighting_state["ambient"] = max(0.3, min(0.8, 0.6 + active_fights * 0.02))

