            "mine": Weapon(WeaponType.SPECIAL, "Smart Mine", 80, 5, 5.0, effect="explosion"),
            "sniper": Weapon(WeaponType.RANGED, "Sniper Rifle", 100, 50, 2.0),
            "shotgun": Weapon(WeaponType.RANGED, "Shotgun", 30, 8, 1.5)
        }

        # Initialize powerups
        self.powerup_effects = {
            PowerUpType.SPEED_BOOST: {"duration": 10, "value": 1.5},
            PowerUpType.DAMAGE_BOOST: {"duration": 15, "value": 1.3},
            PowerUpType.SHIELD: {"duration": 12, "value": 50},
            PowerUpType.REGEN: {"duration": 20, "value": 5},
            PowerUpType.SILENCE: {"duration": 8, "value": 0},  # disables enemy weapons
            PowerUpType.TELEPORT: {"duration": 0, "value": 0},  # instant teleport
            PowerUpType.CLONE: {"duration": 15, "value": 1}  # creates clone
        }

        # Initialize hazards
        self.hazard_effects = {
            HazardType.ELECTRIC_FLOOR: {"damage_per_second": 10, "effect": "stun"},
            HazardType.LAVA_POOL: {"damage_per_second": 15, "effect": "burn"},
            HazardType.TRAP_SPOT: {"damage_per_second": 5, "effect": "slow"},
            HazardType.GRAVITY_WELL: {"damage_per_second": 0, "effect": "pull"},
            HazardType.SLOW_FIELD: {"damage_per_second": 0, "effect": "slow"}
        }

    def initialize_map(self, team_count: int = 2, robots_per_team: int = 3, objective_type: ObjectiveType = ObjectiveType.FLAG_CAPTURE):
        """Initialize the game map with teams, robots, objectives, powerups, and hazards."""
        # Initialize teams
        team_names = [f"Team_{chr(65+i)}" for i in range(team_count)]
        self.game_state.teams = {team: [] for team in team_names}
        self.game_state.score = {team: 0 for team in team_names}

        # Define team spawn zones
        spawn_points = []
        if team_count == 2:
            spawn_points = [Position(10, 10), Position(MAP_SIZE[0] - 10, MAP_SIZE[1] - 10)]
        elif team_count == 3:
            spawn_points = [
                Position(10, 10), 
                Position(MAP_SIZE[0] - 10, 10), 
                Position(MAP_SIZE[0]//2, MAP_SIZE[1] - 10)
            ]
        elif team_count == 4:
            spawn_points = [
                Position(10, 10), 
                Position(MAP_SIZE[0] - 10, 10), 
                Position(10, MAP_SIZE[1] - 10),
                Position(MAP_SIZE[0] - 10, MAP_SIZE[1] - 10)
            ]

        # Spawn robots
        for i, team in enumerate(team_names):
            spawn_pos = spawn_points[i % len(spawn_points)]
            for j in range(robots_per_team):
                role = random.choice(list(RobotRole))
                if role == RobotRole.SUPPORT and i % 2 == 0:
                    role = RobotRole.ATTACKER  # Balance roles
                weapon = random.choice(list(self.weapons.values()))
                robot = Robot(
                    id=f"{team}_R{j}",
                    team=team,
                    role=role,
                    position=Position(
                        spawn_pos.x + random.uniform(-2, 2),
                        spawn_pos.y + random.uniform(-2, 2)
                    ),
                    weapon=weapon,
                    max_health=100,
                    health=100
                )
                self.game_state.teams[team].append(robot)
                self.ai_systems[robot.id] = RobotAI(robot, self.game_state)

        # Spawn objectives
        if objective_type == ObjectiveType.FLAG_CAPTURE:
            # Two flags, one for each team
            flags = [
                Objective(ObjectiveType.FLAG_CAPTURE, Position(20, 50), team_required=team_names[0], description="Capture the enemy flag"),
                Objective(ObjectiveType.FLAG_CAPTURE, Position(MAP_SIZE[0]-20, 50), team_required=team_names[1], description="Capture the enemy flag")
            ]
            self.game_state.objectives = flags
        elif objective_type == ObjectiveType.BASE_DEFENSE:
            base = Objective(ObjectiveType.BASE_DEFENSE, Position(MAP_SIZE[0]//2, MAP_SIZE[1]//2), team_required=team_names[0], max_progress=100, radius=15)
            self.game_state.objectives = [base]
        elif objective_type == ObjectiveType.ESCORT_PAYLOAD:
            payload = Objective(ObjectiveType.ESCORT_PAYLOAD, Position(MAP_SIZE[0]//2, 10), team_required=team_names[0], max_progress=100, description="Escort payload to the other side")
            target = Position(MAP_SIZE[0]//2, MAP_SIZE[1] - 10)
            # Create a path
            self.game_state.objectives = [payload]
        elif objective_type == ObjectiveType.DOMINATION:
            # Three control points
            points = [
                Objective(ObjectiveType.DOMINATION, Position(MAP_SIZE[0]//2, MAP_SIZE[1]//2), max_progress=100, radius=10),
                Objective(ObjectiveType.DOMINATION, Position(20, 20), max_progress=100, radius=8),
                Objective(ObjectiveType.DOMINATION, Position(MAP_SIZE[0]-20, MAP_SIZE[1]-20), max_progress=100, radius=8)
            ]
            self.game_state.objectives = points

        # Spawn power-ups
        for _ in range(5):
            powerup_type = random.choice(list(PowerUpType))
            effect = self.powerup_effects[powerup_type]
            self.game_state.powerups.append(
                PowerUp(
                    type=powerup_type,
                    position=generate_random_position(),
                    duration=effect["duration"],
                    value=effect["value"]
                )
            )

        # Spawn hazards
        num_hazards = int(MAP_SIZE[0] * MAP_SIZE[1] * Hazard_Density)
        for _ in range(num_hazards):
            hazard_type = random.choice(list(HazardType))
            effect = self.hazard_effects[hazard_type]
            pos = generate_random_position()
            self.game_state.hazards.append(
                Hazard(
                    type=hazard_type,
                    position=pos,
                    radius=3.0,
                    damage_per_second=effect["damage_per_second"],
                    effect=effect["effect"]
                )
            )

    def update(self, delta_time: float):
        """Main game update loop."""
        self.game_state.round_time += delta_time
        current_time = time.time()

        # Update adaptive difficulty
        self.adaptive_system.adjust_ai_hardness()

        # Update all robots
        for team, robots in self.game_state.teams.items():
            for robot in robots:
                if robot.is_alive:
                    robot.update(delta_time)

                    # Apply powerup effects
                    for powerup in self.game_state.powerups:
                        if powerup.active and robot.position.distance_to(powerup.position) < 2:
                            self.apply_powerup(robot, powerup)
                            powerup.active = False
                            self.av_system.play_sound("powerup", robot.position)
                            self.av_system.add_particle_effect("glow", robot.position, "yellow")

                    # Apply hazard effects
                    for hazard in self.game_state.hazards:
                        if hazard.active and hazard.position.distance_to(robot.position) < hazard.radius:
                            effect = hazard.apply_effect(robot)
                            if effect["applied"]:
                                robot.health -= effect["damage"]
                                if effect["effect"] == "stun":
                                    robot.cooldown = 1.5
                                elif effect["effect"] == "slow":
                                    robot.speed *= 0.6
                                self.av_system.play_sound("hazard", robot.position)
                                self.av_system.add_particle_effect("spark", hazard.position, "orange")

                    # AI decision making
                    if robot.team in self.game_state.teams:
                        ai = self.ai_systems.get(robot.id)
                        if ai:
                            action = ai.get_next_action()

                            # Check if robot has killed an enemy
                            if action == "attack":
                                # We already handled damage in AI system
                                pass

        # Update objectives
        for obj in self.game_state.objectives:
            robots_in_range = get_robots_in_range(obj.position, [r for team in self.game_state.teams.values() for r in team], obj.radius)
            obj.update(robots_in_range)

            # Objective completed
            if obj.captured_by and obj.progress >= obj.max_progress:
                self.game_state.last_mission_completed = obj.type.value
                self.game_state.score[obj.captured_by] += 100
                self.av_system.play_sound("capture", obj.position)
                self.av_system.add_particle_effect("explosion", obj.position, "blue")
                # Reset objective for next round
                if obj.type == ObjectiveType.FLAG_CAPTURE:
                    obj.captured_by = None
                    obj.progress = 0

        # Spawn new powerups randomly
        if random.random() < POWERUP_SPAWN_RATE:
            powerup_type = random.choice(list(PowerUpType))
            effect = self.powerup_effects[powerup_type]
            self.game_state.powerups.append(
                PowerUp(
                    type=powerup_type,
                    position=generate_random_position(),
                    duration=effect["duration"],
                    value=effect["value"]
                )
            )

        # Remove inactive powerups
