class AdaptiveDifficulty:
    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.performance_history = deque(maxlen=20)  # Last 20 rounds
        self.difficulty_level = 0.5  # Normal difficulty

    def evaluate_performance(self) -> float:
        """Evaluate team performance based on various metrics."""
        if not self.game_state.teams:
            return 0.5

        team_scores = {}
        for team_name, robots in self.game_state.teams.items():
            alive_count = sum(1 for r in robots if r.is_alive)
            objective_points = sum(1 for obj in self.game_state.objectives if obj.captured_by == team_name)
            kills = sum(1 for r in robots for other in self.game_state.teams.values() for r2 in other if r2.team != team_name and r2.is_alive and r.weapon and r.weapon.cooldown <= 0)
            team_scores[team_name] = alive_count * 10 + objective_points * 50 + kills * 15

        if not team_scores:
            return 0.5

        avg_score = sum(team_scores.values()) / len(team_scores)
        max_score = max(team_scores.values()) if team_scores else 0
        min_score = min(team_scores.values()) if team_scores else 0

        # If one team dominates, difficulty increases for them
        if max_score > 0 and min_score < 0.5 * max_score:
            # Unbalanced game
            return min(1.0, self.difficulty_level + 0.05)
        elif max_score == min_score and max_score > 100:
            # High performance across teams
            return min(1.0, self.difficulty_level + 0.02)
        elif max_score < 50:
            # Low performance, decrease difficulty
            return max(0.0, self.difficulty_level - 0.03)

        return self.difficulty_level

    def adjust_ai_hardness(self):
        """Adjust AI behavior based on performance."""
        current_performance = self.evaluate_performance()
        self.difficulty_level = current_performance

        # Adjust AI aggression and decision making based on difficulty
        for team in self.game_state.teams.values():
            for robot in team:
                if robot.role != RobotRole.SUPPORT:  # Support robots don't get more aggressive
                    # Adjust weapon effectiveness, movement speed, and decision speed
                    if self.difficulty_level > 0.7:
                        robot.speed += 0.1
                        if robot.weapon:
                            robot.weapon.damage *= 1.1
                            robot.weapon.fire_rate *= 0.95
                    elif self.difficulty_level < 0.3:
                        robot.speed -= 0.1
                        if robot.weapon:
                            robot.weapon.damage *= 0.9
                            robot.weapon.fire_rate *= 1.05
                    robot.speed = max(0.5, min(robot.speed, 3.0))  # Clamp speed

