        'damage_taken': 0
    })

    def __post_init__(self):
        if not self.weapons:
            # Default weapons
            self.weapons = [
                Weapon(WeaponType.RANGED_PISTOL, 15, 50, 8, 12, 24),
                Weapon(WeaponType.MELEE_SWORD, 30, 5, 0.5, 0, 0, is_melee=True)
            ]
        self.current_weapon_index = 0

    def get_current_weapon(self) -> Weapon:
        return self.weapons[self.current_weapon_index] if self.weapons else Weapon(WeaponType.RANGED_PISTOL, 10, 30, 5, 10, 20)

    def switch_weapon(self, index: int):
        if 0 <= index < len(self.weapons):
            self.current_weapon_index = index

    def add_powerup(self, powerup_type: PowerUpType):
        if len(self.inventory) < MAX_INVENTORY_SLOTS:
            self.inventory.append(powerup_type)

    def use_powerup(self, powerup_type: PowerUpType) -> bool:
        if powerup_type in self.inventory:
            self.inventory.remove(powerup_type)
            return True
        return False

    def take_damage(self, damage: float, damage_type: str = "bullet") -> float:
        # Armor absorbs some damage
        armor_absorption = self.armor * 0.7  # 70% armor effectiveness
        actual_damage = damage - min(armor_absorption, damage)
        self.armor = max(0, self.armor - damage * 0.3)  # Armor degrades
        self.health = max(0, self.health - actual_damage)
        self.stats['damage_taken'] += actual_damage

        if self.health <= 0:
            self.is_dead = True
            self.stats['deaths'] += 1

        return actual_damage

    def heal(self, amount: float):
        self.health = min(BASE_HEALTH, self.health + amount)

    def add_armor(self, amount: float):
        self.armor = min(BASE_ARMOR, self.armor + amount)

    def update_cooldowns(self, delta_time: float):
        to_remove = []
        for effect, end_time in self.cooldowns.items():
            if end_time <= time.time():
                to_remove.append(effect)
            else:
                self.cooldowns[effect] = end_time - delta_time

        for effect in to_remove:
            del self.cooldowns[effect]

    def has_cooldown(self, effect: str) -> bool:
        return effect in self.cooldowns and self.cooldowns[effect] > time.time()

    def apply_cooldown(self, effect: str, duration: float):
        self.cooldowns[effect] = time.time() + duration

    def get_behavior_priority(self) -> float:
        # Higher priority means more aggressive behavior (used in adaptive difficulty)
        if self.is_dead:
            return 0.0
        return (self.stats['kills'] * 2 + self.stats['assists'] + self.stats['objectives_completed']) / (self.stats['deaths'] + 1)

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team_required: Optional[int] = None  # None = neutral
    progress: float = 0.0  # 0.0 to 1.0
    completed: bool = False
    captured_by: Optional[int] = None  # team_id
    radius: float = 10.0
    description: str = ""

    def is_within_range(self, position: Vector2D) -> bool:
        return position.distance_to(self.position) <= self.radius

    def update_progress(self, team_id: int, increment: float, delta_time: float):
        if self.team_required is not None and self.team_required != team_id:
            return  # Only specific team can complete
        if self.completed:
            return
        self.progress = min(1.0, self.progress + increment * delta_time)
        if self.progress >= 1.0:
            self.completed = True
            self.captured_by = team_id

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    active: bool = True
    spawn_time: float = field(default_factory=time.time)
    duration: float = POWERUP_DURATION
    value: float = 20.0  # Amount of health, armor, etc.

    def is_expired(self) -> bool:
        return time.time() - self.spawn_time > self.duration

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float = 8.0
    damage_per_second: float = 5.0
    active: bool = True

@dataclass
class Map:
    size: Tuple[int, int] = MAP_SIZE
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    spawn_points: List[Vector2D] = field(default_factory=list)
    terrain_features: List[str] = field(default_factory=list)  # e.g., "mountain", "forest", "city"

    def add_objective(self, obj: Objective):
        self.objectives.append(obj)

    def add_power_up(self, power_up: PowerUp):
        self.power_ups.append(power_up)

    def add_hazard(self, hazard: Hazard):
        self.hazards.append(hazard)

@dataclass
class Team:
    id: int
    name: str
    robots: List[Robot] = field(default_factory=list)
    score: float = 0.0
    base_position: Vector2D = Vector2D(0, 0)
    flag_position: Optional[Vector2D] = None
    payload_position: Optional[Vector2D] = None
    control_points: List[Vector2D] = field(default_factory=list)
    strategy: Dict[str, Any] = field(default_factory=dict)  # AI strategy memory

    def __post_init__(self):
        self.strategy = {
            'last_known_enemy_positions': [],
            'objective_success_rate': 0.5,
            'team_cooperation_level': 0.7,
            'battle_history': [],
            'preferred_roles': {role: 0.25 for role in RobotRole}
        }

    def add_robot(self, robot: Robot):
        self.robots.append(robot)

    def get_alive_robots(self) -> List[Robot]:
        return [r for r in self.robots if not r.is_dead]

    def get_team_score(self) -> float:
        return self.score + sum(r.stats['kills'] * 10 + 
                               r.stats['assists'] * 5 + 
                               r.stats['objectives_completed'] * 20 
                               for r in self.robots)

@dataclass
class GameState:
    teams: List[Team] = field(default_factory=list)
    map: Map = field(default_factory=Map)
    current_time: float = 0.0
    game_state: str = "waiting"  # waiting, running, paused, ended
    round_duration: float = 300.0  # 5 minutes
    winner: Optional[int] = None
    last_update: float = 0.0
    particle_effects: List[Dict] = field(default_factory=list)  # For visual effects
    sound_events: List[Dict] = field(default_factory=list)  # For audio events
    difficulty_level: float = 0.5  # 0.0 to 1.0, higher = harder
    learning_memory: Dict[str, Any] = field(default_factory=dict)  # For adaptive learning

# ----------------------------
# UTILITY FUNCTIONS
# ----------------------------

def distance_between_points(p1: Vector2D, p2: Vector2D) -> float:
    return p1.distance_to(p2)

def angle_between_vectors(v1: Vector2D, v2: Vector2D) -> float:
    dot = v1.x * v2.x + v1.y * v2.y
    mag1 = v1.magnitude()
    mag2 = v2.magnitude()
    if mag1 == 0 or mag2 == 0:
        return 0.0
    cos_angle = dot / (mag1 * mag2)
    cos_angle = max(-1.0, min(1.0, cos_angle))  # Clamp for floating point errors
    return math.acos(cos_angle)

def get_random_position_in_map(map_size: Tuple[int, int]) -> Vector2D:
    return Vector2D(random.uniform(0, map_size[0]), random.uniform(0, map_size[1]))

def generate_spawn_points(num_teams: int, map_size: Tuple[int, int]) -> List[Vector2D]:
    # Distribute spawn points around the edges of the map
    spawn_points = []
    margin = 10
    corners = [
        Vector2D(margin, margin),
        Vector2D(map_size[0] - margin, margin),
        Vector2D(map_size[0] - margin, map_size[1] - margin),
        Vector2D(margin, map_size[1] - margin)
    ]

    for i in range(num_teams):
        idx = i % len(corners)
        # Add some randomness around the corner
        spawn_points.append(Vector2D(
            corners[idx].x + random.uniform(-3, 3),
            corners[idx].y + random.uniform(-3, 3)
        ))

    return spawn_points

def get_closest_objective(robot: Robot, objectives: List[Objective]) -> Optional[Objective]:
    if not objectives:
        return None
    closest = min(objectives, key=lambda obj: robot.position.distance_to(obj.position))
    if robot.position.distance_to(closest.position) < 50:  # Reasonable range
        return closest
    return None

def get_nearest_enemy(robot: Robot, teams: List[Team]) -> Optional[Robot]:
    enemies = []
    for team in teams:
        if team.id != robot.team:
            enemies.extend([r for r in team.robots if not r.is_dead])

    if not enemies:
        return None

    return min(enemies, key=lambda e: robot.position.distance_to(e.position))

def get_nearest_teammate(robot: Robot, team: Team) -> Optional[Robot]:
    teammates = [t for t in team.robots if t.id != robot.id and not t.is_dead]
    if not teammates:
        return None
    return min(teammates, key=lambda t: robot.position.distance_to(t.position))

def calculate_team_performance(team: Team) -> float:
    # Calculate a performance metric based on kills, objectives, and survival
    alive_count = len(team.get_alive_robots())
    total_robots = len(team.robots)
    if total_robots == 0:
        return 0.0

    avg_kills = sum(r.stats['kills'] for r in team.robots) / total_robots
    avg_objectives = sum(r.stats['objectives_completed'] for r in team.robots) / total_robots
    survival_rate = alive_count / total_robots

    return (avg_kills * 0.4 + avg_objectives * 0.4 + survival_rate * 0.2)

