class RobotBehaviorTree:
    def __init__(self, robot: Robot, game_state: GameState):
        self.robot = robot
        self.game_state = game_state
        self.current_task = None
        self.memory = {'last_seen_enemy': None, 'last_objective': None, 'last_position': robot.position}

    def update(self, delta_time: float) -> None:
        if self.robot.is_dead:
            return

        # Update memory
        self.memory['last_position'] = self.robot.position

        # Determine current objective for the robot
        self.current_task = self._select_task()

        # Execute the selected task
        if self.current_task:
            self._execute_task(self.current_task, delta_time)

    def _select_task(self) -> str:
        # Use priority-based selection for behavior
        team = next(t for t in self.game_state.teams if t.id == self.robot.team)

        # Get nearest objective
        nearest_objective = get_closest_objective(self.robot, self.game_state.map.objectives)

        # Check if there's a critical objective to complete
        if nearest_objective and not nearest_objective.completed:
            # Prioritize objectives based on team strategy and difficulty
            if nearest_objective.type in [ObjectiveType.CAPTURE_FLAG, ObjectiveType.ESCALTE_PAYLOAD]:
                if self.robot.role in [RobotRole.ATTACKER, RobotRole.SCOUT]:
                    return "capture_objective"

            # If defending, target objectives near base
            if self.robot.role == RobotRole.DEFENDER and nearest_objective.is_within_range(team.base_position):
                return "defend_objective"

        # Check for enemies
        nearest_enemy = get_nearest_enemy(self.robot, self.game_state.teams)
        if nearest_enemy:
            distance = self.robot.position.distance_to(nearest_enemy.position)

            # If enemy is close and we're not low on health, attack
            if distance < 30 and self.robot.health > 20:
                # Use melee if very close, ranged otherwise
                if distance < 8:
                    return "melee_attack"
                else:
                    return "ranged_attack"

            # If enemy is far, scout or flank
            if distance < 50:
                if self.robot.role == RobotRole.Scout:
                    return "flank_enemy"
            else:
                if self.robot.role == RobotRole.Scout:
                    return "patrol"

        # If no immediate threats or objectives, patrol or support
        if self.robot.role == RobotRole.SUPPORT:
            nearest_teammate = get_nearest_teammate(self.robot, team)
            if nearest_teammate and nearest_teammate.health < BASE_HEALTH * 0.5:
                return "heal_teammate"

        # Default behavior based on role
        if self.robot.role == RobotRole.ATTACKER:
            return "patrol"
        elif self.robot.role == RobotRole.DEFENDER:
            return "defend_base"
        elif self.robot.role == RobotRole.SUPPORT:
            return "patrol"
        elif self.robot.role == RobotRole.SCOUT:
            return "patrol"
        elif self.robot.role == RobotRole.HARASSER:
            return "harass"

        return "patrol"

    def _execute_task(self, task: str, delta_time: float) -> None:
        team = next(t for t in self.game_state.teams if t.id == self.robot.team)

        if task == "ranged_attack":
            self._execute_ranged_attack(delta_time)
        elif task == "melee_attack":
            self._execute_melee_attack(delta_time)
        elif task == "capture_objective":
            self._execute_capture_objective(delta_time)
        elif task == "defend_objective":
            self._execute_defend_objective(delta_time)
        elif task == "defend_base":
            self._execute_defend_base(delta_time)
        elif task == "heal_teammate":
            self._execute_heal_teammate(delta_time)
        elif task == "patrol":
            self._execute_patrol(delta_time)
        elif task == "flank_enemy":
            self._execute_flank_enemy(delta_time)
        elif task == "harass":
            self._execute_harass(delta_time)

    def _execute_ranged_attack(self, delta_time: float):
        nearest_enemy = get_nearest_enemy(self.robot, self.game_state.teams)
        if not nearest_enemy:
            return

        # Calculate direction to enemy
        direction = (nearest_enemy.position - self.robot.position).normalize()

        # Move toward enemy
        move_speed = self.robot.speed * delta_time
        new_pos = self.robot.position + direction * move_speed

        # Check for obstacles (simplified - assume no obstacles for now)
        self.robot.position = new_pos

        # Fire if in range
        weapon = self.robot.get_current_weapon()
        if weapon.type in [WeaponType.RANGED_PISTOL, WeaponType.RANGED_RIFLE, WeaponType.RANGED_SNIPER]:
            distance = self.robot.position.distance_to(nearest_enemy.position)
            if distance <= weapon.range and weapon.can_fire(self.game_state.current_time):
                if weapon.fire(self.game_state.current_time):
                    # Apply damage
                    damage = weapon.damage * (1.0 - nearest_enemy.armor / (BASE_ARMOR * 2))
                    nearest_enemy.take_damage(damage)
                    self.robot.stats['damage_dealt'] += damage
                    self.robot.stats['kills'] += 1 if nearest_enemy.is_dead else 0

                    # Add visual effect
                    self.game_state.particle_effects.append({
                        'type': 'bullet_impact',
                        'position': nearest_enemy.position,
                        'color': (255, 100, 100),
                        'duration': 0.5
                    })
                    self.game_state.sound_events.append({
                        'type': 'gunshot',
                        'position': self.robot.position,
                        'volume': 0.7
                    })

    def _execute_melee_attack(self, delta_time: float):
        nearest_enemy = get_nearest_enemy(self.robot, self.game_state.teams)
        if not nearest_enemy:
            return

        # Move toward enemy
        direction = (nearest_enemy.position - self.robot.position).normalize()
        move_speed = self.robot.speed * delta_time
        new_pos = self.robot.position + direction * move_speed

        self.robot.position = new_pos

        # Attack if close enough
        if self.robot.position.distance_to(nearest_enemy.position) < 5:
            weapon = self.robot.get_current_weapon()
            if weapon.is_melee and not self.robot.has_cooldown('melee_cooldown'):
                # Apply damage
                damage = weapon.damage
                nearest_enemy.take_damage(damage)
                self.robot.stats['damage_dealt'] += damage
                self.robot.stats['kills'] += 1 if nearest_enemy.is_dead else 0

                # Apply cooldown
                self.robot.apply_cooldown('melee_cooldown', 1.0)

                # Add visual effect
                self.game_state.particle_effects.append({
                    'type': 'melee_impact',
                    'position': nearest_enemy.position,
                    'color': (255, 200, 50),
                    'duration': 0.3
                })
                self.game_state.sound_events.append({
                    'type': 'melee_hit',
                    'position': self.robot.position,
                    'volume': 0.6
                })

    def _execute_capture_objective(self, delta_time: float):
        nearest_objective = get_closest_objective(self.robot, self.game_state.map.objectives)
        if not nearest_objective:
            return

        # Move toward objective
        direction = (nearest_objective.position - self.robot.position).normalize()
        move_speed = self.robot.speed * delta_time
        self.robot.position = self.robot.position + direction * move_speed

        # If within range, start capturing
        if nearest_objective.is_within_range(self.robot.position):
            nearest_objective.update_progress(self.robot.team, 0.5, delta_time)

            if nearest_objective.progress >= 0.5:
                # Add visual feedback
                self.game_state.particle_effects.append({
                    'type': 'capture_progress',
                    'position': nearest_objective.position,
                    'color': (50, 150, 255),
                    'duration': 0.2
                })

    def _execute_defend_objective(self, delta_time: float):
        nearest_objective = get_closest_objective(self.robot, self.game_state.map.objectives)
        if not nearest_objective:
            return

        # Position near objective
        if not nearest_objective.is_within_range(self.robot.position):
            direction = (nearest_objective.position - self.robot.position).normalize()
            move_speed = self.robot.speed * delta_time
            self.robot.position = self.robot.position + direction * move_speed

        # Look for enemies approaching
        nearest_enemy = get_nearest_enemy(self.robot, self.game_state.teams)
        if nearest_enemy and nearest_enemy.position.distance_to(nearest_objective.position) < 30:
            # Engage if enemy is near objective
            self._execute_ranged_attack(delta_time)

    def _execute_defend_base(self, delta_time: float):
        team = next(t for t in self.game_state.teams if t.id == self.robot.team)
        base_pos = team.base_position

        # Move toward base if too far
        if self.robot.position.distance_to(base_pos) > 15:
            direction = (base_pos - self.robot.position).normalize()
            move_speed = self.robot.speed * delta_time
            self.robot.position = self.robot.position + direction * move_speed

        # Look for enemies near base
        nearest_enemy = get_nearest_enemy(self.robot, self.game_state.teams)
        if nearest_enemy and nearest_enemy.position.distance_to(base_pos) < 25:
            self._execute_ranged_attack(delta_time)

    def _execute_heal_teammate(self, delta_time: float):
        team = next(t for t in self.game_state.teams if t.id == self.robot.team)
        nearest_teammate = get_nearest_teammate(self.robot, team)

        if not nearest_teammate or nearest_teammate.health >= BASE_HEALTH:
            return

        # Move toward teammate
        direction = (nearest_teammate.position - self.robot.position).normalize()
        move_speed = self.robot.speed * delta_time
        self.robot.position = self.robot.position + direction * move_speed

        # If close enough, try to use health pack
        if self.robot.position.distance_to(nearest_teammate.position) < 8:
            # Use powerup if available
            if PowerUpType.HEALTH_PACK in self.robot.inventory:
                if self.robot.use_powerup(PowerUpType.HEALTH_PACK):
                    nearest_teammate.heal(20)
                    self.game_state.particle_effects.append({
                        'type': 'heal_effect',
                        'position': nearest_teammate.position,
                        'color': (50, 255, 50),
                        'duration': 0.3
                    })
                    self.game_state.sound_events.append({
                        'type': 'health_pickup',
                        'position': self.robot.position,
                        'volume': 0.4
                    })

    def _execute_patrol(self, delta_time: float):
        # Patrol in a pattern - use memory to move to a patrol point
        if not hasattr(self, '_patrol_points'):
            # Generate random patrol points for this robot
            self._patrol_points = [
                get_random_position_in_map(self.game_state.map.size) for _ in range(3)
            ]
            self._current_patrol_index = 0

        target = self._patrol_points[self._current_patrol_index]
        direction = (target - self.robot.position).normalize()
        move_speed = self.robot.speed * delta_time
        self.robot.position = self.robot.position + direction * move_speed

        # If near target, move to next
        if self.robot.position.distance_to(target) < 2:
            self._current_patrol_index = (self._current_patrol_index + 1) % len(self._patrol_points)

    def _execute_flank_enemy(self, delta_time: float):
        nearest_enemy = get_nearest_enemy(self.robot, self.game_state.teams)
        if not nearest_enemy:
            return

        # Move to a flanking position - perpendicular to enemy direction
        enemy_direction = (nearest_enemy.position - self.robot.position).normalize()

        # Perpendicular direction
        perpendicular = Vector2D(-enemy_direction.y, enemy_direction.x)

        # Flanking target
        flank_target = nearest_enemy.position + perpendicular * 15

        # Move to flank target
        direction = (flank_target - self.robot.position).normalize()
        move_speed = self.robot.speed * delta_time
        self.robot.position = self.robot.position + direction * move_speed

    def _execute_harass(self, delta_time: float):
        team = next(t for t in self.game_state.teams if t.id == self.robot.team)

        # Find weak enemy (low health)
        weakest_enemy = None
        for other_team in self.game_state.teams:
            if other_team.id != team.id:
                for enemy in other_team.robots:
                    if not enemy.is_dead and (weakest_enemy is None or enemy.health < weakest_enemy.health):
                        weakest_enemy = enemy

        if weakest_enemy:
            # Move to harass enemy
            direction = (weakest_enemy.position - self.robot.position).normalize()
            move_speed = self.robot.speed * delta_time
            self.robot.position = self.robot.position + direction * move_speed

            # Try to attack from distance
            if self.robot.position.distance_to(weakest_enemy.position) < 40:
                self._execute_ranged_attack(delta_time)

# ----------------------------
# ADAPTIVE DIFFICULTY SYSTEM
# ----------------------------

class AdaptiveDifficulty:
    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.performance_history = deque(maxlen=20)  # Track last 20 rounds
        self.base_difficulty = 0.5
        self.difficulty_modifier = 0.0

    def calculate_difficulty(self) -> float:
        if len(self.performance_history) == 0:
            return self.base_difficulty

        # Calculate average team performance
        avg_performance = sum(self.performance_history) / len(self.performance_history)

        # If teams are performing too well, increase difficulty
        # If teams are performing poorly, decrease difficulty
        # We want to keep performance around 0.5 (medium)
        if avg_performance > 0.6:
            self.difficulty_modifier += 0.05
        elif avg_performance < 0.4:
            self.difficulty_modifier -= 0.05

        # Clamp difficulty between 0.1 and 0.9
        self.difficulty_modifier = max(-0.4, min(0.4, self.difficulty_modifier))

        return max(0.1, min(0.9, self.base_difficulty + self.difficulty_modifier))

    def adjust_ai_behavior(self):
        # Adjust AI behavior based on difficulty
        difficulty = self.calculate_difficulty()
        for team in self.game_state.teams:
            for robot in team.robots:
                if robot.is_dead:
                    continue

                # Higher difficulty: more aggressive, better aim, faster reactions
                if difficulty > 0.7:
                    robot.speed += 0.5
                    robot.get_current_weapon().fire_rate *= 1.1
                    robot.get_current_weapon().damage *= 1.1
                    robot.health += 10
                    robot.armor += 10
                elif difficulty < 0.3:
                    robot.speed *= 0.9
                    robot.get_current_weapon().fire_rate *= 0.8
                    robot.get_current_weapon().damage *= 0.8
                    robot.health *= 0.9
                    robot.armor *= 0.9

                # Adjust AI decision making
                # Higher difficulty: more likely to use advanced tactics
                if difficulty > 0.7:
                    # More likely to use flanking, coordinated attacks
                    robot.strategy['aggression_level'] = 0.8
                elif difficulty < 0.3:
