@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def to_tuple(self):
        return (self.x, self.y)

    def __repr__(self):
        return f"Vector2D({self.x:.2f}, {self.y:.2f})"

@dataclass
class Weapon:
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # shots per second
    ammo: int
    max_ammo: int
    reload_time: float = 2.0
    is_melee: bool = False

    def __post_init__(self):
        self.current_ammo = self.ammo
        self.last_fired = 0.0

    def can_fire(self, current_time: float) -> bool:
        return current_time - self.last_fired >= 1.0 / self.fire_rate and self.current_ammo > 0

    def fire(self, current_time: float) -> bool:
        if self.can_fire(current_time):
            self.current_ammo -= 1
            self.last_fired = current_time
            return True
        return False

    def reload(self) -> bool:
        if self.current_ammo < self.max_ammo:
            self.current_ammo = min(self.max_ammo, self.current_ammo + 3)
            return True
        return False

@dataclass
class Robot:
    id: str
