            self.inventory.append(powerup_type)

    def use_powerup(self, powerup_type: PowerUpType) -> bool:
        if powerup_type in self.inventory:
            self.inventory.remove(powerup_type)
            return True
        return False

    def take_damage(self, damage: float, damage_type: str = "bullet") -> float:
        # Armor absorbs some damage
        armor_absorption = self.armor * 0.7  # 70% armor effectiveness
        actual_damage = damage - min(armor_absorption, damage)
        self.armor = max(0, self.armor - damage * 0.3)  # Armor degrades
        self.health = max(0, self.health - actual_damage)
        self.stats['damage_taken'] += actual_damage

        if self.health <= 0:
            self.is_dead = True
            self.stats['deaths'] += 1

        return actual_damage

    def heal(self, amount: float):
        self.health = min(BASE_HEALTH, self.health + amount)

    def add_armor(self, amount: float):
        self.armor = min(BASE_ARMOR, self.armor + amount)

    def update_cooldowns(self, delta_time: float):
        to_remove = []
        for effect, end_time in self.cooldowns.items():
            if end_time <= time.time():
                to_remove.append(effect)
            else:
                self.cooldowns[effect] = end_time - delta_time

        for effect in to_remove:
            del self.cooldowns[effect]

    def has_cooldown(self, effect: str) -> bool:
        return effect in self.cooldowns and self.cooldowns[effect] > time.time()

    def apply_cooldown(self, effect: str, duration: float):
        self.cooldowns[effect] = time.time() + duration

    def get_behavior_priority(self) -> float:
        # Higher priority means more aggressive behavior (used in adaptive difficulty)
        if self.is_dead:
