def distance_between_points(p1: Vector2D, p2: Vector2D) -> float:
    return p1.distance_to(p2)

def angle_between_vectors(v1: Vector2D, v2: Vector2D) -> float:
    dot = v1.x * v2.x + v1.y * v2.y
    mag1 = v1.magnitude()
    mag2 = v2.magnitude()
    if mag1 == 0 or mag2 == 0:
        return 0.0
    cos_angle = dot / (mag1 * mag2)
    cos_angle = max(-1.0, min(1.0, cos_angle))  # Clamp for floating point errors
    return math.acos(cos_angle)

def get_random_position_in_map(map_size: Tuple[int, int]) -> Vector2D:
    return Vector2D(random.uniform(0, map_size[0]), random.uniform(0, map_size[1]))

def generate_spawn_points(num_teams: int, map_size: Tuple[int, int]) -> List[Vector2D]:
    # Distribute spawn points around the edges of the map
    spawn_points = []
    margin = 10
    corners = [
        Vector2D(margin, margin),
        Vector2D(map_size[0] - margin, margin),
        Vector2D(map_size[0] - margin, map_size[1] - margin),
        Vector2D(margin, map_size[1] - margin)
    ]

    for i in range(num_teams):
        idx = i % len(corners)
        # Add some randomness around the corner
        spawn_points.append(Vector2D(
            corners[idx].x + random.uniform(-3, 3),
            corners[idx].y + random.uniform(-3, 3)
        ))

    return spawn_points

def get_closest_objective(robot: Robot, objectives: List[Objective]) -> Optional[Objective]:
    if not objectives:
        return None
    closest = min(objectives, key=lambda obj: robot.position.distance_to(obj.position))
    if robot.position.distance_to(closest.position) < 50:  # Reasonable range
        return closest
    return None

def get_nearest_enemy(robot: Robot, teams: List[Team]) -> Optional[Robot]:
    enemies = []
    for team in teams:
        if team.id != robot.team:
            enemies.extend([r for r in team.robots if not r.is_dead])

    if not enemies:
        return None

    return min(enemies, key=lambda e: robot.position.distance_to(e.position))

def get_nearest_teammate(robot: Robot, team: Team) -> Optional[Robot]:
    teammates = [t for t in team.robots if t.id != robot.id and not t.is_dead]
    if not teammates:
        return None
    return min(teammates, key=lambda t: robot.position.distance_to(t.position))

def calculate_team_performance(team: Team) -> float:
    # Calculate a performance metric based on kills, objectives, and survival
    alive_count = len(team.get_alive_robots())
    total_robots = len(team.robots)
    if total_robots == 0:
        return 0.0

    avg_kills = sum(r.stats['kills'] for r in team.robots) / total_robots
    avg_objectives = sum(r.stats['objectives_completed'] for r in team.robots) / total_robots
    survival_rate = alive_count / total_robots

    return (avg_kills * 0.4 + avg_objectives * 0.4 + survival_rate * 0.2)

