class AdaptiveDifficulty:
    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.performance_history = deque(maxlen=20)  # Track last 20 rounds
        self.base_difficulty = 0.5
        self.difficulty_modifier = 0.0

    def calculate_difficulty(self) -> float:
        if len(self.performance_history) == 0:
            return self.base_difficulty

        # Calculate average team performance
        avg_performance = sum(self.performance_history) / len(self.performance_history)

        # If teams are performing too well, increase difficulty
        # If teams are performing poorly, decrease difficulty
        # We want to keep performance around 0.5 (medium)
        if avg_performance > 0.6:
            self.difficulty_modifier += 0.05
        elif avg_performance < 0.4:
            self.difficulty_modifier -= 0.05

        # Clamp difficulty between 0.1 and 0.9
        self.difficulty_modifier = max(-0.4, min(0.4, self.difficulty_modifier))

        return max(0.1, min(0.9, self.base_difficulty + self.difficulty_modifier))

    def adjust_ai_behavior(self):
        # Adjust AI behavior based on difficulty
        difficulty = self.calculate_difficulty()
        for team in self.game_state.teams:
            for robot in team.robots:
                if robot.is_dead:
                    continue

                # Higher difficulty: more aggressive, better aim, faster reactions
                if difficulty > 0.7:
                    robot.speed += 0.5
                    robot.get_current_weapon().fire_rate *= 1.1
                    robot.get_current_weapon().damage *= 1.1
                    robot.health += 10
                    robot.armor += 10
                elif difficulty < 0.3:
                    robot.speed *= 0.9
                    robot.get_current_weapon().fire_rate *= 0.8
                    robot.get_current_weapon().damage *= 0.8
                    robot.health *= 0.9
                    robot.armor *= 0.9

                # Adjust AI decision making
                # Higher difficulty: more likely to use advanced tactics
                if difficulty > 0.7:
                    # More likely to use flanking, coordinated attacks
                    robot.strategy['aggression_level'] = 0.8
                elif difficulty < 0.3:
                    robot.strategy['aggression_level'] = 0.3

    def update_learning_memory(self):
        # Record game state for learning
        team_performances = []
        for team in self.game_state.teams:
            perf = calculate_team_performance(team)
            team_performances.append(perf)

        self.performance_history.append(sum(team_performances) / len(team_performances) if team_performances else 0.5)

        # Update strategy based on performance
        for team in self.game_state.teams:
            # Update team strategy memory
            team.strategy['battle_history'].append({
                'time': self.game_state.current_time,
                'score': team.get_team_score(),
                'alive_robots': len(team.get_alive_robots()),
                'objective_completion': sum(1 for obj in self.game_state.map.objectives if obj.captured_by == team.id)
            })

            # Calculate success rate
            if len(team.strategy['battle_history']) > 5:
                recent = team.strategy['battle_history'][-5:]
                success_rate = sum(1 for b in recent if b['alive_robots'] > 0) / len(recent)
                team.strategy['objective_success_rate'] = success_rate

