    def update(self, delta_time: float):
        # Update cooldowns
        if self.cooldown > 0:
            self.cooldown -= delta_time
            self.cooldown = max(0, self.cooldown)

        # Update power-up durations
        to_remove = []
        for power_type, duration in self.power_ups.items():
            self.power_ups[power_type] = duration - delta_time
            if self.power_ups[power_type] <= 0:
                to_remove.append(power_type)

        for power_type in to_remove:
            del self.power_ups[power_type]
            logger.info(f"Power-up {power_type.value} expired for robot {self.id}")

    def take_damage(self, damage: float):
        # Apply damage with possible shield mitigation
        shield_bonus = 0
        if PowerUpType.SHIELD in self.power_ups:
            shield_bonus = 50  # Reduce damage by 50% while shield is active

        actual_damage = max(0, damage - shield_bonus)
        self.health = max(0, self.health - actual_damage)

        if self.health <= 0:
            self.is_active = False
            logger.info(f"Robot {self.id} has been eliminated!")

