class AIBehavior:
    """Base class for AI behavior patterns"""

    def __init__(self, robot: Robot, game_state: GameState):
        self.robot = robot
        self.game_state = game_state
        self.target_position = None
        self.last_behavior_time = 0.0
        self.behavior_state = "idle"

    def update(self, delta_time: float) -> Optional[Vector2D]:
        """Return the desired movement target or None for default behavior"""
        raise NotImplementedError


class AttackBehavior(AIBehavior):
    """Aggressive behavior: seek and destroy enemies"""

    def update(self, delta_time: float) -> Optional[Vector2D]:
        self.last_behavior_time += delta_time

        # Find closest enemy
        closest_enemy = None
        min_distance = float('inf')

        for robot in self.game_state.get_alive_robots():
            if robot.team != self.robot.team and robot.is_active:
                distance = self.robot.position.distance_to(robot.position)
                if distance < min_distance:
                    min_distance = distance
                    closest_enemy = robot

        if closest_enemy and min_distance < 120:  # Attack range
            self.behavior_state = "attacking"
            return closest_enemy.position
        else:
            self.behavior_state = "patrolling"
            # Patrol to a random location
            if self.last_behavior_time > 3.0:
                self.target_position = Vector2D(
                    random.uniform(0, 100),
                    random.uniform(0, 100)
                )
                self.last_behavior_time = 0
            return self.target_position


class SupportBehavior(AIBehavior):
    """Support behavior: heal teammates and provide buffs"""

    def update(self, delta_time: float) -> Optional[Vector2D]:
        self.last_behavior_time += delta_time

        # If we have healing weapon, look for injured teammates
        if self.robot.weapon == WeaponType.HEALING_GUN:
            # Find lowest health teammate
            lowest_health_teammate = None
            min_health = float('inf')

            for robot in self.game_state.get_team_robots(self.robot.team):
                if robot != self.robot and robot.is_active and robot.health < min_health:
                    min_health = robot.health
                    lowest_health_teammate = robot

            if lowest_health_teammate and min_health < 70:
                self.behavior_state = "healing"
                return lowest_health_teammate.position

        # If no healing needed, defend objectives
        for objective in self.game_state.objectives:
            if objective.team == self.robot.team and objective.captured_by == self.robot.team:
                distance = self.robot.position.distance_to(objective.position)
                if distance > 40:  # Too far from objective
                    self.behavior_state = "defending"
                    return objective.position

        # Default: patrol
        if self.last_behavior_time > 5.0:
            self.target_position = Vector2D(
                random.uniform(0, 100),
                random.uniform(0, 100)
            )
            self.last_behavior_time = 0
        return self.target_position


class ReconBehavior(AIBehavior):
    """Recon behavior: scout, gather intelligence, and report"""

    def update(self, delta_time: float) -> Optional[Vector2D]:
        self.last_behavior_time += delta_time

        # Gather intelligence about enemy positions
        enemy_positions = []
        for robot in self.game_state.get_alive_robots():
