class TankBehavior(AIBehavior):
    """Tank behavior: hold positions and absorb damage"""

    def update(self, delta_time: float) -> Optional[Vector2D]:
        self.last_behavior_time += delta_time

        # Find closest objective to defend
        target_objective = None
        min_distance = float('inf')

        for objective in self.game_state.objectives:
            if objective.team == self.robot.team:
                distance = self.robot.position.distance_to(objective.position)
                if distance < min_distance:
                    min_distance = distance
                    target_objective = objective

        if target_objective:
            self.behavior_state = "defending"
            return target_objective.position

        # If no objectives, defend team spawn point
        spawn_point = Vector2D(20, 20) if self.robot.team == Team.RED else Vector2D(80, 80)
        if self.last_behavior_time > 6.0:
            self.target_position = spawn_point
            self.last_behavior_time = 0

        return self.target_position


class AIController:
    """Main AI controller that selects appropriate behavior based on robot type and situation"""

    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.behaviors = {}

    def update(self, delta_time: float):
        """Update all AI robots"""
        for robot_id, robot in self.game_state.robots.items():
            if robot.team == Team.NEUTRAL:
                continue  # Skip neutral robots (player-controlled)

            # Create behavior if not exists
            if robot_id not in self.behaviors:
                if robot.robot_type == RobotType.ASSAULT:
                    self.behaviors[robot_id] = AttackBehavior(robot, self.game_state)
                elif robot.robot_type == RobotType.SUPPORT:
                    self.behaviors[robot_id] = SupportBehavior(robot, self.game_state)
                elif robot.robot_type == RobotType.RECON:
                    self.behaviors[robot_id] = ReconBehavior(robot, self.game_state)
                elif robot.robot_type == RobotType.TANK:
                    self.behaviors[robot_id] = TankBehavior(robot, self.game_state)

            # Update behavior
            behavior = self.behaviors[robot_id]
            target = behavior.update(delta_time)

            # Move robot toward target if available
            if target:
                robot.move_toward(target, delta_time)

            # Decide on weapon usage
            if robot.can_perform_action():
                # Use weapon if enemy is close enough
                for enemy in self.game_state.get_alive_robots():
                    if enemy.team != robot.team:
                        distance = robot.position.distance_to(enemy.position)
                        weapon_range = {
                            WeaponType.LASER_RIFLE: 100,
                            WeaponType.PLASMA_CANNON: 150,
                            WeaponType.SHOTGUN: 40,
                            WeaponType.CHAIN_SAW: 15,
                            WeaponType.MISSILE_LAUNCHER: 200,
                            WeaponType.HEALING_GUN: 80
                        }.get(robot.weapon, 100)

                        if distance <= weapon_range:
                            robot.use_weapon(enemy.position, self.game_state.robots)
