@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / mag, self.y / mag)

    def distance_to(self, other):
        return (self - other).magnitude()

    def to_tuple(self):
        return (self.x, self.y)

@dataclass
class Robot:
    id: str
    team: Team
    robot_type: RobotType
    position: Vector2D
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 1.0
    weapon: WeaponType = WeaponType.LASER_RIFLE
    ammo: int = 100
    max_ammo: int = 100
    cooldown: float = 0.0
    role: str = "default"
    is_active: bool = True
    last_action_time: float = 0.0
    knowledge_base: Dict[str, Any] = field(default_factory=dict)  # Learning data
    target: Optional[str] = None  # Target robot ID
    objective: Optional[ObjectiveType] = None
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)  # power_up_type -> duration

    def __post_init__(self):
        # Initialize power-ups
        self.power_ups = {}
        # Initialize knowledge base with learning parameters
        self.knowledge_base = {
            'wins': 0,
            'losses': 0,
            'teamwork_score': 0.5,
            'strategy_history': deque(maxlen=50),
            'adaptation_rate': 0.1,
            'recent_actions': deque(maxlen=20)
        }

    def update(self, delta_time: float):
        # Update cooldowns
        if self.cooldown > 0:
            self.cooldown -= delta_time
            self.cooldown = max(0, self.cooldown)

        # Update power-up durations
        to_remove = []
        for power_type, duration in self.power_ups.items():
            self.power_ups[power_type] = duration - delta_time
            if self.power_ups[power_type] <= 0:
                to_remove.append(power_type)

        for power_type in to_remove:
            del self.power_ups[power_type]
            logger.info(f"Power-up {power_type.value} expired for robot {self.id}")

    def take_damage(self, damage: float):
        # Apply damage with possible shield mitigation
        shield_bonus = 0
        if PowerUpType.SHIELD in self.power_ups:
            shield_bonus = 50  # Reduce damage by 50% while shield is active

        actual_damage = max(0, damage - shield_bonus)
        self.health = max(0, self.health - actual_damage)

        if self.health <= 0:
            self.is_active = False
            logger.info(f"Robot {self.id} has been eliminated!")

    def heal(self, amount: float):
        self.health = min(self.max_health, self.health + amount)

    def use_weapon(self, target_position: Vector2D, robots: Dict[str, 'Robot']) -> Dict[str, Any]:
        """Return damage dealt and any effects"""
        weapon_stats = {
            WeaponType.LASER_RIFLE: {'damage': 10, 'range': 100, 'cooldown': 0.5, 'type': 'ranged'},
            WeaponType.PLASMA_CANNON: {'damage': 25, 'range': 150, 'cooldown': 2.0, 'type': 'ranged'},
            WeaponType.SHOTGUN: {'damage': 15, 'range': 40, 'cooldown': 1.0, 'type': 'ranged', 'splash': 20},
            WeaponType.CHAIN_SAW: {'damage': 5, 'range': 15, 'cooldown': 0.2, 'type': 'melee'},
            WeaponType.MISSILE_LAUNCHER: {'damage': 40, 'range': 200, 'cooldown': 5.0, 'type': 'ranged', 'splash': 30},
            WeaponType.HEALING_GUN: {'damage': -15, 'range': 80, 'cooldown': 1.5, 'type': 'heal'}
        }

        if self.weapon not in weapon_stats:
            return {'damage': 0, 'effects': []}

        stats = weapon_stats[self.weapon]
        target_robot = None

        # Find target robot within range
        if self.target:
            if self.target in robots and robots[self.target].is_active:
                target_robot = robots[self.target]

        # If no target specified, find closest enemy
        if not target_robot:
            for robot in robots.values():
                if robot.team != self.team and robot.is_active:
                    dist = self.position.distance_to(robot.position)
                    if dist <= stats['range']:
                        target_robot = robot
                        self.target = robot.id
                        break

        if not target_robot:
            return {'damage': 0, 'effects': []}

        distance = self.position.distance_to(target_robot.position)

        # Check if in range
        if distance > stats['range']:
            return {'damage': 0, 'effects': []}

        # Check cooldown
        if self.cooldown > 0:
            return {'damage': 0, 'effects': []}

        # Apply damage or healing
        damage = stats['damage']
        effects = []

        if stats['type'] == 'heal':
            # Healing gun - heal target
            if target_robot.team == self.team:
                target_robot.heal(abs(damage))
                effects.append('heal')
                logger.info(f"Robot {self.id} healed {target_robot.id} for {abs(damage)} HP")
            else:
                # Can't heal enemies
                return {'damage': 0, 'effects': []}
        else:
            # Damage weapon
            if 'splash' in stats and distance < stats['range'] * 0.3:
                # Splash damage
                for robot in robots.values():
                    if robot.team != self.team and robot.is_active:
                        splash_dist = self.position.distance_to(robot.position)
                        if splash_dist <= stats['splash']:
                            robot.take_damage(damage * 0.5)
                            logger.info(f"Robot {self.id} dealt splash damage to {robot.id}")

            target_robot.take_damage(damage)
            logger.info(f"Robot {self.id} attacked {target_robot.id} for {damage} damage")

        # Apply cooldown
        self.cooldown = stats['cooldown']

        # Reduce ammo
        if self.weapon != WeaponType.HEALING_GUN:
            self.ammo = max(0, self.ammo - 1)

        # Record action for learning
        self.knowledge_base['recent_actions'].append({
            'action': 'attack',
            'target': target_robot.id,
            'weapon': self.weapon.value,
            'timestamp': time.time()
        })

        return {'damage': damage, 'effects': effects}

    def move_toward(self, target: Vector2D, delta_time: float):
        """Move robot toward target position"""
        if not self.is_active:
            return

        direction = (target - self.position).normalize()
        distance = self.position.distance_to(target)

        # Apply speed modifiers from power-ups
        speed_multiplier = 1.0
        if PowerUpType.SPEED_BOOST in self.power_ups:
            speed_multiplier = 1.8

        move_distance = self.speed * speed_multiplier * delta_time
        if distance < move_distance:
            # Reached target
            self.position = target
        else:
            self.position = self.position + direction * move_distance

    def add_power_up(self, power_type: PowerUpType, duration: float):
        """Add a power-up effect"""
        self.power_ups[power_type] = duration
        logger.info(f"Robot {self.id} gained {power_type.value} for {duration} seconds")

    def can_perform_action(self) -> bool:
        """Check if robot is ready to perform an action"""
        return self.is_active and self.cooldown <= 0 and self.health > 0


@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team: Team
    progress: float = 0.0
    max_progress: float = 100.0
    captured_by: Optional[Team] = None
    defenders: Set[str] = field(default_factory=set)
    is_active: bool = True

    def update(self, robots: Dict[str, Robot], delta_time: float):
        """Update objective state based on nearby robots"""
        if not self.is_active:
            return

        nearby_robots = []
        for robot in robots.values():
            if robot.is_active and robot.team != Team.NEUTRAL:
                distance = robot.position.distance_to(self.position)
                if distance < 30:  # Capture radius
                    nearby_robots.append(robot)

        # Logic for different objective types
        if self.type == ObjectiveType.CAPTURE_FLAG:
            # Only one team can capture at a time
            team_counts = defaultdict(int)
            for robot in nearby_robots:
                team_counts[robot.team] += 1

            # Determine leading team
            if team_counts:
                leading_team = max(team_counts.keys(), key=lambda t: team_counts[t])
                if team_counts[leading_team] >= 2:  # Need at least 2 robots to capture
                    self.progress += team_counts[leading_team] * 0.5 * delta_time
                    self.captured_by = leading_team

                    # Reset if other team gains control
                    if self.captured_by != self.team:
                        self.team = self.captured_by
                        logger.info(f"Objective captured by {self.captured_by.value} team!")

                # Decay progress if no robots nearby
                if team_counts[self.team] == 0:
                    self.progress = max(0, self.progress - 0.1 * delta_time)

        elif self.type == ObjectiveType.DEFEND_BASE:
            # Defenders add to progress
            self.defenders = {robot.id for robot in nearby_robots if robot.team == self.team}
            if len(self.defenders) > 0:
                self.progress += len(self.defenders) * 0.3 * delta_time
            else:
                self.progress = max(0, self.progress - 0.1 * delta_time)

        elif self.type == ObjectiveType.ESCORT_PAYLOAD:
            # Progress based on proximity to destination
            self.progress += len(nearby_robots) * 0.2 * delta_time

        # Check completion
        if self.progress >= self.max_progress:
            self.is_active = False
            logger.info(f"Objective {self.type.value} completed by {self.team.value} team!")


@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    spawn_time: float
    duration: float = 20.0
    is_active: bool = True
    collectible: bool = True

    def update(self, robots: Dict[str, Robot], delta_time: float):
        """Check if any robot has collected this power-up"""
        if not self.is_active or not self.collectible:
            return

        for robot in robots.values():
            if robot.is_active and robot.position.distance_to(self.position) < 10:
                robot.add_power_up(self.type, self.duration)
                self.collectible = False
                self.is_active = False
                logger.info(f"Power-up {self.type.value} collected by {robot.id}")
                break


@dataclass
class EnvironmentHazard:
    type: EnvironmentHazard
