    radius: float
    damage_per_second: float
    is_active: bool = True

    def update(self, robots: Dict[str, Robot], delta_time: float):
        """Apply damage to robots in hazard zone"""
        if not self.is_active:
            return

        for robot in robots.values():
            if robot.is_active and robot.position.distance_to(self.position) < self.radius:
                robot.take_damage(self.damage_per_second * delta_time)
