class AIBehavior:
    """Base class for AI behavior patterns"""

    def __init__(self, robot: Robot, game_state: GameState):
        self.robot = robot
        self.game_state = game_state
        self.target_position = None
        self.last_behavior_time = 0.0
        self.behavior_state = "idle"

    def update(self, delta_time: float) -> Optional[Vector2D]:
        """Return the desired movement target or None for default behavior"""
        raise NotImplementedError


class AttackBehavior(AIBehavior):
    """Aggressive behavior: seek and destroy enemies"""

    def update(self, delta_time: float) -> Optional[Vector2D]:
        self.last_behavior_time += delta_time

        # Find closest enemy
        closest_enemy = None
        min_distance = float('inf')

        for robot in self.game_state.get_alive_robots():
            if robot.team != self.robot.team and robot.is_active:
                distance = self.robot.position.distance_to(robot.position)
                if distance < min_distance:
                    min_distance = distance
                    closest_enemy = robot

        if closest_enemy and min_distance < 120:  # Attack range
            self.behavior_state = "attacking"
            return closest_enemy.position
        else:
            self.behavior_state = "patrolling"
            # Patrol to a random location
            if self.last_behavior_time > 3.0:
                self.target_position = Vector2D(
                    random.uniform(0, 100),
                    random.uniform(0, 100)
                )
                self.last_behavior_time = 0
            return self.target_position


class SupportBehavior(AIBehavior):
    """Support behavior: heal teammates and provide buffs"""

    def update(self, delta_time: float) -> Optional[Vector2D]:
        self.last_behavior_time += delta_time

        # If we have healing weapon, look for injured teammates
        if self.robot.weapon == WeaponType.HEALING_GUN:
            # Find lowest health teammate
            lowest_health_teammate = None
            min_health = float('inf')

            for robot in self.game_state.get_team_robots(self.robot.team):
                if robot != self.robot and robot.is_active and robot.health < min_health:
                    min_health = robot.health
                    lowest_health_teammate = robot

            if lowest_health_teammate and min_health < 70:
                self.behavior_state = "healing"
                return lowest_health_teammate.position

        # If no healing needed, defend objectives
        for objective in self.game_state.objectives:
            if objective.team == self.robot.team and objective.captured_by == self.robot.team:
                distance = self.robot.position.distance_to(objective.position)
                if distance > 40:  # Too far from objective
                    self.behavior_state = "defending"
                    return objective.position

        # Default: patrol
        if self.last_behavior_time > 5.0:
            self.target_position = Vector2D(
                random.uniform(0, 100),
                random.uniform(0, 100)
            )
            self.last_behavior_time = 0
        return self.target_position


class ReconBehavior(AIBehavior):
    """Recon behavior: scout, gather intelligence, and report"""

    def update(self, delta_time: float) -> Optional[Vector2D]:
        self.last_behavior_time += delta_time

        # Gather intelligence about enemy positions
        enemy_positions = []
        for robot in self.game_state.get_alive_robots():
            if robot.team != self.robot.team:
                enemy_positions.append(robot.position)

        # Store intelligence for learning
        if enemy_positions:
            self.robot.knowledge_base['enemy_positions'] = enemy_positions
            logger.info(f"Robot {self.robot.id} gathered enemy data")

        # Find nearest objective not captured by our team
        target_objective = None
        min_distance = float('inf')

        for objective in self.game_state.objectives:
            if objective.captured_by != self.robot.team and objective.is_active:
                distance = self.robot.position.distance_to(objective.position)
                if distance < min_distance:
                    min_distance = distance
                    target_objective = objective

        if target_objective:
            self.behavior_state = "scouting"
            return target_objective.position

        # If no objectives, move to perimeter
        if self.last_behavior_time > 4.0:
            # Move toward map edge for better vision
            self.target_position = Vector2D(
                random.choice([10, 90]),
                random.choice([10, 90])
            )
            self.last_behavior_time = 0
        return self.target_position


class TankBehavior(AIBehavior):
    """Tank behavior: hold positions and absorb damage"""

    def update(self, delta_time: float) -> Optional[Vector2D]:
        self.last_behavior_time += delta_time

        # Find closest objective to defend
        target_objective = None
        min_distance = float('inf')

        for objective in self.game_state.objectives:
            if objective.team == self.robot.team:
                distance = self.robot.position.distance_to(objective.position)
                if distance < min_distance:
                    min_distance = distance
                    target_objective = objective

        if target_objective:
            self.behavior_state = "defending"
            return target_objective.position

        # If no objectives, defend team spawn point
        spawn_point = Vector2D(20, 20) if self.robot.team == Team.RED else Vector2D(80, 80)
        if self.last_behavior_time > 6.0:
            self.target_position = spawn_point
            self.last_behavior_time = 0

        return self.target_position


class AIController:
    """Main AI controller that selects appropriate behavior based on robot type and situation"""

    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.behaviors = {}

    def update(self, delta_time: float):
        """Update all AI robots"""
        for robot_id, robot in self.game_state.robots.items():
            if robot.team == Team.NEUTRAL:
                continue  # Skip neutral robots (player-controlled)

            # Create behavior if not exists
            if robot_id not in self.behaviors:
                if robot.robot_type == RobotType.ASSAULT:
                    self.behaviors[robot_id] = AttackBehavior(robot, self.game_state)
                elif robot.robot_type == RobotType.SUPPORT:
                    self.behaviors[robot_id] = SupportBehavior(robot, self.game_state)
                elif robot.robot_type == RobotType.RECON:
                    self.behaviors[robot_id] = ReconBehavior(robot, self.game_state)
                elif robot.robot_type == RobotType.TANK:
                    self.behaviors[robot_id] = TankBehavior(robot, self.game_state)

            # Update behavior
            behavior = self.behaviors[robot_id]
            target = behavior.update(delta_time)

            # Move robot toward target if available
            if target:
                robot.move_toward(target, delta_time)

            # Decide on weapon usage
            if robot.can_perform_action():
                # Use weapon if enemy is close enough
                for enemy in self.game_state.get_alive_robots():
                    if enemy.team != robot.team:
                        distance = robot.position.distance_to(enemy.position)
                        weapon_range = {
                            WeaponType.LASER_RIFLE: 100,
                            WeaponType.PLASMA_CANNON: 150,
                            WeaponType.SHOTGUN: 40,
                            WeaponType.CHAIN_SAW: 15,
                            WeaponType.MISSILE_LAUNCHER: 200,
                            WeaponType.HEALING_GUN: 80
                        }.get(robot.weapon, 100)

                        if distance <= weapon_range:
                            robot.use_weapon(enemy.position, self.game_state.robots)
                            break


