@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team: Team
    progress: float = 0.0
    max_progress: float = 100.0
    captured_by: Optional[Team] = None
    defenders: Set[str] = field(default_factory=set)
    is_active: bool = True

    def update(self, robots: Dict[str, Robot], delta_time: float):
        """Update objective state based on nearby robots"""
        if not self.is_active:
            return

        nearby_robots = []
        for robot in robots.values():
            if robot.is_active and robot.team != Team.NEUTRAL:
                distance = robot.position.distance_to(self.position)
                if distance < 30:  # Capture radius
                    nearby_robots.append(robot)

        # Logic for different objective types
        if self.type == ObjectiveType.CAPTURE_FLAG:
            # Only one team can capture at a time
            team_counts = defaultdict(int)
            for robot in nearby_robots:
                team_counts[robot.team] += 1

            # Determine leading team
            if team_counts:
                leading_team = max(team_counts.keys(), key=lambda t: team_counts[t])
                if team_counts[leading_team] >= 2:  # Need at least 2 robots to capture
                    self.progress += team_counts[leading_team] * 0.5 * delta_time
                    self.captured_by = leading_team

                    # Reset if other team gains control
                    if self.captured_by != self.team:
                        self.team = self.captured_by
                        logger.info(f"Objective captured by {self.captured_by.value} team!")

                # Decay progress if no robots nearby
                if team_counts[self.team] == 0:
                    self.progress = max(0, self.progress - 0.1 * delta_time)

        elif self.type == ObjectiveType.DEFEND_BASE:
            # Defenders add to progress
            self.defenders = {robot.id for robot in nearby_robots if robot.team == self.team}
            if len(self.defenders) > 0:
                self.progress += len(self.defenders) * 0.3 * delta_time
            else:
                self.progress = max(0, self.progress - 0.1 * delta_time)

        elif self.type == ObjectiveType.ESCORT_PAYLOAD:
            # Progress based on proximity to destination
            self.progress += len(nearby_robots) * 0.2 * delta_time

        # Check completion
        if self.progress >= self.max_progress:
            self.is_active = False
            logger.info(f"Objective {self.type.value} completed by {self.team.value} team!")


