    def update(self, robots: Dict[str, Robot], delta_time: float):
        """Check if any robot has collected this power-up"""
        if not self.is_active or not self.collectible:
            return

        for robot in robots.values():
            if robot.is_active and robot.position.distance_to(self.position) < 10:
                robot.add_power_up(self.type, self.duration)
                self.collectible = False
                self.is_active = False
                logger.info(f"Power-up {self.type.value} collected by {robot.id}")
                break


@dataclass
class EnvironmentHazard:
    type: EnvironmentHazard
    position: Vector2D
    radius: float
    damage_per_second: float
    is_active: bool = True

    def update(self, robots: Dict[str, Robot], delta_time: float):
        """Apply damage to robots in hazard zone"""
        if not self.is_active:
