@dataclass
class GameState:
    time: float = 0.0
    round_duration: float = 300.0  # 5 minutes
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[EnvironmentHazard] = field(default_factory=list)
    robots: Dict[str, Robot] = field(default_factory=dict)
    active: bool = True
    winner: Optional[Team] = None
    battle_log: List[str] = field(default_factory=list)

    def add_robot(self, robot: Robot):
        self.robots[robot.id] = robot

    def add_objective(self, objective: Objective):
        self.objectives.append(objective)

    def add_power_up(self, power_up: PowerUp):
        self.power_ups.append(power_up)

    def add_hazard(self, hazard: EnvironmentHazard):
        self.hazards.append(hazard)

    def get_team_robots(self, team: Team) -> List[Robot]:
        return [r for r in self.robots.values() if r.team == team and r.is_active]

    def get_alive_robots(self) -> List[Robot]:
        return [r for r in self.robots.values() if r.is_active]

    def update(self, delta_time: float):
        """Update entire game state"""
        self.time += delta_time

        # Update all robots
        for robot in self.robots.values():
            robot.update(delta_time)

        # Update objectives
        for objective in self.objectives:
            objective.update(self.robots, delta_time)

            # Check for objective completion
            if not objective.is_active and objective.captured_by:
                self.team_scores[objective.captured_by] += 100
                self.battle_log.append(f"Objective completed! {objective.captured_by.value} team earns 100 points!")

        # Update power-ups
        for power_up in self.power_ups[:]:  # Copy list to allow modification
            power_up.update(self.robots, delta_time)
            if not power_up.is_active and not power_up.collectible:
                self.power_ups.remove(power_up)

        # Update hazards
        for hazard in self.hazards:
            hazard.update(self.robots, delta_time)

        # Check game end conditions
        red_robots = self.get_team_robots(Team.RED)
        blue_robots = self.get_team_robots(Team.BLUE)

        if len(red_robots) == 0:
            self.winner = Team.BLUE
            self.active = False
            self.battle_log.append("BLUE TEAM WINS! RED TEAM ELIMINATED!")
        elif len(blue_robots) == 0:
            self.winner = Team.RED
            self.active = False
            self.battle_log.append("RED TEAM WINS! BLUE TEAM ELIMINATED!")
        elif self.time >= self.round_duration:
            # Time's up, determine winner by score
            if self.team_scores[Team.RED] > self.team_scores[Team.BLUE]:
                self.winner = Team.RED
                self.battle_log.append("TIME'S UP! RED TEAM WINS BY SCORE!")
            elif self.team_scores[Team.BLUE] > self.team_scores[Team.RED]:
                self.winner = Team.BLUE
                self.battle_log.append("TIME'S UP! BLUE TEAM WINS BY SCORE!")
            else:
                self.battle_log.append("TIME'S UP! IT'S A TIE!")
            self.active = False

        # Update scores based on team objectives
        for obj in self.objectives:
            if obj.captured_by:
                self.team_scores[obj.captured_by] += 1  # Bonus point per tick for holding objective


