class AdaptiveDifficulty:
    """Adjusts game difficulty based on team performance"""

    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.difficulty_level = 1.0  # 1.0 = normal, >1.0 harder, <1.0 easier
        self.performance_history = deque(maxlen=20)
        self.last_update_time = 0.0

    def calculate_performance(self) -> float:
        """Calculate team performance as a ratio of scores"""
        red_score = self.game_state.team_scores[Team.RED]
        blue_score = self.game_state.team_scores[Team.BLUE]

        if red_score + blue_score == 0:
            return 0.5  # Neutral

        return red_score / (red_score + blue_score)

    def update(self, delta_time: float) -> bool:
        """Update difficulty based on performance"""
        self.last_update_time += delta_time
        if self.last_update_time < 15.0:  # Update every 15 seconds
            return False

        self.last_update_time = 0.0

        # Get current performance
        performance = self.calculate_performance()
        self.performance_history.append(performance)

        # Calculate average performance over time
        if len(self.performance_history) >= 3:
            avg_performance = sum(self.performance_history) / len(self.performance_history)

            # Adjust difficulty based on performance imbalance
            # If one team is dominating, make it harder for them and easier for the other
            if avg_performance > 0.7:  # Red team dominating
                self.difficulty_level = 0.8  # Make it harder for red, easier for blue
                logger.info(f"Difficulty adjusted to {self.difficulty_level}: Blue team needs help")
            elif avg_performance < 0.3:  # Blue team dominating
                self.difficulty_level = 1.2  # Make it harder for blue, easier for red
                logger.info(f"Difficulty adjusted to {self.difficulty_level}: Red team needs help")
            else:  # Balanced
                self.difficulty_level = 1.0
                logger.info("Difficulty maintained at normal level")

        # Apply difficulty adjustments to AI behavior
        self.adjust_ai_behavior()
        return True

    def adjust_ai_behavior(self):
        """Modify AI behavior based on difficulty level"""
        for robot in self.game_state.robots.values():
            if robot.team == Team.NEUTRAL:
                continue

            # Adjust AI aggression and accuracy based on difficulty
            if self.difficulty_level > 1.0 and robot.team == Team.RED:
                # Make red team AI more aggressive
                robot.speed = min(1.5, robot.speed * 1.1)
                robot.max_health = min(120, robot.max_health * 1.1)
                robot.ammo = min(150, robot.ammo * 1.1)

                # Increase AI decision speed
                robot.knowledge_base['adaptation_rate'] = min(0.3, robot.knowledge_base['adaptation_rate'] * 1.2)

            elif self.difficulty_level < 1.0 and robot.team == Team.BLUE:
                # Make blue team AI more aggressive
                robot.speed = min(1.5, robot.speed * 1.1)
                robot.max_health = min(120, robot.max_health * 1.1)
                robot.ammo = min(150, robot.ammo * 1.1)

                # Increase AI decision speed
                robot.knowledge_base['adaptation_rate'] = min(0.3, robot.knowledge_base['adaptation_rate'] * 1.2)

            # Adjust enemy AI behavior based on difficulty
            if self.difficulty_level > 1.0 and robot.team == Team.BLUE:
                # Make blue team AI slightly less effective
                robot.speed = max(0.5, robot.speed * 0.9)
                robot.max_health = max(80, robot.max_health * 0.9)
                robot.knowledge_base['adaptation_rate'] = max(0.05, robot.knowledge_base['adaptation_rate'] * 0.8)

            elif self.difficulty_level < 1.0 and robot.team == Team.RED:
                # Make red team AI slightly less effective
                robot.speed = max(0.5, robot.speed * 0.9)
                robot.max_health = max(80, robot.max_health * 0.9)
                robot.knowledge_base['adaptation_rate'] = max(0.05, robot.knowledge_base['adaptation_rate'] * 0.8)


