class LearningSystem:
    """Enables robots to learn from past battles and improve strategy"""

    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.learning_data = {}
        self.last_learning_time = 0.0

    def update(self, delta_time: float) -> bool:
        """Update learning system, store and analyze data"""
        self.last_learning_time += delta_time
        if self.last_learning_time < 30.0:  # Learn every 30 seconds
            return False

        self.last_learning_time = 0.0

        # Analyze battle data
        self.analyze_battle_data()

        # Update robot knowledge bases
        self.update_robot_knowledge()

        return True

    def analyze_battle_data(self):
        """Store current battle data for future analysis"""
        data = {
            'time': self.game_state.time,
            'team_scores': self.game_state.team_scores.copy(),
            'robots_active': len(self.game_state.get_alive_robots()),
            'objectives_completed': [obj for obj in self.game_state.objectives if not obj.is_active],
            'battle_log': self.game_state.battle_log[-10:]  # Last 10 events
        }

        # Store in memory (could be persisted to file in a real system)
        self.learning_data[len(self.learning_data)] = data
        logger.info(f"Learning data saved: {len(self.learning_data)} entries")

    def update_robot_knowledge(self):
        """Update robot knowledge bases based on learning data"""
        for robot in self.game_state.robots.values():
            if robot.team == Team.NEUTRAL:
                continue

            # Simple adaptation based on win/loss ratio
            wins = robot.knowledge_base['wins']
            losses = robot.knowledge_base['losses']

            if wins + losses > 0:
                win_rate = wins / (wins + losses)
                # Adjust adaptation rate based on performance
                if win_rate > 0.7:
                    # High-performing robot: focus on advanced strategies
                    robot.knowledge_base['adaptation_rate'] = min(0.3, robot.knowledge_base['adaptation_rate'] * 1.1)
                elif win_rate < 0.3:
                    # Low-performing robot: become more cautious
                    robot.knowledge_base['adaptation_rate'] = max(0.05, robot.knowledge_base['adaptation_rate'] * 0.9)

                # Learn from team success
                if robot.team == Team.RED and self.game_state.team_scores[Team.RED] > self.game_state.team_scores[Team.BLUE]:
                    robot.knowledge_base['teamwork_score'] = min(1.0, robot.knowledge_base['teamwork_score'] + 0.05)
                elif robot.team == Team.BLUE and self.game_state.team_scores[Team.BLUE] > self.game_state.team_scores[Team.RED]:
                    robot.knowledge_base['teamwork_score'] = min(1.0, robot.knowledge_base['teamwork_score'] + 0.05)
                else:
                    robot.knowledge_base['teamwork_score'] = max(0.1, robot.knowledge_base['teamwork_score'] - 0.01)

                logger.info(f"Robot {robot.id} - Teamwork: {robot.knowledge_base['teamwork_score']:.2f}, Adaptation: {robot.knowledge_base['adaptation_rate']:.2f}")


