    SCOUT = "Scout"
    CONTROLLER = "Controller"

# Weapon types
class WeaponType(Enum):
    RANGED = "Ranged"
    MELEE = "Melee"
    EXPLOSIVE = "Explosive"
    SUPPORT = "Support"

# Power-up types
class PowerUpType(Enum):
    HEALTH = "Health"
    SHIELD = "Shield"
    SPEED = "Speed"
    DAMAGE = "Damage"
    REGEN = "Regeneration"
    TELEPORT = "Teleport"

# Environmental hazards
class HazardType(Enum):
    LAVA = "Lava"
    ELECTRIC = "Electric"
    GAS = "Gas"
    GRAVITY = "Gravity"

# Objective types
class ObjectiveType(Enum):
    FLAG_CAPTURE = "FlagCapture"
