@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def copy(self):
        return Vector2D(self.x, self.y)

@dataclass
class Robot:
    id: int
    team: Team
    role: Role = Role.ATTACKER
    position: Vector2D = field(default_factory=Vector2D)
    velocity: Vector2D = field(default_factory=Vector2D)
    health: float = 100.0
    max_health: float = 100.0
    shield: float = 0.0
    max_shield: float = 50.0
    speed: float = 3.0
    weapon: 'Weapon' = None
    cooldown: float = 0.0
    last_action_time: float = 0.0
    last_seen_enemy: Optional['Robot'] = None
    target_objective: Optional[Object] = None
    knowledge_base: Dict = field(default_factory=dict)
    strategy_memory: List = field(default_factory=list)
    is_alive: bool = True
    weapon_range: float = 200.0
    melee_range: float = 50.0
    fov: float = 180.0  # Field of view in degrees
    visual_range: float = 300.0

    def update(self, dt: float, game_state: 'Game'):
        if not self.is_alive:
            return

        # Update cooldown
        if self.cooldown > 0:
            self.cooldown -= dt

        # Update position based on velocity
        self.position += self.velocity * dt

        # Apply friction
        self.velocity *= 0.95

        # Keep robot within bounds
        self.position.x = max(10, min(SCREEN_WIDTH - 10, self.position.x))
        self.position.y = max(10, min(SCREEN_HEIGHT - 10, self.position.y))

        # Check for hazards
        self.check_hazards(game_state)

        # Check for power-ups
        self.check_powerups(game_state)

        # Update AI behavior
        self.ai_behavior(game_state)

        # Update knowledge base with new observations
        self.update_knowledge(game_state)

        # Update strategy memory
        self.update_strategy_memory(game_state)

    def check_hazards(self, game_state: 'Game'):
        for hazard in game_state.hazards:
            if (self.position.distance_to(hazard.position) < hazard.radius):
                damage = hazard.damage_per_second * (1 - self.shield / self.max_shield)
                self.take_damage(damage * 0.1)  # Reduced damage due to shield
                # Apply push effect from hazard
                direction = (self.position - hazard.position).normalize()
                self.velocity += direction * 0.5

    def check_powerups(self, game_state: 'Game'):
        for powerup in game_state.powerups[:]:
            if self.position.distance_to(powerup.position) < powerup.radius:
                self.apply_powerup(powerup, game_state)
                game_state.powerups.remove(powerup)

    def apply_powerup(self, powerup: 'PowerUp', game_state: 'Game'):
        if powerup.type == PowerUpType.HEALTH:
            self.health = min(self.max_health, self.health + 25)
        elif powerup.type == PowerUpType.SHIELD:
            self.shield = min(self.max_shield, self.shield + 20)
        elif powerup.type == PowerUpType.SPEED:
            self.speed *= 1.5
            # Timer for speed boost (5 seconds)
            threading.Timer(5.0, lambda: setattr(self, 'speed', self.speed / 1.5)).start()
        elif powerup.type == PowerUpType.DAMAGE:
            self.weapon.damage *= 1.5
            threading.Timer(8.0, lambda: setattr(self.weapon, 'damage', self.weapon.damage / 1.5)).start()
        elif powerup.type == PowerUpType.REGEN:
            # Regeneration effect
            self.health_regen_rate = 5.0
            threading.Timer(10.0, lambda: setattr(self, 'health_regen_rate', 0.0)).start()
        elif powerup.type == PowerUpType.TELEPORT:
            # Teleport to a random safe location
            safe_pos = game_state.get_safe_position()
            self.position = safe_pos.copy()

    def take_damage(self, damage: float):
        # Apply shield absorption first
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        # Apply remaining damage to health
        if damage > 0:
            self.health -= damage

        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            # Play death sound
            pygame.mixer.Sound('sounds/death.wav').play()

    def heal(self, amount: float):
        self.health = min(self.max_health, self.health + amount)

    def ai_behavior(self, game_state: 'Game'):
        # Get the closest enemies within range
        enemies = []
        for robot in game_state.robots:
            if robot.team != self.team and robot.is_alive:
                distance = self.position.distance_to(robot.position)
                if distance < self.visual_range:
                    enemies.append((robot, distance))

        if enemies:
            # Sort by distance
            enemies.sort(key=lambda x: x[1])
            self.last_seen_enemy = enemies[0][0]

            # AI behavior based on role
            if self.role == Role.ATTACKER:
                self.attack_behavior(enemies[0][0], game_state)
            elif self.role == Role.DEFENDER:
                self.defend_behavior(game_state)
            elif self.role == Role.SUPPORT:
                self.support_behavior(game_state)
            elif self.role == Role.SCOUT:
                self.scout_behavior(game_state)
            elif self.role == Role.CONTROLLER:
                self.controller_behavior(game_state)

        else:
            # No enemies visible, pursue objectives or patrol
            self.objective_behavior(game_state)

    def attack_behavior(self, target: 'Robot', game_state: 'Game'):
        # Calculate direction to target
        direction = (target.position - self.position).normalize()

        # If enemy is in range and weapon is ready
        distance = self.position.distance_to(target.position)

        if distance <= self.weapon_range and self.cooldown <= 0:
            # Fire weapon
            self.fire_weapon(target.position)
        elif distance <= self.melee_range and self.cooldown <= 0:
            # Use melee attack
            self.melee_attack(target)
        else:
            # Move toward target
            self.velocity = direction * self.speed

    def defend_behavior(self, game_state: 'Game'):
        # Defend key objectives
        if game_state.objectives:
            # Find the closest objective to defend
            closest_obj = None
            min_dist = float('inf')

            for obj in game_state.objectives:
                if obj.team == self.team and obj.type in [ObjectiveType.BASE_DEFENSE, ObjectiveType.FLAG_CAPTURE]:
                    dist = self.position.distance_to(obj.position)
                    if dist < min_dist:
                        min_dist = dist
                        closest_obj = obj

            if closest_obj:
                # Move toward objective
                direction = (closest_obj.position - self.position).normalize()
                self.velocity = direction * self.speed

                # If near objective, stay close and watch for enemies
                if min_dist < 100:
                    # Look for enemies near objective
                    enemies_near_obj = []
                    for robot in game_state.robots:
                        if robot.team != self.team and robot.is_alive:
                            if robot.position.distance_to(closest_obj.position) < 150:
                                enemies_near_obj.append(robot)

                    if enemies_near_obj:
                        # Attack the closest enemy near objective
                        closest_enemy = min(enemies_near_obj, key=lambda r: r.position.distance_to(self.position))
