    def support_behavior(self, game_state: 'Game'):
        # Find teammates in need of support
        allies_in_need = []
        for robot in game_state.robots:
            if robot.team == self.team and robot.is_alive and robot.health < robot.max_health * 0.5:
                allies_in_need.append(robot)

        if allies_in_need:
            # Go to the healthiest ally in need
            ally = min(allies_in_need, key=lambda a: a.health)
            direction = (ally.position - self.position).normalize()
            self.velocity = direction * self.speed

            # If close enough, provide support (heal or shield)
            if self.position.distance_to(ally.position) < 80:
                # Use support weapon if available
                if self.weapon and self.weapon.type == WeaponType.SUPPORT and self.cooldown <= 0:
                    self.use_support_weapon(ally)
        else:
            # Patrol a strategic location
            if game_state.objectives:
                # Find a central location
                central_point = Vector2D(SCREEN_WIDTH/2, SCREEN_HEIGHT/2)
                direction = (central_point - self.position).normalize()
                self.velocity = direction * self.speed

    def scout_behavior(self, game_state: 'Game'):
        # Move to explore uncharted areas
        # Use vision to find empty areas
        explored_points = set()
        for robot in game_state.robots:
            if robot.team == self.team:
                # Mark areas around teammates as explored
                explored_points.add((int(robot.position.x), int(robot.position.y)))

        # Find a direction with low density of explored points
        # Use a simple algorithm: check multiple directions
        best_direction = Vector2D(1, 0)
        min_density = float('inf')

        for angle in range(0, 360, 30):
            dir_x = math.cos(math.radians(angle))
            dir_y = math.sin(math.radians(angle))
            direction = Vector2D(dir_x, dir_y)

            # Check density of explored points in this direction
            check_point = self.position + direction * 200
            density = 0
            for exp_x, exp_y in explored_points:
                if abs(exp_x - check_point.x) < 50 and abs(exp_y - check_point.y) < 50:
                    density += 1

            if density < min_density:
                min_density = density
                best_direction = direction

        # Move in best direction
        self.velocity = best_direction * self.speed * 1.2  # Scout moves faster

    def controller_behavior(self, game_state: 'Game'):
        # Control key areas and coordinate team
        if game_state.objectives:
            # Find objectives that need control
            objectives_in_play = [obj for obj in game_state.objectives if obj.team != self.team]

            if objectives_in_play:
                # Go to the most contested objective
                best_obj = min(objectives_in_play, key=lambda obj: obj.progress)
                direction = (best_obj.position - self.position).normalize()
                self.velocity = direction * self.speed

                # If close, set up control area
                if self.position.distance_to(best_obj.position) < 120:
                    # Use control ability
                    if self.weapon and self.weapon.type == WeaponType.SUPPORT and self.cooldown <= 0:
                        self.use_control_ability(best_obj)

    def objective_behavior(self, game_state: 'Game'):
        # If no enemies visible, move toward objectives
        if game_state.objectives:
            # Find the closest objective of our team
            our_objectives = [obj for obj in game_state.objectives if obj.team == self.team]

            if our_objectives:
                closest_obj = min(our_objectives, key=lambda obj: self.position.distance_to(obj.position))
                direction = (closest_obj.position - self.position).normalize()
                self.velocity = direction * self.speed
            else:
                # Move toward enemy objectives to capture
                enemy_objectives = [obj for obj in game_state.objectives if obj.team != self.team]
                if enemy_objectives:
                    closest_obj = min(enemy_objectives, key=lambda obj: self.position.distance_to(obj.position))
                    direction = (closest_obj.position - self.position).normalize()
                    self.velocity = direction * self.speed
        else:
            # Patrol a random location
            self.velocity = Vector2D(
                random.uniform(-1, 1), 
                random.uniform(-1, 1)
            ).normalize() * self.speed

    def fire_weapon(self, target_pos: Vector2D):
        if self.weapon and self.cooldown <= 0:
            # Create projectile
            projectile = Projectile(
                position=self.position.copy(),
                target=target_pos,
                speed=15,
                damage=self.weapon.damage,
                team=self.team,
                weapon_type=self.weapon.type
            )
            self.projectiles.append(projectile)
            self.cooldown = self.weapon.cooldown
            # Play weapon sound
            pygame.mixer.Sound('sounds/fire.wav').play()

    def melee_attack(self, target: 'Robot'):
        if self.cooldown <= 0:
            # Direct damage
            target.take_damage(self.weapon.damage)
            # Visual effect
            self.cooldown = self.weapon.cooldown
            # Play melee sound
            pygame.mixer.Sound('sounds/melee.wav').play()

    def use_support_weapon(self, ally: 'Robot'):
        if self.weapon.type == WeaponType.SUPPORT:
            if self.weapon.subtype == "Heal":
                ally.heal(self.weapon.damage)
            elif self.weapon.subtype == "Shield":
                ally.shield = min(ally.max_shield, ally.shield + self.weapon.damage)
            self.cooldown = self.weapon.cooldown
