            objective.progress += 10
            self.cooldown = self.weapon.cooldown
            pygame.mixer.Sound('sounds/control.wav').play()

    def update_knowledge(self, game_state: 'Game'):
        # Update knowledge base with observations
        for robot in game_state.robots:
            if robot.team != self.team and robot.is_alive:
                # Track enemy positions
                if robot.id not in self.knowledge_base:
                    self.knowledge_base[robot.id] = {
                        'last_seen': time.time(),
                        'positions': [],
                        'team': robot.team
                    }
                self.knowledge_base[robot.id]['last_seen'] = time.time()
                self.knowledge_base[robot.id]['positions'].append(robot.position.copy())
                # Keep only last 10 positions
                if len(self.knowledge_base[robot.id]['positions']) > 10:
                    self.knowledge_base[robot.id]['positions'].pop(0)

    def update_strategy_memory(self, game_state: 'Game'):
        # Store recent actions and outcomes
        if time.time() - self.last_action_time > 1.0:
            # Record a snapshot of current state
            memory = {
                'time': time.time(),
                'role': self.role,
                'health': self.health,
                'shield': self.shield,
                'objective_target': self.target_objective,
                'enemy_targets': len([r for r in game_state.robots if r.team != self.team and r.is_alive]),
                'success': self.is_alive
            }
            self.strategy_memory.append(memory)

            # Keep only last 20 memories
            if len(self.strategy_memory) > 20:
                self.strategy_memory.pop(0)

            self.last_action_time = time.time()

