@dataclass
class Projectile:
    position: Vector2D
    target: Vector2D
    speed: float
    damage: float
    team: Team
    weapon_type: WeaponType
    lifetime: float = 5.0
    age: float = 0.0
    direction: Vector2D = field(init=False)

    def __post_init__(self):
        # Calculate direction vector
        direction_vector = self.target - self.position
        if direction_vector.magnitude() > 0:
            self.direction = direction_vector.normalize()
        else:
            self.direction = Vector2D(1, 0)

    def update(self, dt: float):
        self.position += self.direction * self.speed * dt
        self.age += dt

        # Remove if expired
        if self.age >= self.lifetime:
            return False
        return True

    def get_position(self) -> Vector2D:
        return self.position

@dataclass
class Object:
    id: int
    position: Vector2D
    team: Team
    type: ObjectiveType
    radius: float = 40.0
    progress: float = 0.0  # 0-100 (capture/defense progress)
    is_active: bool = True
    capture_rate: float = 1.0  # % per second
    defenders: int = 0
    attackers: int = 0

    def update(self, game_state: 'Game', dt: float):
        if not self.is_active:
            return

        # Update defender and attacker counts
        self.defenders = 0
        self.attackers = 0

        for robot in game_state.robots:
            if robot.is_alive and robot.position.distance_to(self.position) < self.radius + 50:
                if robot.team == self.team:
                    self.defenders += 1
                else:
                    self.attackers += 1

        # Update progress based on control
        if self.defenders > 0 and self.attackers == 0:
            # Team defending
            self.progress = min(100, self.progress + self.capture_rate * dt * 5)
        elif self.attackers > 0 and self.defenders == 0:
            # Team attacking
            self.progress = max(0, self.progress - self.capture_rate * dt * 5)
        elif self.attackers > 0 and self.defenders > 0:
            # Both sides
            if self.attackers > self.defenders:
                self.progress = max(0, self.progress - self.capture_rate * dt * 2)
            elif self.defenders > self.attackers:
                self.progress = min(100, self.progress + self.capture_rate * dt * 2)

        # Objective completed
        if self.progress >= 100 and self.type == ObjectiveType.FLAG_CAPTURE:
            game_state.score[self.team.name] += 100
            # Play victory sound
            pygame.mixer.Sound('sounds/objective_complete.wav').play()
            self.is_active = False
            # Spawn a new objective
            game_state.spawn_objective()
        elif self.progress <= 0 and self.type == ObjectiveType.FLAG_CAPTURE:
            # Objective captured by enemy
            game_state.score[self.team.name] -= 50
            self.is_active = False
            game_state.spawn_objective()

    def draw(self, screen):
        color = (255, 0, 0) if self.team == Team.RED else (0, 0, 255)
        pygame.draw.circle(screen, color, (int(self.position.x), int(self.position.y)), int(self.radius))

        # Draw progress bar
        bar_width = 50
        bar_height = 8
        bar_x = self.position.x - bar_width // 2
        bar_y = self.position.y - self.radius - 15

        pygame.draw.rect(screen, (100, 100, 100), (bar_x, bar_y, bar_width, bar_height))
        pygame.draw.rect(screen, color, (bar_x, bar_y, bar_width * (self.progress / 100), bar_height))

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    radius: float = 20.0
    lifespan: float = 30.0
    age: float = 0.0
    spawn_time: float = field(default_factory=time.time)

    def update(self, dt: float):
        self.age += dt
        return self.age < self.lifespan

    def draw(self, screen):
        color_map = {
            PowerUpType.HEALTH: (0, 255, 0),
            PowerUpType.SHIELD: (0, 120, 255),
            PowerUpType.SPEED: (255, 255, 0),
            PowerUpType.DAMAGE: (255, 0, 0),
            PowerUpType.REGEN: (120, 0, 255),
            PowerUpType.TELEPORT: (255, 165, 0)
        }
        color = color_map.get(self.type, (255, 255, 255))
        pygame.draw.circle(screen, color, (int(self.position.x), int(self.position.y)), int(self.radius))

        # Draw pulsing effect
        pulse_size = 1 + math.sin(time.time() * 5) * 0.2
        pygame.draw.circle(screen, color, (int(self.position.x), int(self.position.y)), 
                          int(self.radius * pulse_size), 2)

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float = 60.0
    damage_per_second: float = 5.0
    color: Tuple[int, int, int] = field(default_factory=lambda: (255, 100, 0))

    def update(self, dt: float):
        # Hazards are static, but could have dynamic behavior
        pass

    def draw(self, screen):
        # Draw hazard with visual effect
        for i in range(3):
            alpha = 50 + (i * 30)
            radius = self.radius + i * 5
            surface = pygame.Surface((radius * 2, radius * 2), pygame.SRCALPHA)
            pygame.draw.circle(surface, (*self.color, alpha), (radius, radius), radius)
            screen.blit(surface, (self.position.x - radius, self.position.y - radius))

@dataclass
class Game:
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Object] = field(default_factory=list)
    powerups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    projectiles: List[Projectile] = field(default_factory=list)
    score: Dict = field(default_factory=lambda: {Team.RED.name: 0, Team.BLUE.name: 0})
    game_state: GameState = GameState.PREPARING
    time_elapsed: float = 0.0
    difficulty: float = 0.5  # 0.0 to 1.0 (normal)
    adaptive_system: Dict = field(default_factory=dict)
    last_spawn_time: float = 0.0
    spawn_interval: float = 45.0  # seconds

    def __post_init__(self):
        self.adaptive_system = {
            'enemy_ai_aggressiveness': 0.5,
            'enemy_ai_accuracy': 0.5,
            'enemy_ai_teamwork': 0.5,
            'powerup_frequency': 0.5,
            'hazard_frequency': 0.5,
            'objective_count': 3
        }
        self.initialize_game()

    def initialize_game(self):
        # Create robots
        for i in range(4):
            team = Team.RED if i < 2 else Team.BLUE
            role = random.choice(list(Role))
            position = Vector2D(
                random.uniform(100, SCREEN_WIDTH - 100),
                random.uniform(100, SCREEN_HEIGHT - 100)
            )
            weapon = Weapon.create_default_weapon(team)

            robot = Robot(
                id=i,
                team=team,
                role=role,
                position=position,
                weapon=weapon
            )
            self.robots.append(robot)

        # Create initial objectives
        for i in range(self.adaptive_system['objective_count']):
            team = random.choice([Team.RED, Team.BLUE])
            position = Vector2D(
                random.uniform(200, SCREEN_WIDTH - 200),
                random.uniform(200, SCREEN_HEIGHT - 200)
            )
            obj_type = random.choice([
                ObjectiveType.FLAG_CAPTURE,
                ObjectiveType.BASE_DEFENSE,
                ObjectiveType.ESCORT_PAYLOAD
            ])
            obj = Object(
                id=i,
                position=position,
                team=team,
                type=obj_type
            )
            self.objectives.append(obj)

        # Create hazards
        for i in range(2):
            hazard_type = random.choice(list(HazardType))
            position = Vector2D(
                random.uniform(100, SCREEN_WIDTH - 100),
                random.uniform(100, SCREEN_HEIGHT - 100)
            )
            color_map = {
                HazardType.LAVA: (255, 100, 0),
                HazardType.ELECTRIC: (255, 255, 100),
                HazardType.GAS: (100, 255, 100),
                HazardType.GRAVITY: (150, 150, 255)
            }
            hazard = Hazard(
                type=hazard_type,
                position=position,
                color=color_map[hazard_type]
            )
            self.hazards.append(hazard)

    def spawn_objective(self):
        # Spawn a new objective after one is completed
        team = random.choice([Team.RED, Team.BLUE])
        position = Vector2D(
            random.uniform(200, SCREEN_WIDTH - 200),
            random.uniform(200, SCREEN_HEIGHT - 200)
        )
        obj_type = random.choice([
            ObjectiveType.FLAG_CAPTURE,
            ObjectiveType.BASE_DEFENSE,
            ObjectiveType.ESCORT_PAYLOAD
        ])
        obj = Object(
            id=len(self.objectives),
            position=position,
            team=team,
            type=obj_type
        )
        self.objectives.append(obj)

    def spawn_powerup(self):
        if random.random() < self.adaptive_system['powerup_frequency'] * 0.1:
            powerup_type = random.choice(list(PowerUpType))
            position = Vector2D(
                random.uniform(100, SCREEN_WIDTH - 100),
                random.uniform(100, SCREEN_HEIGHT - 100)
            )
            # Make sure it's not too close to a hazard
            too_close = False
            for hazard in self.hazards:
                if position.distance_to(hazard.position) < 150:
                    too_close = True
                    break

            if not too_close:
                powerup = PowerUp(powerup_type, position)
                self.powerups.append(powerup)

    def spawn_hazard(self):
        if random.random() < self.adaptive_system['hazard_frequency'] * 0.05:
            hazard_type = random.choice(list(HazardType))
            position = Vector2D(
                random.uniform(100, SCREEN_WIDTH - 100),
                random.uniform(100, SCREEN_HEIGHT - 100)
            )
            color_map = {
                HazardType.LAVA: (255, 100, 0),
                HazardType.ELECTRIC: (255, 255, 100),
                HazardType.GAS: (100, 255, 100),
                HazardType.GRAVITY: (150, 150, 255)
            }
            hazard = Hazard(
                type=hazard_type,
                position=position,
                color=color_map[hazard_type]
            )
            self.hazards.append(hazard)

    def get_safe_position(self) -> Vector2D:
        # Find a position away from hazards and objectives
        attempts = 0
        while attempts < 100:
            pos = Vector2D(
                random.uniform(100, SCREEN_WIDTH - 100),
                random.uniform(100, SCREEN_HEIGHT - 100)
            )
            safe = True
            for hazard in self.hazards:
                if pos.distance_to(hazard.position) < 120:
                    safe = False
                    break
            for obj in self.objectives:
                if pos.distance_to(obj.position) < 80:
                    safe = False
                    break
            if safe:
                return pos
            attempts += 1
        # Fallback to random safe position
        return Vector2D(SCREEN_WIDTH/2, SCREEN_HEIGHT/2)

    def update(self, dt: float):
        if self.game_state != GameState.IN_PROGRESS:
            return

        self.time_elapsed += dt

        # Update robots
        for robot in self.robots:
            robot.update(dt, self)

        # Update projectiles
        self.projectiles = [p for p in self.projectiles if p.update(dt)]

        # Update objectives
        for obj in self.objectives:
            obj.update(self, dt)

        # Update powerups
        self.powerups = [p for p in self.powerups if p.update(dt)]

        # Update hazards
        for hazard in self.hazards:
            hazard.update(dt)

        # Check for collisions between projectiles and robots
        self.check_projectile_collisions()

        # Spawn powerups and hazards based on adaptive system
        if self.time_elapsed - self.last_spawn_time > self.spawn_interval:
            self.spawn_powerup()
            # Randomly spawn hazard every 90 seconds
            if self.time_elapsed % 90 < dt:
                self.spawn_hazard()
            self.last_spawn_time = self.time_elapsed

        # Adaptive difficulty system
        self.adaptive_difficulty()

    def check_projectile_collisions(self):
        for projectile in self.projectiles[:]:
            for robot in self.robots:
                if robot.team != projectile.team and robot.is_alive:
                    if projectile.position.distance_to(robot.position) < 30:
                        # Apply damage
                        robot.take_damage(projectile.damage)
                        # Remove projectile
                        self.projectiles.remove(projectile)
                        # Play hit sound
                        pygame.mixer.Sound('sounds/hit.wav').play()
                        break

    def adaptive_difficulty(self):
        # Calculate team performance
        red_score = self.score[Team.RED.name]
        blue_score = self.score[Team.BLUE.name]

