            self.adaptive_system['enemy_ai_aggressiveness'] = min(1.0, self.adaptive_system['enemy_ai_aggressiveness'] + 0.05)
            self.adaptive_system['enemy_ai_accuracy'] = min(1.0, self.adaptive_system['enemy_ai_accuracy'] + 0.03)
        elif blue_win_rate > 0.7:
            # Blue is dominating, make red more aggressive
            self.adaptive_system['enemy_ai_aggressiveness'] = min(1.0, self.adaptive_system['enemy_ai_aggressiveness'] + 0.05)
            self.adaptive_system['enemy_ai_accuracy'] = min(1.0, self.adaptive_system['enemy_ai_accuracy'] + 0.03)

        # Increase challenge if score is too close
        if abs(red_win_rate - blue_win_rate) < 0.1:
            self.adaptive_system['powerup_frequency'] = min(0.8, self.adaptive_system['powerup_frequency'] + 0.02)
            self.adaptive_system['hazard_frequency'] = min(0.6, self.adaptive_system['hazard_frequency'] + 0.02)
            self.adaptive_system['objective_count'] = min(5, self.adaptive_system['objective_count'] + 1)
        else:
            # Reduce challenge if one team is dominating
            self.adaptive_system['powerup_frequency'] = max(0.3, self.adaptive_system['powerup_frequency'] - 0.01)
            self.adaptive_system['hazard_frequency'] = max(0.2, self.adaptive_system['hazard_frequency'] - 0.01)
            self.adaptive_system['objective_count'] = max(2, self.adaptive_system['objective_count'] - 1)

