            if robot.team != Team.RED:  # Enemy robots (blue)
                robot.weapon.range = 200 + (self.adaptive_system['enemy_ai_accuracy'] * 100)
                robot.visual_range = 300 + (self.adaptive_system['enemy_ai_aggressiveness'] * 150)
