    ammo: int
    max_ammo: int
    reload_time: float = 2.0
    is_melee: bool = False

    def __post_init__(self):
        self.ammo_left = self.ammo
        self.last_fired = 0.0

@dataclass
class Robot:
    id: str
    team: Team
    position: Vector2D
    health: float
    max_health: float
    speed: float
    role: RobotRole
    weapon: Weapon
    inventory: List[PowerUpType] = field(default_factory=list)
    cooldowns: Dict[str, float] = field(default_factory=dict)  # skill_name -> expiration_time
    vision_range: float = 150.0
    last_seen_enemies: List[str] = field(default_factory=list)
    knowledge_base: Dict[str, Any] = field(default_factory=dict)  # memory of past battles
    behavior_tree: Dict[str, Any] = field(default_factory=dict)
    target: Optional[Vector2D] = None
    is_active: bool = True
    score: int = 0
    team_contributions: Dict[str, int] = field(default_factory=lambda: defaultdict(int))

    def __post_init__(self):
        if not self.cooldowns:
            self.cooldowns = {
                "dash": 0.0,
                "ultimate": 0.0,
                "heal": 0.0
            }
        if not self.behavior_tree:
            self.behavior_tree = {
                "priority": ["objective", "engagement", "survival", "support"],
                "states": {}
            }

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team: Team
    captured_by: Optional[Team] = None
    progress: float = 0.0  # 0.0 to 1.0
    capture_rate: float = 0.01  # per tick
    radius: float = 30.0
    defenders: List[str] = field(default_factory=list)
    payload_speed: float = 0.5  # for escort objectives
    payload_destination: Optional[Vector2D] = None

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    active: bool = True
    duration: float = 10.0  # seconds
    value: float = 1.5  # multiplier for effect
    spawn_time: float = 0.0
    respawn_time: float = 30.0  # seconds before reappearing

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    visual_effect: str = "particle"

@dataclass
class GameState:
    time: float = 0.0
    match_duration: float = 300.0  # 5 minutes
    map_size: Vector2D = field(default_factory=lambda: Vector2D(1200, 800))
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    robots: List[Robot] = field(default_factory=list)
    winner: Optional[Team] = None
    round_history: List[Dict] = field(default_factory=list)
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    audio_events: List[str] = field(default_factory=list)
    visual_effects: List[Dict] = field(default_factory=list)
    difficulty_level: float = 0.5  # 0.0 to 1.0, 0.5 is medium
    learning_rate: float = 0.1  # how quickly robots adapt
    team_composition: Dict[Team, Dict[RobotRole, int]] = field(default_factory=lambda: {
        Team.RED: {role: 0 for role in RobotRole},
        Team.BLUE: {role: 0 for role in RobotRole}
    })

