# AUDIO AND VISUAL SYSTEM
# =======================

class AudioSystem:
    """Handles all sound effects and music"""

    def __init__(self):
        # In a real implementation, we'd use pygame.mixer
        # Here we simulate audio events
        self.sound_effects = {
            'shoot': 'pew_pew',
            'melee': 'clash',
            'explosion': 'boom',
            'powerup': 'ding',
            'capture': 'chime',
            'damage': 'hurt',
            'death': 'fatal',
            'objective_complete': 'victory',
            'team_win': 'win_theme'
        }
        self.volume = 0.7

    def play_sound(self, event: str, position: Optional[Vector2D] = None):
        """Simulate playing a sound effect"""
        if event in self.sound_effects:
            audio_event = f"{self.sound_effects[event]}_{random.randint(1,3)}"
            GameState().audio_events.append({
                'event': audio_event,
                'time': GameState().time,
                'position': position.to_tuple() if position else (0, 0),
                'volume': self.volume
            })

class VisualSystem:
    """Handles all visual effects and rendering"""

    def __init__(self):
        self.screen = pygame.display.set_mode((1200, 800))
        pygame.display.set_caption("CyberArena")
        self.font = pygame.font.SysFont('Arial', 16)
        self.clock = pygame.time.Clock()

        # Color palette
        self.colors = {
            Team.RED: (255, 50, 50),
            Team.BLUE: (50, 50, 255),
            Team.NEUTRAL: (150, 150, 150),
            'background': (10, 10, 20),
            'powerup': (255, 255, 0),
            'hazard': (200, 50, 0),
            'health': (50, 200, 50),
            'ui_text': (255, 255, 255),
            'selected': (255, 255, 0)
        }

        # Particle system
        self.particles = []

    def add_particle(self, position: Vector2D, color: Tuple[int, int, int], 
                    lifetime: float = 2.0, velocity: Optional[Vector2D] = None):
        """Add a visual particle"""
        if velocity is None:
            velocity = Vector2D(
                random.uniform(-1, 1) * 5,
                random.uniform(-1, 1) * 5
            )
        self.particles.append({
            'position': position.copy(),
            'color': color,
            'velocity': velocity,
            'lifetime': lifetime,
            'max_lifetime': lifetime,
            'size': random.randint(2, 6)
        })

    def update_particles(self):
        """Update all particles"""
        for particle in self.particles[:]:
            particle['position'] += particle['velocity']
            particle['lifetime'] -= 1/60.0  # Assuming 60 FPS
            particle['size'] = max(0, particle['size'] - 0.1)

            if particle['lifetime'] <= 0:
                self.particles.remove(particle)

    def render(self, game_state: GameState):
        """Render the entire game state"""
        # Clear screen
        self.screen.fill(self.colors['background'])

        # Render hazards
        for hazard in game_state.hazards:
            if hazard.active:
                color = self.colors['hazard']
                pygame.draw.circle(self.screen, color, hazard.position.to_tuple(), int(hazard.radius))
                # Add particle effects for hazards
                if hazard.type == HazardType.LAVA_POOL:
                    for _ in range(3):
                        self.add_particle(
                            hazard.position + Vector2D(random.uniform(-hazard.radius, hazard.radius), 
                                                     random.uniform(-hazard.radius, hazard.radius)),
                            (255, 100, 0), 
                            1.0,
                            Vector2D(random.uniform(-1, 1), random.uniform(-1, 1)) * 2
                        )
                elif hazard.type == HazardType.ELECTRIC_FLOOR:
                    for _ in range(2):
                        self.add_particle(
                            hazard.position + Vector2D(random.uniform(-hazard.radius, hazard.radius), 
                                                     random.uniform(-hazard.radius, hazard.radius)),
                            (100, 200, 255), 
                            0.8,
                            Vector2D(random.uniform(-2, 2), random.uniform(-2, 2)) * 3
                        )

        # Render power-ups
        for power_up in game_state.power_ups:
            if power_up.active:
                pygame.draw.circle(self.screen, self.colors['powerup'], power_up.position.to_tuple(), 10)
                pygame.draw.circle(self.screen, (255, 255, 255), power_up.position.to_tuple(), 12, 2)

                # Add a pulse effect
                pulse = math.sin(game_state.time * 3) * 2 + 10
                pygame.draw.circle(self.screen, self.colors['powerup'], power_up.position.to_tuple(), int(pulse), 1)

        # Render objectives
        for obj in game_state.objectives:
            if obj.type == ObjectiveType.CAPTURE_FLAG:
                color = self.colors[obj.team] if obj.captured_by else self.colors[Team.NEUTRAL]
                pygame.draw.circle(self.screen, color, obj.position.to_tuple(), int(obj.radius))
                pygame.draw.circle(self.screen, (255, 255, 255), obj.position.to_tuple(), int(obj.radius) + 2, 2)

                # Draw capture progress bar
                bar_width = int(obj.radius * 2 * obj.progress)
                pygame.draw.rect(self.screen, (0, 255, 0), 
                    [obj.position.x - obj.radius, obj.position.y - obj.radius - 15, bar_width, 5])

            elif obj.type == ObjectiveType.ESCAPE_PAYLOAD:
                color = self.colors[obj.team]
                pygame.draw.circle(self.screen, color, obj.position.to_tuple(), 15)
                # Draw a small arrow pointing to destination if it has one
                if obj.payload_destination:
                    pygame.draw.line(self.screen, (200, 200, 200), 
                        obj.position.to_tuple(), obj.payload_destination.to_tuple(), 1)

        # Render robots
        for robot in game_state.robots:
            if robot.is_active:
                color = self.colors[robot.team]
                # Draw robot body
                pygame.draw.circle(self.screen, color, robot.position.to_tuple(), 12)

                # Draw robot role indicator (small icon)
                role_icon = {
                    RobotRole.ATTACKER: "A",
                    RobotRole.DEFENDER: "D",
                    RobotRole.SUPPORT: "S",
                    RobotRole.SCOUT: "C",
                    RobotRole.HEALER: "H"
                }
                icon_text = self.font.render(role_icon[robot.role], True, (255, 255, 255))
                self.screen.blit(icon_text, (robot.position.x - 4, robot.position.y - 6))

                # Draw health bar
                health_ratio = robot.health / robot.max_health
                bar_width = 20
                bar_height = 4
                pygame.draw.rect(self.screen, (255, 0, 0), 
                    [robot.position.x - bar_width//2, robot.position.y - 20, bar_width, bar_height])
                pygame.draw.rect(self.screen, (0, 255, 0), 
                    [robot.position.x - bar_width//2, robot.position.y - 20, bar_width * health_ratio, bar_height])

                # Draw target indicator if exists
                if robot.target:
                    pygame.draw.line(self.screen, (255, 255, 0), 
                        robot.position.to_tuple(), robot.target.to_tuple(), 1)
                    pygame.draw.circle(self.screen, (255, 255, 0), robot.target.to_tuple(), 5, 1)

                # Draw vision range
                pygame.draw.circle(self.screen, (100, 100, 200, 50), 
                    robot.position.to_tuple(), int(robot.vision_range), 1)

        # Render particles
        for particle in self.particles:
            alpha = particle['lifetime'] / particle['max_lifetime']
            color = [int(c * alpha) for c in particle['color']]
            pygame.draw.circle(self.screen, color, 
                particle['position'].to_tuple(), int(particle['size']))

        # Render UI
        self.render_ui(game_state)

        # Update display
        pygame.display.flip()

        # Cap at 60 FPS
        self.clock.tick(60)

    def render_ui(self, game_state: GameState):
        """Render user interface elements"""
        # Top bar: time and scores
        time_text = self.font.render(f"Time: {int(game_state.time // 60)}:{int(game_state.time % 60):02d}", True, self.colors['ui_text'])
        self.screen.blit(time_text, (10, 10))

        score_text = self.font.render(f"Red: {game_state.team_scores[Team.RED]} | Blue: {game_state.team_scores[Team.BLUE]}", True, self.colors['ui_text'])
        self.screen.blit(score_text, (10, 30))

        # Difficulty indicator
        difficulty_text = self.font.render(f"Difficulty: {int(game_state.difficulty_level * 100)}%", True, self.colors['ui_text'])
        self.screen.blit(difficulty_text, (10, 50))

        # Objective status
        for i, obj in enumerate(game_state.objectives):
            status = f"{obj.type.value}: {obj.captured_by.value if obj.captured_by else 'Neutral'}"
            if obj.progress > 0 and obj.progress < 1:
                status += f" ({int(obj.progress * 100)}%)"
            obj_text = self.font.render(status, True, self.colors[obj.team] if obj.captured_by else self.colors[Team.NEUTRAL])
            self.screen.blit(obj_text, (10, 70 + i * 20))

        # Audio events display
        if len(game_state.audio_events) > 0:
            last_event = game_state.audio_events[-1]
            event_text = self.font.render(f"Audio: {last_event['event']}", True, (200, 200, 0))
            self.screen.blit(event_text, (10, 650))

        # Robot count by team
        red_count = sum(1 for r in game_state.robots if r.team == Team.RED and r.is_active)
        blue_count = sum(1 for r in game_state.robots if r.team == Team.BLUE and r.is_active)
        count_text = self.font.render(f"Red Robots: {red_count} | Blue Robots: {blue_count}", True, self.colors['ui_text'])
        self.screen.blit(count_text, (10, 680))

# =======================
# AI BEHAVIOR SYSTEM
# =======================

class BehaviorTree:
    """Hierarchical behavior system for robots"""

    def __init__(self, robot: Robot):
        self.robot = robot
        self.root = self.build_tree()

    def build_tree(self):
        """Build behavior tree for the robot based on its role"""
        # For simplicity, we'll use a priority-based approach
        # Higher priority nodes execute first

        if self.robot.role == RobotRole.ATTACKER:
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "attack"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_objective_in_range"},
                            {"type": "action", "action": "capture_objective"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "patrol"
                    }
                ]
            }
        elif self.robot.role == RobotRole.DEFENDER:
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "objective_under_attack"},
                            {"type": "action", "action": "defend_objective"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "attack"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "patrol_objective"
                    }
                ]
            }
        elif self.robot.role == RobotRole.SUPPORT:
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "ally_needs_healing"},
                            {"type": "action", "action": "heal_ally"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "support_attack"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "patrol"
                    }
                ]
            }
        elif self.robot.role == RobotRole.SCOUT:
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "attack"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "objective_in_sight"},
                            {"type": "action", "action": "report_objective"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "explore"
                    }
                ]
            }
        else:  # HEALER
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "ally_needs_healing"},
                            {"type": "action", "action": "heal_ally"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "defend_self"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "patrol"
                    }
                ]
            }

    def execute(self, game_state: GameState) -> str:
        """Execute the behavior tree and return the action taken"""

        def evaluate_node(node):
            if node["type"] == "selector":
                for child in node["children"]:
                    result = evaluate_node(child)
                    if result != "failure":
                        return result
                return "failure"

            elif node["type"] == "sequence":
                for child in node["children"]:
                    result = evaluate_node(child)
                    if result == "failure":
                        return "failure"
                return "success"

            elif node["type"] == "condition":
                if node["check"] == "has_target_enemy":
                    # Find nearest enemy in range
                    for robot in game_state.robots:
                        if robot.team != self.robot.team and robot.is_active:
                            if self.robot.position.distance_to(robot.position) <= self.robot.vision_range:
                                self.robot.target = robot.position
                                self.robot.last_seen_enemies.append(robot.id)
                                return "success"
                    return "failure"

                elif node["check"] == "has_objective_in_range":
                    for obj in game_state.objectives:
                        if obj.team == self.robot.team or obj.captured_by == self.robot.team:
                            if self.robot.position.distance_to(obj.position) <= 80:
                                self.robot.target = obj.position
                                return "success"
                    return "failure"

                elif node["check"] == "objective_under_attack":
                    for obj in game_state.objectives:
                        if obj.captured_by == self.robot.team:
                            # Check if any enemy is near objective
                            for robot in game_state.robots:
                                if robot.team != self.robot.team and robot.is_active:
                                    if robot.position.distance_to(obj.position) <= 60:
                                        self.robot.target = obj.position
                                        return "success"
                    return "failure"

                elif node["check"] == "low_health":
                    return self.robot.health < self.robot.max_health * 0.3

                elif node["check"] == "ally_needs_healing":
                    for robot in game_state.robots:
                        if robot.team == self.robot.team and robot.is_active:
                            if robot.health < robot.max_health * 0.6:
                                self.robot.target = robot.position
                                return "success"
                    return "failure"

                elif node["check"] == "objective_in_sight":
                    for obj in game_state.objectives:
                        if self.robot.position.distance_to(obj.position) <= self.robot.vision_range:
                            # Send information to teammates
                            self.robot.knowledge_base['objective_positions'] = getattr(self.robot.knowledge_base, 'objective_positions', {})
                            self.robot.knowledge_base['objective_positions'][obj.type.value] = obj.position
                            return "success"
                    return "failure"

            elif node["type"] == "action":
                if node["action"] == "attack":
                    nearest_enemy = None
                    min_dist = float('inf')
                    for robot in game_state.robots:
                        if robot.team != self.robot.team and robot.is_active:
                            dist = self.robot.position.distance_to(robot.position)
                            if dist < min_dist and dist <= self.robot.weapon.range:
                                min_dist = dist
                                nearest_enemy = robot

                    if nearest_enemy:
                        # Fire weapon
                        current_time = game_state.time
                        if current_time - self.robot.weapon.last_fired >= self.robot.weapon.fire_rate:
                            if self.robot.weapon.ammo_left > 0:
                                self.robot.weapon.last_fired = current_time
                                self.robot.weapon.ammo_left -= 1
                                # Apply damage
                                damage = self.robot.weapon.damage
                                if self.robot.weapon.is_melee:
                                    damage *= 2  # Melee bonus
                                nearest_enemy.health -= damage
                                # Play sound
                                audio_system = AudioSystem()
                                audio_system.play_sound('shoot')
                                # Add particle effect
                                visual_system = VisualSystem()
                                visual_system.add_particle(
                                    self.robot.position, 
                                    (255, 255, 0), 
                                    0.5, 
                                    (nearest_enemy.position - self.robot.position).normalize() * 5
                                )
                                # Add to score
                                self.robot.team_contributions['kills'] += 1
                                if nearest_enemy.health <= 0:
                                    self.robot.score += 100
                                    nearest_enemy.is_active = False
                                    audio_system.play_sound('death')
                                    visual_system.add_particle(nearest_enemy.position, (255, 0, 0), 1.5)
                                return "success"
                            else:
                                # Reload
                                if current_time - self.robot.weapon.last_fired >= self.robot.weapon.reload_time:
                                    self.robot.weapon.ammo_left = self.robot.weapon.max_ammo
                        return "success"
                    return "failure"

                elif node["action"] == "capture_objective":
                    for obj in game_state.objectives:
                        if self.robot.position.distance_to(obj.position) <= obj.radius:
                            # Start capturing
                            if obj.captured_by == self.robot.team:
                                # Defend
                                obj.progress = 1.0
                            elif obj.captured_by == None:
                                # Neutral
                                obj.progress += obj.capture_rate
                                if obj.progress >= 1.0:
                                    obj.captured_by = self.robot.team
                                    audio_system = AudioSystem()
                                    audio_system.play_sound('capture')
                                    visual_system = VisualSystem()
                                    visual_system.add_particle(obj.position, self.colors[obj.team], 1.0)
                                    # Award points
                                    game_state.team_scores[self.robot.team] += 50
                                    if obj.type == ObjectiveType.CAPTURE_FLAG:
                                        game_state.team_scores[self.robot.team] += 100
                                    self.robot.score += 50
                                    self.robot.team_contributions['captures'] += 1
                                    return "success"
                            elif obj.captured_by != self.robot.team:
                                # Enemy held
                                # Reduce their progress
                                obj.progress -= obj.capture_rate * 0.5
                                if obj.progress <= 0:
                                    obj.captured_by = self.robot.team
                                    audio_system = AudioSystem()
                                    audio_system.play_sound('capture')
                                    visual_system = VisualSystem()
                                    visual_system.add_particle(obj.position, self.colors[obj.team], 1.0)
                                    game_state.team_scores[self.robot.team] += 50
                                    self.robot.score += 50
                                    self.robot.team_contributions['captures'] += 1
                                    return "success"
                    return "failure"

                elif node["action"] == "defend_objective":
                    for obj in game_state.objectives:
                        if obj.captured_by == self.robot.team:
                            # Move toward objective
                            self.robot.target = obj.position
                            # If enemy is near, attack
                            for robot in game_state.robots:
                                if robot.team != self.robot.team and robot.is_active:
                                    if robot.position.distance_to(obj.position) <= 60:
                                        self.robot.target = robot.position
                                        return "success"
                            return "success"
                    return "failure"

                elif node["action"] == "retreat":
                    # Find safe location
                    safe_distance = 200
                    for obj in game_state.objectives:
                        if obj.captured_by == self.robot.team:
                            # Retreat toward objective
                            self.robot.target = obj.position
                            return "success"

                    # Find away from enemies
                    away_direction = Vector2D(0, 0)
                    enemy_count = 0
                    for robot in game_state.robots:
                        if robot.team != self.robot.team and robot.is_active:
                            if robot.position.distance_to(self.robot.position) <= 100:
                                away_direction += (self.robot.position - robot.position).normalize()
                                enemy_count += 1
                    if enemy_count > 0:
