                color = self.colors[obj.team] if obj.captured_by else self.colors[Team.NEUTRAL]
                pygame.draw.circle(self.screen, color, obj.position.to_tuple(), int(obj.radius))
                pygame.draw.circle(self.screen, (255, 255, 255), obj.position.to_tuple(), int(obj.radius) + 2, 2)

                # Draw capture progress bar
                bar_width = int(obj.radius * 2 * obj.progress)
                pygame.draw.rect(self.screen, (0, 255, 0), 
                    [obj.position.x - obj.radius, obj.position.y - obj.radius - 15, bar_width, 5])

            elif obj.type == ObjectiveType.ESCAPE_PAYLOAD:
                color = self.colors[obj.team]
                pygame.draw.circle(self.screen, color, obj.position.to_tuple(), 15)
                # Draw a small arrow pointing to destination if it has one
                if obj.payload_destination:
                    pygame.draw.line(self.screen, (200, 200, 200), 
                        obj.position.to_tuple(), obj.payload_destination.to_tuple(), 1)

        # Render robots
        for robot in game_state.robots:
            if robot.is_active:
                color = self.colors[robot.team]
                # Draw robot body
                pygame.draw.circle(self.screen, color, robot.position.to_tuple(), 12)

                # Draw robot role indicator (small icon)
                role_icon = {
                    RobotRole.ATTACKER: "A",
                    RobotRole.DEFENDER: "D",
                    RobotRole.SUPPORT: "S",
                    RobotRole.SCOUT: "C",
                    RobotRole.HEALER: "H"
                }
                icon_text = self.font.render(role_icon[robot.role], True, (255, 255, 255))
                self.screen.blit(icon_text, (robot.position.x - 4, robot.position.y - 6))

                # Draw health bar
                health_ratio = robot.health / robot.max_health
                bar_width = 20
                bar_height = 4
                pygame.draw.rect(self.screen, (255, 0, 0), 
                    [robot.position.x - bar_width//2, robot.position.y - 20, bar_width, bar_height])
                pygame.draw.rect(self.screen, (0, 255, 0), 
                    [robot.position.x - bar_width//2, robot.position.y - 20, bar_width * health_ratio, bar_height])

                # Draw target indicator if exists
                if robot.target:
                    pygame.draw.line(self.screen, (255, 255, 0), 
                        robot.position.to_tuple(), robot.target.to_tuple(), 1)
                    pygame.draw.circle(self.screen, (255, 255, 0), robot.target.to_tuple(), 5, 1)

                # Draw vision range
                pygame.draw.circle(self.screen, (100, 100, 200, 50), 
                    robot.position.to_tuple(), int(robot.vision_range), 1)

        # Render particles
        for particle in self.particles:
            alpha = particle['lifetime'] / particle['max_lifetime']
            color = [int(c * alpha) for c in particle['color']]
            pygame.draw.circle(self.screen, color, 
                particle['position'].to_tuple(), int(particle['size']))

        # Render UI
        self.render_ui(game_state)

        # Update display
        pygame.display.flip()

        # Cap at 60 FPS
        self.clock.tick(60)

    def render_ui(self, game_state: GameState):
        """Render user interface elements"""
        # Top bar: time and scores
        time_text = self.font.render(f"Time: {int(game_state.time // 60)}:{int(game_state.time % 60):02d}", True, self.colors['ui_text'])
        self.screen.blit(time_text, (10, 10))

        score_text = self.font.render(f"Red: {game_state.team_scores[Team.RED]} | Blue: {game_state.team_scores[Team.BLUE]}", True, self.colors['ui_text'])
        self.screen.blit(score_text, (10, 30))

        # Difficulty indicator
        difficulty_text = self.font.render(f"Difficulty: {int(game_state.difficulty_level * 100)}%", True, self.colors['ui_text'])
        self.screen.blit(difficulty_text, (10, 50))
        # Difficulty indicator
        difficulty_text = self.font.render(f"Difficulty: {int(game_state.difficulty_level * 100)}%", True, self.colors['ui_text'])
        self.screen.blit(difficulty_text, (10, 50))

        # Difficulty effect indicators
        if game_state.difficulty_level > 0.6:
            difficulty_effect = self.font.render("↑ HIGH AGGRESSION", True, (255, 0, 0))
            self.screen.blit(difficulty_effect, (10, 70))
        elif game_state.difficulty_level < 0.4:
            difficulty_effect = self.font.render("↓ LOW AGGRESSION", True, (0, 255, 0))
            self.screen.blit(difficulty_effect, (10, 70))

        # Objective status
        for i, obj in enumerate(game_state.objectives):
            status = f"{obj.type.value}: {obj.captured_by.value if obj.captured_by else 'Neutral'}"
            if obj.progress > 0 and obj.progress < 1:
                status += f" ({int(obj.progress * 100)}%)"
            obj_text = self.font.render(status, True, self.colors[obj.team] if obj.captured_by else self.colors[Team.NEUTRAL])
            self.screen.blit(obj_text, (10, 70 + i * 20))

        # Audio events display
        if len(game_state.audio_events) > 0:
            last_event = game_state.audio_events[-1]
            event_text = self.font.render(f"Audio: {last_event['event']}", True, (200, 200, 0))
            self.screen.blit(event_text, (10, 650))

        # Robot count by team
        red_count = sum(1 for r in game_state.robots if r.team == Team.RED and r.is_active)
        blue_count = sum(1 for r in game_state.robots if r.team == Team.BLUE and r.is_active)
        count_text = self.font.render(f"Red Robots: {red_count} | Blue Robots: {blue_count}", True, self.colors['ui_text'])
        self.screen.blit(count_text, (10, 680))

