# AI BEHAVIOR SYSTEM
# =======================

class BehaviorTree:
    """Hierarchical behavior system for robots"""

    def __init__(self, robot: Robot):
        self.robot = robot
        self.root = self.build_tree()

    def build_tree(self):
        """Build behavior tree for the robot based on its role"""
        # For simplicity, we'll use a priority-based approach
        # Higher priority nodes execute first

        if self.robot.role == RobotRole.ATTACKER:
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "attack"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_objective_in_range"},
                            {"type": "action", "action": "capture_objective"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "patrol"
                    }
                ]
            }
        elif self.robot.role == RobotRole.DEFENDER:
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "objective_under_attack"},
                            {"type": "action", "action": "defend_objective"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "attack"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "patrol_objective"
                    }
                ]
            }
        elif self.robot.role == RobotRole.SUPPORT:
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "ally_needs_healing"},
                            {"type": "action", "action": "heal_ally"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "support_attack"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "patrol"
                    }
                ]
            }
        elif self.robot.role == RobotRole.SCOUT:
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "attack"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "objective_in_sight"},
                            {"type": "action", "action": "report_objective"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "explore"
                    }
                ]
            }
        else:  # HEALER
            return {
                "type": "selector",
                "children": [
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "ally_needs_healing"},
                            {"type": "action", "action": "heal_ally"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "has_target_enemy"},
                            {"type": "action", "action": "defend_self"}
                        ]
                    },
                    {
                        "type": "sequence",
                        "children": [
                            {"type": "condition", "check": "low_health"},
                            {"type": "action", "action": "retreat"}
                        ]
                    },
                    {
                        "type": "action", "action": "patrol"
                    }
                ]
            }

    def execute(self, game_state: GameState) -> str:
        """Execute the behavior tree and return the action taken"""

        def evaluate_node(node):
            if node["type"] == "selector":
                for child in node["children"]:
                    result = evaluate_node(child)
                    if result != "failure":
                        return result
                return "failure"

            elif node["type"] == "sequence":
                for child in node["children"]:
                    result = evaluate_node(child)
                    if result == "failure":
                        return "failure"
                return "success"

            elif node["type"] == "condition":
                if node["check"] == "has_target_enemy":
                    # Find nearest enemy in range
                    for robot in game_state.robots:
                        if robot.team != self.robot.team and robot.is_active:
                            if self.robot.position.distance_to(robot.position) <= self.robot.vision_range:
                                self.robot.target = robot.position
                                self.robot.last_seen_enemies.append(robot.id)
                                return "success"
                    return "failure"

                elif node["check"] == "has_objective_in_range":
                    for obj in game_state.objectives:
                        if obj.team == self.robot.team or obj.captured_by == self.robot.team:
                            if self.robot.position.distance_to(obj.position) <= 80:
                                self.robot.target = obj.position
                                return "success"
                    return "failure"

                elif node["check"] == "objective_under_attack":
                    for obj in game_state.objectives:
                        if obj.captured_by == self.robot.team:
                            # Check if any enemy is near objective
                            for robot in game_state.robots:
                                if robot.team != self.robot.team and robot.is_active:
                                    if robot.position.distance_to(obj.position) <= 60:
                                        self.robot.target = obj.position
                                        return "success"
                    return "failure"

                elif node["check"] == "low_health":
                    return self.robot.health < self.robot.max_health * 0.3

                elif node["check"] == "ally_needs_healing":
                    for robot in game_state.robots:
                        if robot.team == self.robot.team and robot.is_active:
                            if robot.health < robot.max_health * 0.6:
                                self.robot.target = robot.position
                                return "success"
                    return "failure"

                elif node["check"] == "objective_in_sight":
                    for obj in game_state.objectives:
                        if self.robot.position.distance_to(obj.position) <= self.robot.vision_range:
                            # Send information to teammates
                            self.robot.knowledge_base['objective_positions'] = getattr(self.robot.knowledge_base, 'objective_positions', {})
                            self.robot.knowledge_base['objective_positions'][obj.type.value] = obj.position
                            return "success"
                    return "failure"

            elif node["type"] == "action":
                if node["action"] == "attack":
                    nearest_enemy = None
                    min_dist = float('inf')
                    for robot in game_state.robots:
                        if robot.team != self.robot.team and robot.is_active:
                            dist = self.robot.position.distance_to(robot.position)
                            if dist < min_dist and dist <= self.robot.weapon.range:
                                min_dist = dist
                                nearest_enemy = robot

                    if nearest_enemy:
                        # Fire weapon
                        current_time = game_state.time
                        if current_time - self.robot.weapon.last_fired >= self.robot.weapon.fire_rate:
                            if self.robot.weapon.ammo_left > 0:
                                self.robot.weapon.last_fired = current_time
                                self.robot.weapon.ammo_left -= 1
                                # Apply damage
                                damage = self.robot.weapon.damage
                                if self.robot.weapon.is_melee:
                                    damage *= 2  # Melee bonus
                                nearest_enemy.health -= damage
                                # Play sound
                                audio_system = AudioSystem()
                                audio_system.play_sound('shoot')
                                # Add particle effect
                                visual_system = VisualSystem()
                                visual_system.add_particle(
                                    self.robot.position, 
                                    (255, 255, 0), 
                                    0.5, 
                                    (nearest_enemy.position - self.robot.position).normalize() * 5
                                )
                                # Add to score
                                self.robot.team_contributions['kills'] += 1
                                if nearest_enemy.health <= 0:
                                    self.robot.score += 100
                                    nearest_enemy.is_active = False
                                    audio_system.play_sound('death')
                                    visual_system.add_particle(nearest_enemy.position, (255, 0, 0), 1.5)
                                return "success"
                            else:
                                # Reload
                                if current_time - self.robot.weapon.last_fired >= self.robot.weapon.reload_time:
                                    self.robot.weapon.ammo_left = self.robot.weapon.max_ammo
                        return "success"
                    return "failure"

                elif node["action"] == "capture_objective":
                    for obj in game_state.objectives:
                        if self.robot.position.distance_to(obj.position) <= obj.radius:
                            # Start capturing
                            if obj.captured_by == self.robot.team:
                                # Defend
                                obj.progress = 1.0
                            elif obj.captured_by == None:
                                # Neutral
                                obj.progress += obj.capture_rate
                                if obj.progress >= 1.0:
                                    obj.captured_by = self.robot.team
                                    audio_system = AudioSystem()
                                    audio_system.play_sound('capture')
                                    visual_system = VisualSystem()
                                    visual_system.add_particle(obj.position, self.colors[obj.team], 1.0)
                                    # Award points
                                    game_state.team_scores[self.robot.team] += 50
                                    if obj.type == ObjectiveType.CAPTURE_FLAG:
                                        game_state.team_scores[self.robot.team] += 100
                                    self.robot.score += 50
                                    self.robot.team_contributions['captures'] += 1
                                    return "success"
                            elif obj.captured_by != self.robot.team:
                                # Enemy held
                                # Reduce their progress
                                obj.progress -= obj.capture_rate * 0.5
                                if obj.progress <= 0:
                                    obj.captured_by = self.robot.team
                                    audio_system = AudioSystem()
                                    audio_system.play_sound('capture')
                                    visual_system = VisualSystem()
                                    visual_system.add_particle(obj.position, self.colors[obj.team], 1.0)
                                    game_state.team_scores[self.robot.team] += 50
                                    self.robot.score += 50
                                    self.robot.team_contributions['captures'] += 1
                                    return "success"
                    return "failure"

                elif node["action"] == "defend_objective":
                    for obj in game_state.objectives:
                        if obj.captured_by == self.robot.team:
                            # Move toward objective
                            self.robot.target = obj.position
                            # If enemy is near, attack
                            for robot in game_state.robots:
                                if robot.team != self.robot.team and robot.is_active:
                                    if robot.position.distance_to(obj.position) <= 60:
                                        self.robot.target = robot.position
                                        return "success"
                            return "success"
                    return "failure"

                elif node["action"] == "retreat":
                    # Find safe location
                    safe_distance = 200
                    for obj in game_state.objectives:
                        if obj.captured_by == self.robot.team:
                            # Retreat toward objective
                            self.robot.target = obj.position
                            return "success"

                    # Find away from enemies
                    away_direction = Vector2D(0, 0)
                    enemy_count = 0
                    for robot in game_state.robots:
                        if robot.team != self.robot.team and robot.is_active:
                            if robot.position.distance_to(self.robot.position) <= 100:
                                away_direction += (self.robot.position - robot.position).normalize()
                                enemy_count += 1
                    if enemy_count > 0:
                        away_direction = away_direction.normalize() * safe_distance
                        self.robot.target = self.robot.position + away_direction
                        return "success"
                    return "failure"

                elif node["action"] == "patrol":
                    # Patrol a fixed point
                    if not hasattr(self.robot, 'patrol_point'):
                        # Generate patrol point
                        self.robot.patrol_point = Vector2D(
                            random.randint(100, game_state.map_size.x - 100),
                            random.randint(100, game_state.map_size.y - 100)
                        )

                    # Move toward patrol point
                    self.robot.target = self.robot.patrol_point
                    if self.robot.position.distance_to(self.robot.patrol_point) < 20:
                        # Generate new patrol point
                        self.robot.patrol_point = Vector2D(
                            random.randint(100, game_state.map_size.x - 100),
                            random.randint(100, game_state.map_size.y - 100)
                        )
                    return "success"

                elif node["action"] == "patrol_objective":
                    if game_state.objectives:
                        # Patrol around an objective
                        obj = game_state.objectives[0]
                        # Find point around objective
                        angle = (game_state.time % 10) * 0.1
                        radius = 80
                        self.robot.target = Vector2D(
                            obj.position.x + math.cos(angle) * radius,
                            obj.position.y + math.sin(angle) * radius
                        )
                        return "success"
                    return "failure"

                elif node["action"] == "heal_ally":
                    for robot in game_state.robots:
                        if robot.team == self.robot.team and robot.is_active and robot.health < robot.max_health * 0.6:
                            # Use healing ability
                            if game_state.time - self.robot.cooldowns.get("heal", 0) > 10:
                                # Heal ally
