class BlendMode(Enum):
    NORMAL = "normal"
    MULTIPLY = "multiply"
    SCREEN = "screen"
    OVERLAY = "overlay"
    SOFT_LIGHT = "soft_light"
    HARD_LIGHT = "hard_light"
    DARKEN = "darken"
    LIGHTEN = "lighten"

@dataclass
class Layer:
    name: str
    image: Image.Image  # PIL Image object
    opacity: float = 1.0  # 0.0 to 1.0
    visible: bool = True
    position: Tuple[int, int] = (0, 0)  # (x, y) top-left corner
    blend_mode: BlendMode = BlendMode.NORMAL
    filters: List[str] = field(default_factory=list)  # List of applied filter names

    def clone(self) -> 'Layer':
        return Layer(
            name=self.name,
            image=self.image.copy(),
            opacity=self.opacity,
            visible=self.visible,
            position=self.position,
            blend_mode=self.blend_mode,
            filters=self.filters.copy()
        )

@dataclass
class Project:
    layers: List[Layer] = field(default_factory=list)
    canvas_size: Tuple[int, int] = (1920, 1080)
    background_color: Tuple[int, int, int] = (255, 255, 255)  # White

    def add_layer(self, layer: Layer) -> None:
        self.layers.append(layer)

    def remove_layer(self, index: int) -> None:
        if 0 <= index < len(self.layers):
            self.layers.pop(index)

    def reorder_layer(self, old_index: int, new_index: int) -> None:
        if 0 <= old_index < len(self.layers) and 0 <= new_index < len(self.layers):
            layer = self.layers.pop(old_index)
            self.layers.insert(new_index, layer)

    def get_composite_image(self) -> Image.Image:
        # Create base canvas
        canvas = Image.new('RGBA', self.canvas_size, self.background_color + (255,))

        for layer in self.layers:
            if not layer.visible:
                continue

            # Create a copy of the layer image
            layer_img = layer.image.convert('RGBA')

            # Apply opacity
            if layer.opacity < 1.0:
                alpha = layer_img.split()[-1]
                alpha = ImageEnhance.Brightness(alpha).enhance(layer.opacity)
                layer_img.putalpha(alpha)

            # Apply filters
            for filter_name in layer.filters:
                layer_img = self._apply_filter(layer_img, filter_name)

            # Apply blending
            if layer.blend_mode != BlendMode.NORMAL:
                canvas = self._blend_layers(canvas, layer_img, layer.blend_mode)
            else:
                # Normal blend: paste with alpha
                canvas.alpha_composite(layer_img, layer.position)

        return canvas.convert('RGB')

    def _apply_filter(self, img: Image.Image, filter_name: str) -> Image.Image:
        if filter_name == "blur":
            return img.filter(ImageFilter.GaussianBlur(radius=2))
        elif filter_name == "sharpen":
            return img.filter(ImageFilter.SHARPEN)
        elif filter_name == "brightness_increase":
            return ImageEnhance.Brightness(img).enhance(1.5)
        elif filter_name == "brightness_decrease":
            return ImageEnhance.Brightness(img).enhance(0.7)
        elif filter_name == "contrast_increase":
            return ImageEnhance.Contrast(img).enhance(1.5)
        elif filter_name == "contrast_decrease":
            return ImageEnhance.Contrast(img).enhance(0.7)
        elif filter_name == "saturation_increase":
            return ImageEnhance.Color(img).enhance(1.5)
        elif filter_name == "saturation_decrease":
            return ImageEnhance.Color(img).enhance(0.7)
        else:
            return img  # Unknown filter, return unmodified

    def _blend_layers(self, base: Image.Image, overlay: Image.Image, mode: BlendMode) -> Image.Image:
        # Convert to numpy arrays for blending
        base_np = np.array(base)
        overlay_np = np.array(overlay)

        # Extract alpha channel from overlay
        alpha = overlay_np[:, :, 3] / 255.0

        # Expand alpha to 3 channels for RGB blending
        alpha_3d = np.expand_dims(alpha, axis=-1)

        if mode == BlendMode.MULTIPLY:
            blended = base_np[:, :, :3] * (overlay_np[:, :, :3] / 255.0)
        elif mode == BlendMode.SCREEN:
            blended = 255 - ((255 - base_np[:, :, :3]) * (255 - overlay_np[:, :, :3]) / 255.0)
        elif mode == BlendMode.OVERLAY:
            mask_low = base_np[:, :, :3] < 128
            mask_high = base_np[:, :, :3] >= 128
            blended = np.zeros_like(base_np[:, :, :3], dtype=np.float64)
            blended[mask_low] = (2 * base_np[:, :, :3][mask_low] * overlay_np[:, :, :3][mask_low] / 255.0)
            blended[mask_high] = (255 - 2 * (255 - base_np[:, :, :3][mask_high]) * (255 - overlay_np[:, :, :3][mask_high]) / 255.0)
