@dataclass
class Vector2D:
    """2D Position and Velocity Vector"""
    x: float = 0.0
    y: float = 0.0

    def distance_to(self, other: 'Vector2D') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def normalize(self) -> 'Vector2D':
        mag = math.sqrt(self.x**2 + self.y**2)
        if mag > 0:
            return Vector2D(self.x/mag, self.y/mag)
        return Vector2D(0, 0)

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __rmul__(self, scalar):
        return self.__mul__(scalar)

@dataclass
class Robot:
    """Represents a single AI-controlled robot in the arena"""
    id: str
    team: Team
    robot_type: RobotType
    position: Vector2D
    health: float = 100.0
    max_health: float = 100.0
    energy: float = 100.0
    max_energy: float = 100.0
    speed: float = 5.0
    weapon: Optional['Weapon'] = None
    abilities: List['Ability'] = field(default_factory=list)
    role: str = "default"
    last_action_time: float = 0.0
    last_seen_enemy: Optional[str] = None
    objectives: List[ObjectiveType] = field(default_factory=list)
    memory: Dict[str, Any] = field(default_factory=dict)
    is_active: bool = True

    def __post_init__(self):
        if not self.weapon:
            self.weapon = Weapon(WeaponType.RANGED, damage=25, cooldown=1.5, range=150)

    def take_damage(self, amount: float) -> bool:
        """Apply damage to the robot and return True if killed"""
        self.health = max(0, self.health - amount)
        if self.health <= 0:
            self.is_active = False
            logger.info(f"Robot {self.id} ({self.team.value}) has been eliminated!")
            return True
        return False

    def heal(self, amount: float):
        """Heal the robot"""
        self.health = min(self.max_health, self.health + amount)

    def consume_energy(self, amount: float) -> bool:
        """Consume energy and return True if enough energy available"""
        if self.energy >= amount:
            self.energy -= amount
            return True
        return False

    def regenerate_energy(self, rate: float, delta_time: float):
        """Regenerate energy over time"""
        self.energy = min(self.max_energy, self.energy + rate * delta_time)

    def update_memory(self, key: str, value: Any):
        """Update robot's memory for learning"""
        self.memory[key] = value

    def get_memory(self, key: str, default=None) -> Any:
        """Retrieve from memory"""
        return self.memory.get(key, default)

    def get_state(self) -> Dict:
        """Return a serializable state representation"""
        return {
            "id": self.id,
            "team": self.team.value,
            "robot_type": self.robot_type.value,
            "position": {"x": self.position.x, "y": self.position.y},
            "health": self.health,
            "energy": self.energy,
            "speed": self.speed,
            "weapon": self.weapon.get_state() if self.weapon else None,
            "abilities": [ab.get_state() for ab in self.abilities],
            "role": self.role,
            "is_active": self.is_active,
            "memory": self.memory
        }

@dataclass
class Weapon:
    """Represents a weapon a robot can use"""
    weapon_type: WeaponType
    damage: float
    cooldown: float
    range: float
    ammo: Optional[int] = None
    max_ammo: Optional[int] = None
    fire_rate: float = 1.0  # shots per second
    last_fired: float = 0.0

    def can_fire(self, current_time: float) -> bool:
        """Check if weapon can fire based on cooldown"""
        return current_time - self.last_fired >= self.cooldown

    def fire(self, current_time: float) -> bool:
        """Fire the weapon, return success"""
        if self.can_fire(current_time):
            self.last_fired = current_time
            return True
        return False

    def get_state(self) -> Dict:
        """Return serializable weapon state"""
        return {
            "type": self.weapon_type.value,
            "damage": self.damage,
            "cooldown": self.cooldown,
            "range": self.range,
            "ammo": self.ammo,
            "max_ammo": self.max_ammo,
            "fire_rate": self.fire_rate,
            "last_fired": self.last_fired
        }

@dataclass
class Ability:
    """Represents a special ability a robot can use"""
    name: str
    cooldown: float
    duration: float
    effect: str  # e.g., "heal", "speed_boost", "invisibility"
    power: float  # magnitude of effect
    last_used: float = 0.0
    is_active: bool = False
    activation_time: float = 0.0

    def can_use(self, current_time: float) -> bool:
        """Check if ability is off cooldown"""
        return current_time - self.last_used >= self.cooldown

    def use(self, current_time: float) -> bool:
        """Use the ability, return success"""
        if self.can_use(current_time):
            self.last_used = current_time
            self.is_active = True
            self.activation_time = current_time
            return True
        return False

    def update(self, current_time: float):
        """Update ability state"""
        if self.is_active and current_time - self.activation_time >= self.duration:
            self.is_active = False

    def get_state(self) -> Dict:
        """Return serializable ability state"""
        return {
            "name": self.name,
            "cooldown": self.cooldown,
            "duration": self.duration,
            "effect": self.effect,
            "power": self.power,
            "last_used": self.last_used,
            "is_active": self.is_active,
            "activation_time": self.activation_time
        }

