class CyberArena:
    """Main CyberArena game engine"""

    def __init__(self, num_robots_per_team: int = 4):
        self.game_state = GameState(
            robots=[],
            objectives=[],
            power_ups=[],
            hazards=[],
            spawn_points={
                Team.RED: [Vector2D(100, 100), Vector2D(100, 400)],
                Team.BLUE: [Vector2D(400, 100), Vector2D(400, 400)]
            }
        )

        # Initialize subsystems
        self.adaptive_difficulty = AdaptiveDifficulty(self.game_state)
        self.learning_system = LearningSystem()
        self.audio_visual = AudioVisualSystem()

        # Game configuration
        self.arena_size = Vector2D(500, 500)
        self.game_time_limit = 300.0  # 5 minutes
        self.spawn_cooldown = 10.0
        self.last_spawn_time = 0.0

        # Initialize robots
        self._initialize_robots(num_robots_per_team)

        # Initialize objectives
        self._initialize_objectives()

        # Initialize power-ups
        self._initialize_power_ups()

        # Initialize hazards
        self._initialize_hazards()

        # Game state tracking
        self.last_update_time = time.time()
        self.is_running = True

        logger.info(f"CyberArena initialized with {num_robots_per_team} robots per team")

    def _initialize_robots(self, num_per_team: int):
        """Initialize robots for both teams"""
        robot_ids = 0
        for team in [Team.RED, Team.BLUE]:
            for i in range(num_per_team):
                # Randomly assign robot type
                robot_type = random.choice(list(RobotType))

                # Pick a spawn point
                spawn_point = random.choice(self.game_state.spawn_points[team])

                # Create robot
                robot = Robot(
                    id=f"{team.value.lower()}_{robot_ids}",
                    team=team,
                    robot_type=robot_type,
                    position=spawn_point,
                    health=100,
                    max_health=100,
                    energy=100,
                    max_energy=100
                )

                # Assign weapon based on type
                if robot_type == RobotType.ASSAULT:
                    robot.weapon = Weapon(WeaponType.RANGED, damage=30, cooldown=1.2, range=160)
                elif robot_type == RobotType.SUPPORT:
                    robot.weapon = Weapon(WeaponType.RANGED, damage=20, cooldown=0.8, range=140)
                    robot.abilities.append(Ability("Heal", cooldown=15, duration=5, effect="heal", power=25))
                elif robot_type == RobotType.RECON:
                    robot.weapon = Weapon(WeaponType.RANGED, damage=25, cooldown=1.0, range=200)
